	-- (U8; the owner's Index renders: "UNCOMMON" cut on the phone tab) the rarity tabs are signboard tabs: at every grid size each
	-- tab that shows in the tab strip shows whole (never half under the strip's edge or the Elements button), and its name fits
	-- the tab at its own size, never cut or squeezed under 18 design px.
	-- U8 review (the after render listed "Uncommon", "Legendary" and "Fusions" overflowing at 1920x1080 while this passed):
	-- widths are FredokaOne's real ones (SmokeCommon.RealWidth; the mock's TextService is a flat 0.5 em), given to the
	-- window through IndexController.Metrics.MEASURE as the renderer does; a name's padding (the Fusions sparkle's inset)
	-- counts, with 2 px to spare; and the name's drawn text (with its lead icon) never meets the tab's count or its badge
	-- corner (the badge shows whenever a reward waits, so its place is kept free while it is hidden too)
	S.index_tabs_fit_phone = guarded("index_tabs_fit_phone", function()
		local Menu = U7.client("Controllers/MenuController")
		local IC = U7.client("Controllers/IndexController")
		local RealWidth = SmokeCommon.RealWidth
		local SPARE = 2
		local metrics = IC and type(IC.Metrics) == "table" and IC.Metrics or nil
		local savedMeasure = metrics and metrics.MEASURE
		if metrics then
			metrics.MEASURE = function(text, size, font)
				return RealWidth(text, size, font)
			end
		end
		-- a label's drawn text in its tab's own design px: the padded box, the text's real width placed by its alignment,
		-- one TextSize tall in the middle of the box
		local function local_(o, tab, sc)
			local p = (o.AbsolutePosition - tab.AbsolutePosition) / sc
			local z = o.AbsoluteSize / sc
			return { X = p.X, Y = p.Y, R = p.X + z.X, B = p.Y + z.Y }
		end
		local function textRect(label, tab, sc)
			local r = local_(label, tab, sc)
			local pad = label:FindFirstChildOfClass("UIPadding")
			local pl, pr = pad and pad.PaddingLeft.Offset or 0, pad and pad.PaddingRight.Offset or 0
			local pt, pb = pad and pad.PaddingTop.Offset or 0, pad and pad.PaddingBottom.Offset or 0
			local w = RealWidth(label.Text, label.TextSize, label.Font)
			local left, right = r.X + pl, r.R - pr
			local x = left
			if label.TextXAlignment == Enum.TextXAlignment.Right then
				x = right - w
			elseif label.TextXAlignment == Enum.TextXAlignment.Center then
				x = (left + right - w) / 2
			end
			local cy = r.Y + pt + (r.B - r.Y - pt - pb) / 2
			local out = { X = x, R = x + w, Y = cy - label.TextSize / 2, B = cy + label.TextSize / 2 }
			local lead = label:FindFirstChild("LeadIcon")
			if lead then
				local l = local_(lead, tab, sc)
				out.X, out.Y, out.B = math.min(out.X, l.X), math.min(out.Y, l.Y), math.max(out.B, l.B)
			end
			return out, w, pl + pr
		end
		for _, s in ipairs(U8.SIZES) do
			U8.at(s[1], s[2], s[3], "index tabs", function(tag)
				Menu.Open("Index")
				LKC.advance(1)
				local index = U8.pg():FindFirstChild("NimbusIndex")
				local list = index and index:FindFirstChild("GroupList", true)
				if not T.check(list ~= nil, tag .. ": the tab strip (GroupList) exists") then
					return
				end
				local view = U8.rect(list)
				local elements = index:FindFirstChild("ElementsButton", true)
				local cut, tight, seen, meets = {}, {}, 0, {}
				for _, tab in ipairs(list:GetDescendants()) do
					if tab.Name:match("^Group_") and tab:IsA("GuiButton") and U8.shown(tab) then
						local r = U8.rect(tab)
						if U8.overlap(r, view) then
							seen = seen + 1
							local inside = r.X >= view.X - 0.5 and r.R <= view.R + 0.5 and r.Y >= view.Y - 0.5 and r.B <= view.B + 0.5
							local under = elements and U8.shown(elements) and U8.overlap(r, U8.rect(elements))
							if not inside or under then
								cut[#cut + 1] = tab.Name .. " " .. U8.show(r)
							end
							local name = tab:FindFirstChild("GroupName", true)
							if name then
								local sc = U8.scaleOf(name)
								local rect, w, inset = textRect(name, tab, sc)
								local room = name.AbsoluteSize.X / sc
								if name.TextScaled or inset + w + SPARE > room + 0.01 or name.TextSize < 18 then
									tight[#tight + 1] = fmt("%s %q %.1f px + %d inset in %.1f at %s%s", tab.Name, name.Text, w, inset, room, tostring(name.TextSize),
										name.TextScaled and " (scaled)" or "")
								end
								for _, other in ipairs({ "Progress", "Badge" }) do
									local o = tab:FindFirstChild(other)
									if o then
										local r = other == "Progress" and (textRect(o, tab, sc)) or local_(o, tab, sc)
										if U8.overlap(rect, r) then
											meets[#meets + 1] = fmt("%s %q %s meets its %s %s", tab.Name, name.Text, U8.show(rect), other, U8.show(r))
										end
									end
								end
							end
						end
					end
				end
				T.check(seen >= 2, tag .. ": the strip shows at least two tabs", tostring(seen))
				T.check(#cut == 0, tag .. ": every tab in view shows whole (none half under the strip's edge or the Elements button)", table.concat(cut, "; ") .. " | view " .. U8.show(view))
				T.check(#tight == 0, tag .. ": every tab's name (with its lead icon's inset and 2 px to spare) fits it at a fixed size of 18 px or more, real FredokaOne widths",
					table.concat(tight, "; "))
				T.check(#meets == 0, tag .. ": no tab's name meets the tab's count or its badge corner", table.concat(meets, "; "))
			end)
		end
		if metrics then
			metrics.MEASURE = savedMeasure
		end
		LKC.flushErrors("index_tabs_fit_phone")
	end)

	-- (U8; the owner's Index renders: Claim under Roblox's jump button at 844x390) on a touch phone the Claim button never
	-- sits under the jump button: Roblox's touch controls go while the window is open (MenuController.SetTouchHidden, as the
	-- Pets window, the Shop and the Gifts window do), or the button is clear of the jump button's square; and they come back
	-- as they were on Close
	S.index_claim_clear_of_jump = guarded("index_claim_clear_of_jump", function()
		local Menu = U7.client("Controllers/MenuController")
		local IC = U7.client("Controllers/IndexController")
		local GuiService = game:GetService("GuiService")
		for _, s in ipairs({ { 844, 390, true }, { 390, 844, true } }) do
			U8.at(s[1], s[2], s[3], "index claim", function(tag)
				local before = GuiService.TouchControlsEnabled
				Menu.Open("Index")
				LKC.advance(1)
				local index = U8.pg():FindFirstChild("NimbusIndex")
				local claim = index and index:FindFirstChild("Claim", true)
				if not T.check(claim ~= nil and U8.shown(claim), tag .. ": the Claim button shows") then
					return
				end
				-- Roblox's jump button on a phone (HudController K: J = 70, from 1.5 J + 10 to 0.5 J + 10 off the right edge, its
				-- bottom 20 px over the bottom edge), in the window's own coordinates
				local J = 70
				local inset = index.IgnoreGuiInset and 0 or 58
				local jump = { X = s[1] - (1.5 * J + 10), R = s[1] - (0.5 * J + 10), Y = s[2] - 20 - J - inset, B = s[2] - 20 - inset }
				local hidden = GuiService.TouchControlsEnabled == false
				local c = U8.rect(claim)
				T.check(hidden or not U8.overlap(c, jump), tag .. ": Claim is never under the jump button (the touch controls hidden, or Claim clear of it)",
					fmt("touch controls %s, claim %s, jump %s", tostring(GuiService.TouchControlsEnabled), U8.show(c), U8.show(jump)))
				IC.Close()
				LKC.advance(0.5)
				T.eq(GuiService.TouchControlsEnabled, before, tag .. ": the touch controls are back as they were after Close")
			end)
		end
		LKC.flushErrors("index_claim_clear_of_jump")
	end)

	-- (Pitch 2 item 12_elements, option A "Wheel"; the owner's shot 12: Elements was a scrolling section inside the Index,
	-- 3 of the 8 elements in view, 18 px arrows, no title bar and no X) at the four grid sizes the Index's Elements plank
	-- opens a centred kit B window (Window_Elements in NimbusIndex) over the Index, which stays open: the Signboard panel
	-- with its ELEMENTS title and its red X (44 screen px or more); all eight elements at once, each block whole inside the
	-- window and on no other block; the ring's six links pixel arrows of 26 screen px or more (PixelIcon arrow*: the old
	-- ones were 18), the texts x1.5 and x0.75 shown; nothing scrolls (no ScrollingFrame in it) and every shown part of the
	-- chart inside the window, the window on the screen; Esc closes it and leaves the Index open, and so does the X
	S.elements_window = guarded("elements_window", function()
		local Menu = U7.client("Controllers/MenuController")
		local IC = U7.client("Controllers/IndexController")
		local Config = LoadingH.shared("Config")
		local UIS = game:GetService("UserInputService")
		local function press(key)
			Mock.FireSignal(UIS, "InputBegan", Mock.NewInput(key, "Keyboard", "Begin"), false)
		end
		local function plankOf(gui)
			for _, d in ipairs(gui and gui:GetDescendants() or {}) do
				if d.Name == "Elements" and d:IsA("GuiButton") and U8.shown(d) then
					return d
				end
			end
			return nil
		end
		-- (look review r0) a rect in screen px (a ScreenGui under Roblox's top bar sits 58 px lower), the right end of a
		-- part and its shown pieces (the ribbon's tails draw their notches outside their own box), the menu's shown tiles
		local function screenRect(o)
			local r = U8.rect(o)
			local cur = o
			while cur and not cur:IsA("LayerCollector") do
				cur = cur.Parent
			end
			local dy = (cur and cur:IsA("ScreenGui") and not cur.IgnoreGuiInset) and 58 or 0
			return { X = r.X, R = r.R, Y = r.Y + dy, B = r.B + dy }
		end
		local function farRight(o)
			local right = U8.rect(o).R
			for _, d in ipairs(o:GetDescendants()) do
				if d:IsA("GuiObject") and U8.shown(d) and d.AbsoluteSize.X > 0 then
					right = math.max(right, U8.rect(d).R)
				end
			end
			return right
		end
		-- the title ribbon's right end (its band and right tail with their pieces) and the X's left edge; ok = both tails shown
		local function ribbonEnd(win)
			local panel = win and win:FindFirstChild("ElementsPanel", true)
			local title = panel and panel:FindFirstChild("Title", true)
			local close = panel and panel:FindFirstChild("Close", true)
			local band = title and title:FindFirstChild("RibbonBand")
			local tailL, tailR = title and title:FindFirstChild("TailL"), title and title:FindFirstChild("TailR")
			if not (band and tailL and tailR and close) then
				return { ok = false, R = 0, X = 0 }
			end
			return { ok = U8.shown(band) and U8.shown(tailL) and U8.shown(tailR), R = math.max(farRight(band), farRight(tailR)), X = U8.rect(close).X }
		end
		local function menuTiles()
			local menu = U8.pg():FindFirstChild("NimbusMenu")
			local out = {}
			for _, d in ipairs(menu and menu:GetDescendants() or {}) do
				if d:IsA("GuiObject") and d.Name:match("^Entry_") and U8.shown(d) then
					out[#out + 1] = d
				end
			end
			return out
		end
		-- (look review r0) TextBounds with the faces' real widths, as Roblox and the renderer measure (the mock's flat 0.5 em
		-- made "ELEMENTS" at 34 px 136 px wide, so the title's ribbon had room it does not have; FredokaOne draws it 184):
		-- the mock's own wrap rule (on spaces, at the box's width) over real word widths
		local Theme = LoadingH.shared("Theme")
		local Mock = rawget(_G, "Mock")
		local mockExtent = Mock and Mock.TextExtent
		local function realExtent(inst, limit)
			local text = tostring(inst.Text or "")
			if inst.RichText then
				text = text:gsub("<[^>]*>", "")
			end
			local size = tonumber(inst.TextSize) or 14
			local font = (type(Theme.FontOf) == "function" and Theme.FontOf(inst)) or inst.Font
			local function width(str)
				return SmokeCommon.RealWidth(str, size, font) or (#str * size * 0.5)
			end
			local own = limit and limit / math.max(0.01, U8.scaleOf(inst)) or nil
			local space = width(" ")
			local maxW, lines = 0, 0
			for raw in (text .. "\n"):gmatch("([^\n]*)\n") do
				if own and own > 0 and width(raw) > own then
					local cur, rows = 0, 1
					for word in raw:gmatch("%S+") do
						local wl = width(word)
						if cur > 0 and cur + space + wl > own then
							rows = rows + 1
							maxW = math.max(maxW, cur)
							cur = 0
						end
						cur = (cur > 0) and (cur + space + wl) or wl
					end
					maxW = math.max(maxW, cur)
					lines = lines + rows
				else
					maxW = math.max(maxW, width(raw))
					lines = lines + 1
				end
			end
			return maxW, lines * size * (tonumber(inst.LineHeight) or 1)
		end
		if mockExtent then
			Mock.TextExtent = realExtent
		end
		-- (look review r0) the portrait phone first: the window is built there from nothing, as on a phone that opens it
		-- first (the renderer's flow; built first at 1920 and then rebuilt, the ribbon was re-fitted on the resize)
		local sizes = {}
		for i = #U8.SIZES, 1, -1 do
			sizes[#sizes + 1] = U8.SIZES[i]
		end
		for _, s in ipairs(sizes) do
			U8.at(s[1], s[2], s[3], "elements window", function(tag)
				Menu.Open("Index")
				LKC.advance(1)
				local gui = U8.pg():FindFirstChild("NimbusIndex")
				local plank = plankOf(gui)
				if not T.check(plank ~= nil, tag .. ": the Index shows its Elements plank") then
					return
				end
				local tilesBefore = #menuTiles()
				Mock.Click(plank)
				local ribAtOpen = ribbonEnd(gui:FindFirstChild("Window_Elements", true))
				LKC.advance(0.8)
				local win = gui:FindFirstChild("Window_Elements", true)
				if not T.check(win ~= nil and U8.shown(win), tag .. ": the plank opens the Elements window (Window_Elements)") then
					return
				end
				T.check(IC.IsOpen(), tag .. ": ...over the Index, which stays open")
				local panel = win:FindFirstChild("ElementsPanel", true)
				local body = panel and panel:FindFirstChild("Body")
				local r = U8.rect(body or win)
				local area = gui.AbsoluteSize
				T.check(math.abs((r.X + r.R) / 2 - area.X / 2) <= 2 and r.X >= 0 and r.R <= area.X and r.Y >= 0 and r.B <= area.Y,
					tag .. ": the window is centred across the screen and on it", U8.show(r) .. " in " .. area.X .. "x" .. area.Y)
				T.check(panel ~= nil and panel:GetAttribute("Skin") == "Signboard", tag .. ": a kit B Signboard window")
				local title = panel and panel:FindFirstChild("Title", true)
				T.check(title ~= nil and U8.shown(title) and title.Text:lower() == "elements", tag .. ": its title reads ELEMENTS", title and title.Text or "none")
				local close = panel and panel:FindFirstChild("Close", true)
				T.check(close ~= nil and U8.shown(close) and close.AbsoluteSize.X >= 43.5 and close.AbsoluteSize.Y >= 43.5, tag .. ": its red X shows, 44 px or more",
					close and U8.show(U8.rect(close)) or "none")
				-- (look review r0, major: at 390x844 the ribbon ran under the X, its right tail hidden: the title's ribbon was
				-- fitted while the label had no box yet, so it took the full pads its 220 px box has no room for) the gold ribbon,
				-- band and both tails, ends 4 design px or more before the X: on the frame the window opens and once it settled
				local k = U8.scaleOf(panel or win)
				for _, at in ipairs({ { ribAtOpen, "as it opens" }, { ribbonEnd(win), "settled" } }) do
					local rb = at[1]
					T.check(rb.ok and rb.R <= rb.X - 4 * k + 0.5, tag .. ": the title's ribbon shows both tails and ends 4 px or more before the X (" .. at[2] .. ")",
						fmt("ribbon ends %.1f, X at %.1f, both tails %s", rb.R, rb.X, tostring(rb.ok)))
				end
				-- (look review r0, major: at 844x390 slivers of the menu tiles showed at the window's left edge) no menu tile
				-- shows under the window while it is open
				local under = {}
				local wr = screenRect(win:FindFirstChild("ElementsPanel", true) or win)
				for _, t in ipairs(menuTiles()) do
					if U8.overlap(screenRect(t), wr) then
						under[#under + 1] = t.Name .. " " .. U8.show(screenRect(t))
					end
				end
				T.check(#under == 0, tag .. ": no menu tile shows under the Elements window (the tiles step aside)",
					table.concat(under, "; ") .. " | window " .. U8.show(wr))
				-- (look review r0, minor: at 1920 the Nature block sat 2-3 px over the body's foot) on PC the ring is centred in
				-- the body: its lowest block 12 design px or more over the stone's lip
				local stone = panel and panel:FindFirstChild("Stone", true)
				local lip = stone and stone:FindFirstChild("Lip")
				if win:GetAttribute("Mode") == "PC" and lip then
					local low = 0
					for _, e in ipairs(Config.Elements.Order) do
						local b = win:FindFirstChild("Ring", true) and win:FindFirstChild("Ring", true):FindFirstChild("Block_" .. e)
						if b and U8.shown(b) then
							low = math.max(low, U8.rect(b).B)
						end
					end
					T.check(low > 0 and low <= U8.rect(lip).Y - 12 * k + 0.5, tag .. ": the ring's lowest block keeps 12 px or more of stone over the lip",
						fmt("lowest block ends %.1f, lip at %.1f", low, U8.rect(lip).Y))
				end
				-- (look review r0, minor: at 844x390 "rivals: / x1.5 / both" wrapped to 3 cramped lines) the rivals' caption
				-- takes 2 lines or fewer
				local rc = win:FindFirstChild("RivalCaption", true)
				if rc and U8.shown(rc) and rc.TextWrapped then
					local lines = math.floor(rc.TextBounds.Y / math.max(1, rc.TextSize * U8.scaleOf(rc)) + 0.25)
					T.check(lines <= 2, tag .. ": the rivals' caption takes 2 lines or fewer", fmt("'%s' %d lines (%s)", rc.Text, lines, U8.show(U8.rect(rc))))
				end
				-- all eight elements at once, whole and apart
				local blocks, missing, outside, meet = {}, {}, {}, {}
				for _, e in ipairs(Config.Elements.Order) do
					local b = win:FindFirstChild("Block_" .. e, true)
					if b and U8.shown(b) then
						local br = U8.rect(b)
						blocks[#blocks + 1] = { e, br }
						if br.X < r.X - 0.5 or br.R > r.R + 0.5 or br.Y < r.Y - 0.5 or br.B > r.B + 0.5 then
							outside[#outside + 1] = e .. " " .. U8.show(br)
						end
					else
						missing[#missing + 1] = e
					end
				end
				for i = 1, #blocks do
					for j = i + 1, #blocks do
						if U8.overlap(blocks[i][2], blocks[j][2]) then
							meet[#meet + 1] = blocks[i][1] .. "/" .. blocks[j][1]
						end
					end
				end
				T.check(#missing == 0, tag .. ": all " .. #Config.Elements.Order .. " elements show at once", table.concat(missing, ", "))
				T.check(#outside == 0 and #meet == 0, tag .. ": every element block whole inside the window and on no other block",
					table.concat(outside, "; ") .. " | " .. table.concat(meet, ", "))
				-- the ring's links: big pixel arrows (never a rotated frame); the multipliers in words
				local ring = win:FindFirstChild("Ring", true)
				local arrows, small = 0, {}
				for _, d in ipairs(ring and ring:GetDescendants() or {}) do
					local name = d:GetAttribute("PixelIcon")
					if type(name) == "string" and (name:match("^arrow") or name == "left") and U8.shown(d) then
						arrows = arrows + 1
						if d.AbsoluteSize.X < 25.5 or d.Rotation ~= 0 then
							small[#small + 1] = name .. " " .. U8.show(U8.rect(d))
						end
					end
				end
				T.check(arrows >= 6 and #small == 0, tag .. ": the ring's six links are pixel arrows of 26 screen px or more, none turned",
					arrows .. " arrows; " .. table.concat(small, "; "))
				local texts, seen = {}, {}
				for _, d in ipairs(win:GetDescendants()) do
					if d:IsA("TextLabel") and U8.shown(d) then
						seen[d.Text] = true
					end
				end
				for _, want in ipairs({ "x1.5", "x0.75" }) do
					if not seen[want] then
						texts[#texts + 1] = want
					end
				end
				T.check(#texts == 0, tag .. ": the multipliers read x1.5 and x0.75", "missing " .. table.concat(texts, ", "))
				-- nothing scrolls: no scroll frame, every part of the chart inside the window
				local scrolls, out = {}, {}
				local content = panel and panel:FindFirstChild("Chart", true)
				for _, d in ipairs(win:GetDescendants()) do
					if d:IsA("ScrollingFrame") and U8.shown(d) then
						scrolls[#scrolls + 1] = d.Name
					end
				end
				for _, d in ipairs(content and content:GetDescendants() or {}) do
					if d:IsA("GuiObject") and U8.shown(d) and d.AbsoluteSize.X > 0 then
						local dr = U8.rect(d)
						if dr.X < r.X - 1 or dr.R > r.R + 1 or dr.Y < r.Y - 1 or dr.B > r.B + 1 then
							out[#out + 1] = d.Name .. " " .. U8.show(dr)
						end
					end
				end
				T.check(content ~= nil and #scrolls == 0 and #out == 0, tag .. ": nothing scrolls: no scroll frame, every part of the chart inside the window",
					table.concat(scrolls, ", ") .. " | " .. table.concat(out, "; ", 1, math.min(#out, 6)))
				-- Esc, then the X: each closes the chart and leaves the Index open
				press("Escape")
				LKC.advance(0.5)
				T.check(not U8.shown(win) and IC.IsOpen(), tag .. ": Esc closes the Elements window and leaves the Index open",
					fmt("elements %s, index %s", tostring(U8.shown(win)), tostring(IC.IsOpen())))
				plank = plankOf(gui)
				if plank then
					Mock.Click(plank)
					LKC.advance(0.8)
				end
				T.check(U8.shown(win), tag .. ": the plank opens it again")
				if close then
					Mock.Click(close)
					LKC.advance(0.5)
				end
				T.check(not U8.shown(win) and IC.IsOpen(), tag .. ": the X closes it and returns to the Index",
					fmt("elements %s, index %s", tostring(U8.shown(win)), tostring(IC.IsOpen())))
				T.eq(#menuTiles(), tilesBefore, tag .. ": the menu tiles are back as they were with the Index alone")
			end)
		end
		if mockExtent then
			Mock.TextExtent = mockExtent
		end
		LKC.flushErrors("elements_window")
	end)

	-- (Pitch 2 item 12_index_badge, option B "Reward on the row"; the owner's shot 12: the red "!" / green check badge sat
	-- on the tab's title row and poked 6 px over the tab, and a strip tab at the strip's end showed cut, "0 fu...") at the
	-- four grid sizes, with one group's reward waiting (the first group complete) and one claimed (the second): no tab
	-- shows a badge; the waiting tab's count gives way to a gold token chip "+<reward>" (Reward, the token icon on it) and
	-- the claimed tab's to a grass check (Claimed), each whole inside its tab and clear of its name; the strip's tabs show
	-- whole at rest, also after a swipe that stopped half way (the strip snaps to whole tabs) and its page dots show; in
	-- the column layout the Elements plank sits in the header band, left of the X and clear of the title
	S.index_badge_clear = guarded("index_badge_clear", function()
		local Menu = U7.client("Controllers/MenuController")
		local PetCatalog = LoadingH.shared("PetCatalog")
		local Config = LoadingH.shared("Config")
		local Theme = LoadingH.shared("Theme")
		local groups = (PetCatalog and type(PetCatalog.IndexGroups) == "function") and PetCatalog.IndexGroups() or {}
		local g1, g2 = groups[1], groups[2]
		if not T.check(g1 ~= nil and g2 ~= nil, "index badge: the catalog has two Index groups") then
			return
		end
		local disc = {}
		for _, key in ipairs(U8.KEYS) do
			disc[key] = true
		end
		for _, g in ipairs({ g1, g2 }) do
			for _, def in ipairs(g.Pets) do
				disc[def.Id] = true
			end
		end
		local reward = g1.Reward and g1.Reward.Tokens or (Config.Index and Config.Index.Rewards and Config.Index.Rewards[g1.Id] and Config.Index.Rewards[g1.Id].Tokens) or 0
		local wantChip = "+" .. Theme.Short(reward)
		local function inside(a, b)
			return a.X >= b.X - 0.5 and a.R <= b.R + 0.5 and a.Y >= b.Y - 0.5 and a.B <= b.B + 0.5
		end
		-- a name's drawn text: its box's width, one TextSize tall in the middle of the box (the box is 4 px taller)
		local function drawn(label)
			if not label then
				return { X = 0, R = 0, Y = 0, B = 0 }
			end
			local r = U8.rect(label)
			local half = label.TextSize * U8.scaleOf(label) / 2
			local cy = (r.Y + r.B) / 2
			return { X = r.X, R = r.R, Y = cy - half, B = cy + half }
		end
		for _, s in ipairs(U8.SIZES) do
			U8.at(s[1], s[2], s[3], "index badge", function(tag)
				U8.feed(nil, nil, nil, nil, { Discovered = disc, IndexClaimed = { [g2.Id] = true } })
				Menu.Open("Index")
				LKC.advance(1)
				local index = U8.pg():FindFirstChild("NimbusIndex")
				local list = index and index:FindFirstChild("GroupList", true)
				if not T.check(list ~= nil, tag .. ": the tab strip (GroupList) exists") then
					return
				end
				local badges = {}
				for _, d in ipairs(list:GetDescendants()) do
					if d.Name == "Badge" and d:IsA("GuiObject") and U8.shown(d) then
						badges[#badges + 1] = d.Parent.Name
					end
				end
				T.check(#badges == 0, tag .. ": no tab shows a badge (the reward sits on the row)", table.concat(badges, ", "))
				local function partOf(group, name)
					local tab = list:FindFirstChild("Group_" .. group.Id, true)
					return tab, tab and tab:FindFirstChild(name, true)
				end
				-- the waiting reward: the gold chip in the count's place
				local t1, chip = partOf(g1, "Reward")
				local name1 = t1 and t1:FindFirstChild("GroupName", true)
				local count1 = t1 and t1:FindFirstChild("Progress")
				local okChip = chip and U8.shown(chip) and chip.Text == wantChip and chip:FindFirstChild("LeadIcon", true) ~= nil
				T.check(okChip and inside(U8.rect(chip), U8.rect(t1)) and not U8.overlap(U8.rect(chip), drawn(name1))
					and not (count1 and U8.shown(count1)), tag .. ": the waiting reward reads " .. wantChip .. " on a gold token chip, whole in its tab, clear of the name, the count gone",
					chip and fmt("'%s' %s in %s, count %s", chip.Text, U8.show(U8.rect(chip)), U8.show(U8.rect(t1)), tostring(count1 and U8.shown(count1))) or "no chip")
				-- the claimed group: a grass check in the count's place
				local t2, done = partOf(g2, "Claimed")
				local name2 = t2 and t2:FindFirstChild("GroupName", true)
				local count2 = t2 and t2:FindFirstChild("Progress")
				T.check(done ~= nil and U8.shown(done) and inside(U8.rect(done), U8.rect(t2)) and not U8.overlap(U8.rect(done), drawn(name2))
					and not (count2 and U8.shown(count2)), tag .. ": the claimed group shows a grass check, whole in its tab, clear of the name, the count gone",
					done and fmt("%s in %s", U8.show(U8.rect(done)), U8.show(U8.rect(t2))) or "no check")
				local column = list.ScrollingDirection == Enum.ScrollingDirection.Y
				if column then
					-- the column layout: the Elements plank in the header, by the X
					local panel = index:FindFirstChild("IndexPanel", true)
					local head = panel and panel:FindFirstChild("TitleBar", true)
					local plank = index:FindFirstChild("Elements", true)
					local close = panel and panel:FindFirstChild("Close", true)
					local title = head and head:FindFirstChild("Title", true)
					local pr = plank and U8.rect(plank)
					T.check(plank ~= nil and head ~= nil and U8.shown(plank) and inside(pr, U8.rect(head)) and close ~= nil and pr.R <= U8.rect(close).X + 0.5
						and not (title and U8.overlap(pr, { X = U8.rect(title).X, R = U8.rect(title).X + title.TextBounds.X, Y = U8.rect(title).Y, B = U8.rect(title).B })),
						tag .. ": the Elements plank sits in the header band, left of the X and clear of the title",
						pr and fmt("plank %s, head %s", U8.show(pr), head and U8.show(U8.rect(head)) or "-") or "no plank")
					-- (look review r0, minor: at 1920 the plank hung ~5 px under the navy band onto the body's edge) every drawn
					-- part of the plank (its edge, its hard shadow) stays on the navy plate
					local plate = head and head:FindFirstChild("Plate")
					if plank and plate then
						local low = pr.B -- (its hard shadow's pieces start under its outer edge, so they mark the drawn foot)
						for _, d in ipairs(plank:GetDescendants()) do
							if d:IsA("GuiObject") and U8.shown(d) and d.BackgroundTransparency < 1 and d.AbsoluteSize.Y > 0 then
								low = math.max(low, U8.rect(d).B)
							end
						end
						T.check(low <= U8.rect(plate).B + 0.5, tag .. ": the Elements plank's edge and shadow stay on the navy band",
							fmt("plank drawn to %.1f, band ends %.1f", low, U8.rect(plate).B))
					end
				else
					-- the strip: a swipe that stops half way snaps back to whole tabs; the page dots say there is more
					local view = U8.rect(list)
					list.CanvasPosition = Vector2.new(37, 0)
					LKC.advance(0.8)
					local cut = {}
					for _, tab in ipairs(list:GetChildren()) do
						if tab.Name:match("^Group_") and tab:IsA("GuiButton") and U8.shown(tab) then
							local r = U8.rect(tab)
							if U8.overlap(r, view) and not inside(r, view) then
								cut[#cut + 1] = tab.Name .. " " .. U8.show(r)
							end
						end
					end
					T.check(#cut == 0, tag .. ": after a swipe that stopped half way every tab in view shows whole (the strip snaps)",
						table.concat(cut, "; ") .. " | view " .. U8.show(view) .. ", canvas " .. tostring(list.CanvasPosition.X))
					local dots = index:FindFirstChild("PageDots", true)
					local n = 0
					for _, d in ipairs(dots and dots:GetChildren() or {}) do
						if d:IsA("GuiObject") and U8.shown(d) then
							n = n + 1
						end
					end
					T.check(dots ~= nil and U8.shown(dots) and n >= 2, tag .. ": the strip's page dots show (" .. n .. ")")
					-- (look review r0, major: the dots sat in the tabs' shadow against the Common tab, tan on cream, and read as a
					-- shadow line) the dots keep 3 design px or more of stone under the tabs' drawn parts (their hard shadows) and
					-- over the centre, and a dot not in view still reads on the stone (3:1)
					if dots and n >= 2 then
						local k = U8.scaleOf(dots)
						local shadowB = 0
						for _, tab in ipairs(list:GetChildren()) do
							if tab:IsA("GuiObject") and U8.shown(tab) and U8.overlap(U8.rect(tab), view) then
								shadowB = math.max(shadowB, U8.rect(tab).B)
								for _, d in ipairs(tab:GetDescendants()) do
									if d:IsA("GuiObject") and U8.shown(d) and d.BackgroundTransparency < 1 and d.AbsoluteSize.Y > 0 then
										shadowB = math.max(shadowB, U8.rect(d).B)
									end
								end
							end
						end
						local dr = U8.rect(dots)
						local centre = index:FindFirstChild("Centre", true)
						local cy = centre and U8.shown(centre) and U8.rect(centre).Y or math.huge
						T.check(dr.Y >= shadowB + 3 * k - 0.5 and dr.B <= cy - 3 * k + 0.5, tag .. ": the page dots sit on clear stone, 3 px or more under the tabs' shadows and over the centre",
							fmt("dots %s, tabs drawn to %.1f, centre at %.1f", U8.show(dr), shadowB, cy))
						local page = dots:GetAttribute("Page")
						local weak = {}
						for i = 1, n do
							local d = dots:FindFirstChild("Dot" .. i)
							if d and i ~= page and Theme.Contrast(d.BackgroundColor3, Theme.Sign.Stone) < 3 then
								weak[#weak + 1] = fmt("Dot%d %.2f:1", i, Theme.Contrast(d.BackgroundColor3, Theme.Sign.Stone))
							end
						end
						T.check(#weak == 0, tag .. ": a page dot not in view reads on the stone (3:1 or more)", table.concat(weak, ", "))
					end
				end
			end)
		end
		LKC.flushErrors("index_badge_clear")
	end)

	-- (U8; finding 15) no neon glow in the U8 families: the lobby HUD (NimbusHud, the top-bar pill, the menu tiles, the gift, the
	-- boost chips under it), the
	-- Pets window and the Index. No glow ring (a NeonKit Glow frame or GlowStroke shown), no gloss gradient (a UIGradient on
	-- a shown object; kit B's functional ones are named Lip, Step, Sweep or Fill and keep a flat face), no neon border (a
	-- Border UIStroke in a Theme.Neon colour) and no Theme.Neon fill. NeonKit.Card's glow is off unless asked for
	S.kitb_no_neon_glow = guarded("kitb_no_neon_glow", function()
		local Theme = LoadingH.shared("Theme")
		local NK = U7.client("UI/NeonKit")
		local PC = U7.client("Controllers/PetsController")
		local Menu = U7.client("Controllers/MenuController")
		if not T.check(NK and PC and Menu, "no neon glow: NeonKit, PetsController and MenuController load") then
			return
		end
		local plain = NK.Card({ Name = "U8Probe" })
		local lit = NK.Card({ Name = "U8Probe", Glow = true })
		T.check(plain.Glow.Visible == false and lit.Glow.Visible == true, "no neon glow: NeonKit.Card's glow is off by default (Glow = true turns it on)")
		plain.Root:Destroy()
		lit.Root:Destroy()
		local ALLOWED = { Lip = true, Step = true, Sweep = true, Fill = true }
		local function neonName(c)
			for name, n in pairs(Theme.Neon) do
				if sameColor(c, n) then
					return name
				end
			end
			return nil
		end
		-- (U8 review) the drawn cut gem (client/UI/GemIcon, spec 5.7) is an icon whose tones are its art (U8 kept it on its navy
		-- square): its gradients are not a panel's gloss. The Gems strip shows only in some lobby states, so the walk met it
		-- only after another scenario had turned it on
		local function inGemIcon(d)
			local cur = d.Parent
			while cur and not cur:IsA("LayerCollector") do
				if cur.Name == "GemIcon" then
					return true
				end
				cur = cur.Parent
			end
			return false
		end
		-- (U9-2) the Shop's illustrations are art, not panels: the gumball machines (attribute Art) and the EggArt eggs
		-- (attributes Form + Rarity) keep their glass sheen and egg tones. (LOOK-ui, kitb-look1) a scroll row's edge "Fade" no
		-- longer fades: it holds CloudUI.MoreMark, so no gradient is allowed for it
		local function inArt(d)
			local cur = d.Parent
			while cur and not cur:IsA("LayerCollector") do
				if cur:GetAttribute("Art") ~= nil or (cur:GetAttribute("Form") ~= nil and cur:GetAttribute("Rarity") ~= nil) then
					return true
				end
				cur = cur.Parent
			end
			return false
		end
		local function walk(root, family, bad)
			for _, d in ipairs(root and root:GetDescendants() or {}) do
				local p = d.Parent
				if inArt(d) then
					-- (U9-2) an illustration's own paint
				elseif d:IsA("UIStroke") and p and p:IsA("GuiObject") and U8.shown(p) and d.Enabled ~= false and d.Transparency < 0.95 then
					if d.Name == "GlowStroke" or (p.Name == "Glow" and d.ApplyStrokeMode == Enum.ApplyStrokeMode.Border) then
						bad[#bad + 1] = family .. ": a glow ring on " .. p:GetFullName():gsub("^Players%.[^.]+%.PlayerGui%.", "")
					elseif d.ApplyStrokeMode == Enum.ApplyStrokeMode.Border and neonName(d.Color) then
						bad[#bad + 1] = family .. ": a neon " .. neonName(d.Color) .. " border on " .. p.Name
					end
				elseif d:IsA("UIGradient") and p and p:IsA("GuiObject") and U8.shown(p) and d.Enabled ~= false and not ALLOWED[d.Name] and not inGemIcon(d)
					and not designedLook(d) then -- (kit-b merge) the title's T1 ribbon: its gold bands and TitleHide are the owner's pick
					bad[#bad + 1] = family .. ": a gloss gradient on " .. p:GetFullName():gsub("^Players%.[^.]+%.PlayerGui%.", "")
				elseif d:IsA("GuiObject") and d.BackgroundTransparency < 0.5 and U8.shown(d) and neonName(d.BackgroundColor3) then
					bad[#bad + 1] = family .. ": a neon " .. neonName(d.BackgroundColor3) .. " fill on " .. d.Name
				end
			end
		end
		for _, s in ipairs({ { 1920, 1080, false }, { 844, 390, true } }) do
			U8.at(s[1], s[2], s[3], "no neon glow", function(tag)
				local pg = U8.pg()
				local bad = {}
				local menu = pg:FindFirstChild("NimbusMenu")
				walk(pg:FindFirstChild("NimbusHud"), "HUD", bad)
				walk(pg:FindFirstChild("NimbusTopBar"), "HUD pill", bad)
				walk(menu and menu:FindFirstChild("MenuColumn"), "HUD tiles", bad)
				local daily = pg:FindFirstChild("NimbusDaily")
				local gift = daily and daily:FindFirstChild("GiftsButton")
				if gift then
					walk(gift, "HUD gift", bad)
				end
				-- (U8 review) the boost chips hang right under the gift: both shown (the two passes), each a kit B tag (a flat
				-- block in its wood edge, square: no UICorner, no gradient)
				local lp = game:GetService("Players").LocalPlayer
				local oldPasses = lp:GetAttribute("OwnedPasses")
				lp:SetAttribute("OwnedPasses", "Cash2x,PetXp2x")
				LKC.advance(0.3)
				local boosts = pg:FindFirstChild("NimbusBoosts")
				local chips = 0
				for _, name in ipairs({ "Chip_Cash", "Chip_Xp" }) do
					local chip = boosts and boosts:FindFirstChild(name, true)
					if chip and U8.shown(chip) then
						chips = chips + 1
						T.check(chip:FindFirstChildOfClass("UICorner") == nil and chip:FindFirstChildOfClass("UIGradient") == nil and chip:FindFirstChild("SignEdge") ~= nil
							and chip.BackgroundTransparency == 0, tag .. ": the boost chip " .. name .. " is a kit B tag (a flat face in a wood edge, square)")
					end
				end
				T.check(chips == 2, tag .. ": both boost chips show under the gift (the two passes)", tostring(chips))
				walk(boosts, "HUD boosts", bad)
				lp:SetAttribute("OwnedPasses", oldPasses)
				LKC.advance(0.3)
				PC.Open({ Key = U8.KEYS[4] })
				LKC.advance(1)
				walk(pg:FindFirstChild("NimbusPets"), "Pets", bad)
				PC.Close(true)
				LKC.advance(0.4)
				Menu.Open("Index")
				LKC.advance(1)
				walk(pg:FindFirstChild("NimbusIndex"), "Index", bad)
				pcall(Menu.Close)
				LKC.advance(0.4)
				-- (U9-1) the Home window: with a home (the hero, the strip, the cards, the station rows, the Prestige confirm shown
				-- over them) and without one (Claim a home and its three steps)
				local Config = LoadingH.shared("Config")
				local oldSpot = lp:GetAttribute(Config.Attr.SpotIndex)
				for _, spot in ipairs({ 1, false }) do
					lp:SetAttribute(Config.Attr.SpotIndex, spot or nil)
					LKC.advance(0.2)
					Menu.Open("Home")
					LKC.advance(1)
					local home = pg:FindFirstChild("NimbusMenu") and pg.NimbusMenu:FindFirstChild("Window_Home")
					walk(home, spot and "Home" or "Home (no home)", bad)
					local confirm = home and home:FindFirstChild("PrestigeConfirm", true)
					if spot and confirm then
						confirm.Visible = true
						walk(confirm, "Home Prestige confirm", bad)
						confirm.Visible = false
					end
					pcall(Menu.Close)
					LKC.advance(0.4)
				end
				lp:SetAttribute(Config.Attr.SpotIndex, oldSpot)
				LKC.advance(0.2)
				-- (U9-2) the Shop on every tab (the Secret card at the altar and away from it on Eggs)
				local Shop = U7.client("Controllers/ShopController")
				local SE = U7.client("UI/ShopEggs")
				local oldAltar = SE and SE._AtAltar
				for _, tab in ipairs({ "Eggs", "Gems", "Packs", "Passes", "Boosts" }) do
					Shop.Open({ Tab = tab })
					LKC.advance(1)
					walk(pg:FindFirstChild("NimbusShop"), "Shop " .. tab, bad)
					if tab == "Eggs" and SE then
						SE._AtAltar = false
						Shop.Open({ Tab = tab })
						LKC.advance(1.2)
						walk(pg:FindFirstChild("NimbusShop"), "Shop Eggs (away)", bad)
						SE._AtAltar = oldAltar
					end
				end
				pcall(Shop.Close)
				LKC.advance(0.4)
				-- (U9-3) the Stats window, and the titles and the VIP crown over heads (BillboardGuis on the characters)
				walk(U93.open(), "Stats", bad)
				pcall(Menu.Close)
				LKC.advance(0.4)
				U93.titled(function(players)
					for _, bb in ipairs(U93.boards(players)) do
						walk(bb, bb.Name .. " " .. bb.Parent.Parent.Name, bad)
					end
				end)
				-- (U9-4) the Gifts window on both tabs (a day due, the play gifts paused with one ready) and the Sky Trove panel
				-- (Join open, then Done)
				local DCw = U7.client("Controllers/DailyController")
				for _, view in ipairs({ { "Daily", "" }, { "Play", "play" } }) do
					LKC.toClient("DailyState", U94.payload(view[2]))
					LKC.advance(0.2)
					DCw.Open({ Tab = view[1] })
					LKC.advance(1)
					walk(U94.holder(), "Gifts " .. view[1], bad)
				end
				pcall(DCw.Close)
				LKC.advance(0.4)
				for _, state in ipairs({ "Open", "Done" }) do
					walk(U94.trove(state), "Trove " .. state, bad)
				end
				U94.closeTrove()
				-- (U9-9) the toasts, the match result card (won, lost), the tutorial card (opened, folded) and its menu pointer,
				-- the NPC dialog and (PC) the "press L" hint
				U99.walkFamily(not s[3], function(root, family)
					walk(root, family, bad)
				end)
				-- (U9-2b) the hatch stage: the strip mid-scroll, the crack, the x1 reveal and the x3 reveal. Its art (attribute Art)
				-- keeps its own paint; a letter's hard "Bands" are the title look's face
				ALLOWED.Bands = true
				local ESw = U92b.show("x1")
				if ESw then
					LKC.advance(1.6)
					walk(U8.pg():FindFirstChild("NimbusHatch"), "Hatch strip", bad)
					LKC.advance(3.1)
					walk(U8.pg():FindFirstChild("NimbusHatch"), "Hatch crack", bad)
					U92b.close()
				else
					bad[#bad + 1] = "the hatch stage did not show"
				end
				for _, kind in ipairs({ "x1", "x3" }) do
					if U92b.reveal(kind) then
						walk(U8.pg():FindFirstChild("NimbusHatch"), "Hatch reveal " .. kind, bad)
					end
					U92b.close()
				end
				T.check(#bad == 0, fmt("%s: no glow ring, gloss gradient, neon border or neon fill in the HUD, the Pets window, the Index, the Home window, the Shop, the Stats window, the tags over heads, the Gifts window, the Sky Trove, the toasts, the result card, the tutorial, the NPC dialog, the mouse hint and the hatch stage (%d)", tag, #bad),
					table.concat(bad, "; ", 1, math.min(#bad, 12)))
				-- (U9-5) and the Care family: the Training Place, the Food Machine, the garden picker, the Fusion Machine on both
				-- tabs and the pet picker in its three contexts
				pcall(Menu.Close)
				LKC.advance(0.4)
				local family, opened = {}, 0
				for _, f in ipairs(U9.FAMILY) do
					U9.open(f[1])
					local gui = pg:FindFirstChild(f[2])
					if U9.showing(gui) then
						opened = opened + 1
					end
					walk(gui, f[1], family)
					U9.close()
				end
				T.check(opened == #U9.FAMILY, fmt("%s: every Care family view opened (%d of %d)", tag, opened, #U9.FAMILY))
				T.check(#family == 0, fmt("%s: no glow ring, gloss gradient, neon border or neon fill in the Care family (%d)", tag, #family),
					table.concat(family, "; ", 1, math.min(#family, 12)))
				-- (U9-6) and the battle family: the HUD in a dungeon room, a raid and a ring round, the next-round card, the run's
				-- result card and the loss screen. Stricter than the walk above: kit B is square and flat, so a shown gradient is
				-- only a pie's hard-edged Sweep (a cooldown ring) or the title's designed look, and a corner only rounds a disc (a
				-- round button, a portrait: CornerRadius 0.5)
				local battle, seen = {}, 0
				for _, f in ipairs(U96.FAMILY) do
					U96.open(f[1])
					local gui = pg:FindFirstChild(f[2])
					if U96.showing(gui) then
						seen = seen + 1
					end
					walk(gui, f[1], battle)
					for _, d in ipairs(gui and gui:GetDescendants() or {}) do
						local p = d.Parent
						if p and p:IsA("GuiObject") and U8.shown(p) and not designedLook(d) then
							local where = f[1] .. ": " .. p:GetFullName():gsub("^Players%.[^.]+%.PlayerGui%.", "")
							if d:IsA("UIGradient") and d.Enabled ~= false and d.Name ~= "Sweep" and d.Name ~= "Fill" and d.Name ~= "Lip" then
								battle[#battle + 1] = where .. " has a gradient (" .. d.Name .. ")"
							elseif d:IsA("UIGradient") and d.Enabled ~= false and d.Name == "Fill" then
								battle[#battle + 1] = where .. " has a gloss fill gradient"
							elseif d:IsA("UICorner") and not (d.CornerRadius.Scale >= 0.49 and p.AbsoluteSize.X > 0 and math.abs(p.AbsoluteSize.X - p.AbsoluteSize.Y) <= 1.5) then
								battle[#battle + 1] = where .. " has a rounded corner"
							end
						end
					end
					U96.close()
				end
				T.check(seen == #U96.FAMILY, fmt("%s: every battle family view opened (%d of %d)", tag, seen, #U96.FAMILY))
				T.check(#battle == 0, fmt("%s: no glow, gradient, neon or rounded corner in the battle family (%d)", tag, #battle),
					table.concat(battle, "; ", 1, math.min(#battle, 12)))
				-- (U9-7) and the dock family (U97.FAMILY: the Arena, Ring, Dungeon and dare windows, the run / End cards, the side
				-- cards), as strict as the battle family: square and flat, so no gradient but a designed look and no corner but a
				-- disc's; and the team rows (TeamFaces) inside them
				local dock, shown = {}, 0
				for _, f in ipairs(U97.FAMILY) do
					U97.open(f[1])
					local gui = pg:FindFirstChild(f[2])
					if U97.showing(gui) then
						shown = shown + 1
					end
					walk(gui, f[1], dock)
					for _, d in ipairs(gui and gui:GetDescendants() or {}) do
						local p = d.Parent
						if p and p:IsA("GuiObject") and U8.shown(p) and not designedLook(d) then
							local where = f[1] .. ": " .. p:GetFullName():gsub("^Players%.[^.]+%.PlayerGui%.", "")
							if d:IsA("UIGradient") and d.Enabled ~= false then
								dock[#dock + 1] = where .. " has a gradient (" .. d.Name .. ")"
							elseif d:IsA("UICorner") and not (d.CornerRadius.Scale >= 0.49 and p.AbsoluteSize.X > 0 and math.abs(p.AbsoluteSize.X - p.AbsoluteSize.Y) <= 1.5) then
								dock[#dock + 1] = where .. " has a rounded corner"
							end
						end
					end
					U97.close()
				end
				T.check(shown == #U97.FAMILY, fmt("%s: every dock family view opened (%d of %d)", tag, shown, #U97.FAMILY))
				T.check(#dock == 0, fmt("%s: no glow, gradient, neon or rounded corner in the dock family (%d)", tag, #dock),
					table.concat(dock, "; ", 1, math.min(#dock, 12)))
				-- (U9-8) and the Obby family (U98.FAMILY: the Sky Obby picker, its unlock toast, the HUD's vitals card at rest and
				-- with a dash cooling), as strict: no gradient but a designed look, no corner but a disc's. The vitals card's
				-- health tube (HealthBar) is U8's and keeps its lip gradient: the walk leaves it out
				local obby, seenObby = {}, 0
				for _, f in ipairs(U98.FAMILY) do
					U98.open(f[1])
					local gui = pg:FindFirstChild(f[2])
					local root = f[3] and gui and gui:FindFirstChild(f[3], true) or gui
					if U98.showing(gui, f[3]) then
						seenObby = seenObby + 1
					end
					local hp = root and root:FindFirstChild("HealthBar", true)
					local function skip(d)
						return hp ~= nil and (d == hp or d:IsDescendantOf(hp))
					end
					for _, d in ipairs(root and root:GetDescendants() or {}) do
						local p = d.Parent
						if p and p:IsA("GuiObject") and U8.shown(p) and not designedLook(d) and not skip(d) then
							local where = f[1] .. ": " .. p:GetFullName():gsub("^Players%.[^.]+%.PlayerGui%.", "")
							if d:IsA("UIStroke") and d.Enabled ~= false and d.Transparency < 0.95 and (d.Name == "GlowStroke" or (p.Name == "Glow"
								and d.ApplyStrokeMode == Enum.ApplyStrokeMode.Border)) then
								obby[#obby + 1] = where .. " has a glow ring"
							elseif d:IsA("UIStroke") and d.Enabled ~= false and d.Transparency < 0.95 and d.ApplyStrokeMode == Enum.ApplyStrokeMode.Border and neonName(d.Color) then
								obby[#obby + 1] = where .. " has a neon " .. neonName(d.Color) .. " border"
							elseif d:IsA("GuiObject") and d.BackgroundTransparency < 0.5 and U8.shown(d) and neonName(d.BackgroundColor3) then
								obby[#obby + 1] = where .. "." .. d.Name .. " has a neon " .. neonName(d.BackgroundColor3) .. " fill"
							elseif d:IsA("UIGradient") and d.Enabled ~= false then
								obby[#obby + 1] = where .. " has a gradient (" .. d.Name .. ")"
							elseif d:IsA("UICorner") and (d.CornerRadius.Scale > 0 or d.CornerRadius.Offset > 0) -- (a 0 px corner is square: the HUD's card keeps one it resizes)
								and not (d.CornerRadius.Scale >= 0.49 and p.AbsoluteSize.X > 0 and math.abs(p.AbsoluteSize.X - p.AbsoluteSize.Y) <= 1.5) then
								obby[#obby + 1] = where .. " has a rounded corner"
							end
						end
					end
					U98.close()
				end
				T.check(seenObby == #U98.FAMILY, fmt("%s: every Obby family view opened (%d of %d)", tag, seenObby, #U98.FAMILY))
				T.check(#obby == 0, fmt("%s: no glow, gradient, neon or rounded corner in the Obby family (%d)", tag, #obby),
					table.concat(obby, "; ", 1, math.min(#obby, 12)))
			end)
		end
		LKC.flushErrors("kitb_no_neon_glow")
	end)

	-- (LOOK-ui, kitb-look1: the owner's look bar "pixel edges snapped to whole pixels at every screen size") at 1920x1080,
	-- 1280x720, 844x390 and 390x844, in the lobby HUD (strips, gift, tiles, vitals), the Pets window, the Index, the Home
	-- window, the Shop on its tabs and the Stats window: every PixelIcon cell is a whole number of screen px wide and tall and
	-- sits a whole number of px from its icon's other cells (one cell size, no lumpy 1-and-2 px cells), every kit lip (a
	-- Frame "Lip" of a fixed height) is a whole number of px tall and every kit edge (UIStroke "SignEdge") a whole number of
	-- px thick. A shown icon or edge under a transient pop is measured at rest (the pops rest at 1). Every shown scroll bar
	-- there is the kit's one bar (SignKit.Scroll: wood, opaque, square ends, 8 px or a phone list's 6)
	S.kitb_whole_pixels = guarded("kitb_whole_pixels", function()
		local Menu = U7.client("Controllers/MenuController")
		local PC = U7.client("Controllers/PetsController")
		local Shop = U7.client("Controllers/ShopController")
		local PI = LoadingH.shared("PixelIcon")
		if not T.check(Menu and PC and Shop and PI and PI.RestScale, "whole pixels: the windows and PixelIcon.RestScale load") then
			return
		end
		local function whole(v)
			return math.abs(v - math.floor(v + 0.5)) <= 0.02
		end
		local SK = LoadingH.shared("SignKit")
		local Sign = LoadingH.shared("Theme").Sign
		local function walk(root, family, bad, seen)
			for _, d in ipairs(root and root:GetDescendants() or {}) do
				if d:IsA("ScrollingFrame") and d.ScrollBarThickness > 0 and U8.shown(d) then
					seen.bars = seen.bars + 1
					local t = d.ScrollBarThickness
					if not (sameColor(d.ScrollBarImageColor3, Sign.Wood) and d.ScrollBarImageTransparency == 0 and d.TopImage == d.MidImage
						and d.BottomImage == d.MidImage and (t == SK.Sizes.ScrollBar or t == SK.Sizes.ScrollBarPhone)) then
						seen.badBars[#seen.badBars + 1] = fmt("%s: %s bar %d px %s @%.2f%s", family, d.Name, t, hex(d.ScrollBarImageColor3),
							d.ScrollBarImageTransparency, d.TopImage == d.MidImage and "" or " round ends")
					end
				end
				if d:IsA("GuiObject") and d.BorderSizePixel > 0 and d.BackgroundTransparency < 1 and U8.shown(d) then
					-- (LOOK-ui) Roblox's default 1 px dark border round an opaque part: kit B draws edges with strokes only
					seen.borders[#seen.borders + 1] = fmt("%s: %s", family, d:GetFullName():match("[^%.]+%.[^%.]+$") or d.Name)
				end
				if d:IsA("Frame") and d.Name == "CloseMark" and d:GetAttribute("PixelX") and U8.shown(d) then
					-- (LOOK-ui) the pitch's .x block: red face, the red lip, the edge in the ink (not the wood)
					seen.closes = seen.closes + 1
					local b = d.Parent
					local e, lip = b:FindFirstChild("SignEdge"), b:FindFirstChild("Lip")
					if not (e and sameColor(e.Color, Sign.Text) and lip and sameColor(lip.BackgroundColor3, Sign.RedLip) and sameColor(b.BackgroundColor3, Sign.Red)) then
						seen.badCloses[#seen.badCloses + 1] = fmt("%s: %s edge %s lip %s", family, b.Name, e and hex(e.Color) or "none", lip and hex(lip.BackgroundColor3) or "none")
					end
				end
				if d:IsA("Frame") and d:GetAttribute("PixelIcon") and U8.shown(d) then
					local first = nil
					for _, cell in ipairs(d:GetChildren()) do
						if cell:IsA("Frame") and cell.Name:match("^R%d+$") then -- PixelIcon.New's runs (a Lead box holds icons)
							seen.cells = seen.cells + 1
							local s, p = cell.AbsoluteSize, cell.AbsolutePosition
							first = first or p
							if not (whole(s.X) and whole(s.Y) and whole(p.X - first.X) and whole(p.Y - first.Y)) then
								bad[#bad + 1] = fmt("%s: %s icon cell %.2fx%.2f", family, tostring(d:GetAttribute("PixelIcon")), s.X, s.Y)
								break
							end
						end
					end
				elseif d:IsA("Frame") and d.Name == "Lip" and d.Size.Y.Scale == 0 and d.Size.Y.Offset > 0 and U8.shown(d) then
					seen.lips = seen.lips + 1
					if not whole(d.AbsoluteSize.Y) then
						bad[#bad + 1] = fmt("%s: lip %.2f px on %s", family, d.AbsoluteSize.Y, d.Parent.Name)
					end
				elseif d:IsA("UIStroke") and d.Name == "SignEdge" and d.Parent and d.Parent:IsA("GuiObject") and U8.shown(d.Parent) and d.Enabled ~= false then
					seen.edges = seen.edges + 1
					local px = d.Thickness * PI.RestScale(d.Parent)
					if not whole(px) then
						bad[#bad + 1] = fmt("%s: edge %.2f px on %s", family, px, d.Parent.Name)
					end
				end
			end
		end
		for _, s in ipairs(U8.SIZES) do
			U8.at(s[1], s[2], s[3], "whole pixels", function(tag)
				local pg = U8.pg()
				local bad, seen = {}, { cells = 0, lips = 0, edges = 0, bars = 0, badBars = {}, closes = 0, badCloses = {}, borders = {} }
				walk(pg:FindFirstChild("NimbusHud"), "HUD", bad, seen)
				local menu = pg:FindFirstChild("NimbusMenu")
				walk(menu and menu:FindFirstChild("MenuColumn"), "HUD tiles", bad, seen)
				local daily = pg:FindFirstChild("NimbusDaily")
				walk(daily and daily:FindFirstChild("GiftsButton"), "HUD gift", bad, seen)
				PC.Open({ Key = U8.KEYS[4] })
				LKC.advance(1)
				walk(pg:FindFirstChild("NimbusPets"), "Pets", bad, seen)
				PC.Close(true)
				LKC.advance(0.4)
				for _, name in ipairs({ "Index", "Home" }) do
					Menu.Open(name)
					LKC.advance(1)
					walk(name == "Index" and pg:FindFirstChild("NimbusIndex") or (menu and menu:FindFirstChild("Window_Home")), name, bad, seen)
					pcall(Menu.Close)
					LKC.advance(0.4)
				end
				for _, tab in ipairs({ "Eggs", "Gems", "Passes" }) do
					Shop.Open({ Tab = tab })
					LKC.advance(1)
					walk(pg:FindFirstChild("NimbusShop"), "Shop " .. tab, bad, seen)
				end
				pcall(Shop.Close)
				LKC.advance(0.4)
				walk(U93.open(), "Stats", bad, seen)
				pcall(Menu.Close)
				LKC.advance(0.4)
				T.check(seen.cells > 50 and seen.lips > 10 and seen.edges > 10, tag .. ": the walk met icons, lips and edges",
					fmt("%d cells, %d lips, %d edges", seen.cells, seen.lips, seen.edges))
				T.check(#bad == 0, fmt("%s: every pixel icon cell, kit lip and kit edge is a whole number of screen px (%d off)", tag, #bad),
					table.concat(bad, "; ", 1, math.min(#bad, 14)))
				T.check(seen.bars > 0 and #seen.badBars == 0, fmt("%s: every scroll bar is the kit's one bar (wood, opaque, square ends, %d / %d px; %d seen)",
					tag, SK.Sizes.ScrollBar, SK.Sizes.ScrollBarPhone, seen.bars), table.concat(seen.badBars, "; ", 1, math.min(#seen.badBars, 10)))
				T.check(#seen.borders == 0, fmt("%s: no opaque part keeps Roblox's 1 px default border (%d do)", tag, #seen.borders),
					table.concat(seen.borders, "; ", 1, math.min(#seen.borders, 10)))
				T.check(seen.closes >= 4 and #seen.badCloses == 0, fmt("%s: every close is the pitch's x block (red face and lip, the ink edge; %d seen)", tag, seen.closes),
					table.concat(seen.badCloses, "; ", 1, math.min(#seen.badCloses, 8)))
			end)
		end
		LKC.flushErrors("kitb_whole_pixels")
	end)

	-- (Pitch 2 item F0, the owner's pick A "Carved signboard"; plan Task 1) the kit's finish: ONE light from the top left on
	-- every part. A window's wood frame is lit WoodLight on its top and left and shaded WoodDark on its bottom and right
	-- (Theme.Finish.Bevel px) and casts the window's two-step diagonal hard shadow (Finish.Window px: a darker near band, a
	-- lighter outer step, no blur); its stone body sits sunk under it with a carved rim (a StoneLip band Finish.Sink px
	-- along its top and left, the WellEdge hairline, a lit Tile line down its right edge, the carved line where frame and
	-- body meet); a raised block's wood edge has a lit / shaded line (Finish.Line px), its face a lit top band (Finish.Shine
	-- px) and it casts the card shadow (Finish.Card px); a slot / an Off block is a sunk well (no shadow); a press shows one
	-- darker frame before it sinks; a window opens by rising Finish.Rise px in Finish.RiseSteps hard steps. The finish never
	-- moves or resizes the part it finishes (the windows' layouts and fits stay). Then the walk: in the Shop, the Gifts
	-- window, the Pets window and the Index at 1920x1080 every SignKit Frame wears the bevel and the shadow, every Body the
	-- carved rim, every raised wood-edged kit block (30 px or taller) the shine
	S.finish_pass_kit = guarded("finish_pass_kit", function()
		local Theme, SK, CloudUI = LoadingH.shared("Theme"), LoadingH.shared("SignKit"), U7.client("UI/CloudUI")
		if not T.check(Theme and SK and CloudUI and type(Theme.Finish) == "table" and type(SK.Rise) == "function",
			"finish pass: Theme.Finish, SignKit (with SignKit.Rise) and CloudUI load") then
			return
		end
		local F, Sg = Theme.Finish, Theme.Sign
		T.check(F.Bevel == 3 and F.Line == 1 and F.Sink == 4 and F.Shine == 2 and F.Card == 5 and F.Window == 8 and F.Step == 2
			and F.Rise == 12 and F.RiseSteps == 3, "finish pass: the tokens (bevel 3, line 1, sink 4, shine 2, card 5, window 8, step 2, rise 12 in 3)")
		local pg = U8.pg()
		local gui = Instance.new("ScreenGui")
		gui.Name = "FinishPassProbe"
		gui.Parent = pg
		local function px(o, axis)
			return o and (axis == "X" and o.Size.X.Offset or o.Size.Y.Offset) or -1
		end
		local function shown(o)
			return o ~= nil and o.Visible ~= false
		end
		-- the light lines of a bevel holder: lit (top / left) and dark (bottom / right) `t` px thick
		local function bevelOk(holder, t, sides)
			if not (holder and holder:GetAttribute("Finish") == "Bevel" and shown(holder)) then
				return false, "no FinishBevel"
			end
			for _, s in ipairs(sides or { "LitT", "LitL", "DarkB", "DarkR" }) do
				local l = holder:FindFirstChild(s)
				local want = s:sub(1, 3) == "Lit" and Sg.WoodLight or Sg.WoodDark
				local thick = (s == "LitT" or s == "DarkB") and px(l, "Y") or px(l, "X")
				if not (l and sameColor(l.BackgroundColor3, want) and l.BackgroundTransparency == 0 and thick == t) then
					return false, s .. " " .. (l and (hex(l.BackgroundColor3) .. " " .. tostring(thick)) or "missing")
				end
			end
			return true, ""
		end
		local function shadowOk(holder, off)
			if not (holder and holder:GetAttribute("Finish") == "Shadow" and shown(holder)) then
				return false, "no FinishShadow"
			end
			local nr, nb, fr, fb = holder:FindFirstChild("NearR"), holder:FindFirstChild("NearB"), holder:FindFirstChild("FarR"), holder:FindFirstChild("FarB")
			if not (nr and nb and fr and fb) then
				return false, "a step is missing"
			end
			local near = off - F.Step
			local ok = sameColor(nr.BackgroundColor3, Sg.Text) and sameColor(fr.BackgroundColor3, Sg.Text)
				and nr.BackgroundTransparency < fr.BackgroundTransparency and fr.BackgroundTransparency < 1
				and px(fr, "X") == off and px(fb, "Y") == off and px(nr, "X") == near and px(nb, "Y") == near
				and fr.Position.X.Scale == 1 and fb.Position.Y.Scale == 1 and fr.Position.Y.Offset == off and nr.Position.Y.Offset == near
			return ok, fmt("far %d x %d @%.2f, near %d @%.2f", px(fr, "X"), px(fb, "Y"), fr.BackgroundTransparency, px(nr, "X"), nr.BackgroundTransparency)
		end

		-- the window frame and its body (SignKit.Frame / SignKit.Body)
		local win = Instance.new("Frame")
		win.Size = UDim2.fromOffset(600, 400)
		win.Parent = gui
		local head, plate = SK.Header(win, { Title = "PETS", Height = 64 })
		local wood = SK.Frame(win, { Y = 64, Height = 300 })
		local body = SK.Body(wood)
		local ok, why = bevelOk(wood:FindFirstChild("FinishBevel"), F.Bevel)
		T.check(ok, "finish pass frame: the wood frame is lit WoodLight top / left and shaded WoodDark bottom / right, 3 px", why)
		ok, why = shadowOk(wood:FindFirstChild("FinishShadow"), F.Window)
		T.check(ok, "finish pass frame: the window's two-step diagonal hard shadow (8 px, the near band darker)", why)
		T.check(wood.Size == UDim2.new(1, 0, 0, 300) and wood.Position == UDim2.fromOffset(0, 64) and body.Position == UDim2.fromOffset(SK.Sizes.Frame, SK.Sizes.Frame),
			"finish pass frame: the finish moves and resizes nothing (frame and body where they were)", tostring(wood.Size) .. " " .. tostring(body.Position))
		local carve = body:FindFirstChild("FinishCarve")
		local sinkT, sinkL, rimT, litR = carve and carve:FindFirstChild("SinkT"), carve and carve:FindFirstChild("SinkL"), carve and carve:FindFirstChild("RimT"), carve and carve:FindFirstChild("LitR")
		local lineT, lineB = carve and carve:FindFirstChild("LineT"), carve and carve:FindFirstChild("LineB")
		T.check(carve and carve:GetAttribute("Finish") == "Carve" and sinkT and sinkL and sameColor(sinkT.BackgroundColor3, Sg.StoneLip) and px(sinkT, "Y") == F.Sink and px(sinkL, "X") == F.Sink,
			"finish pass body: the stone sits sunk 4 px under the frame (a StoneLip band along its top and left)", carve and (tostring(px(sinkT, "Y")) .. " " .. tostring(px(sinkL, "X"))) or "no FinishCarve")
		T.check(rimT and sameColor(rimT.BackgroundColor3, Sg.WellEdge) and px(rimT, "Y") == F.Line and litR and sameColor(litR.BackgroundColor3, Sg.Tile) and px(litR, "X") == F.RimLit,
			"finish pass body: the carved rim (the WellEdge hairline, the lit Tile line down the right edge)")
		T.check(lineT and lineB and sameColor(lineT.BackgroundColor3, Sg.WoodDark) and sameColor(lineB.BackgroundColor3, Sg.WoodLight) and px(lineT, "Y") == F.Line,
			"finish pass body: the carved line where the frame meets the body (dark above and left, lit below and right)")
		ok, why = bevelOk(head and head:FindFirstChild("FinishBevel"), F.Bevel, { "LitT", "LitL", "DarkR" })
		T.check(ok and head.FinishBevel:FindFirstChild("DarkB") == nil, "finish pass header: the header's wood rim carries the frame's light (lit top / left, shaded right)", why)
		local top = plate and plate:FindFirstChild("FinishTop")
		T.check(top and sameColor(top.BackgroundColor3, Sg.NavyTop) and px(top, "Y") == F.Shine, "finish pass header: the navy plate's lit top line (NavyTop, 2 px)")
		-- the awning: striped, a scalloped valance hanging over the frame's rim, a wood bracket at each end; its box unchanged
		local roof = SK.Roof(win, { Width = 360, Y = -10 })
		local trim = roof:FindFirstChild("FinishTrim")
		local stripes, tabs = 0, 0
		for _, c in ipairs(trim and trim:GetChildren() or {}) do
			if c.Name:match("^Stripe%d+$") and sameColor(c.BackgroundColor3, Sg.Stone) then
				stripes = stripes + 1
			elseif c.Name:match("^Tab%d+$") then
				tabs = tabs + 1
			end
		end
		local tab1 = trim and trim:FindFirstChild("Tab1")
		T.check(trim and trim:GetAttribute("Finish") == "Awning" and stripes >= 6 and tabs >= 14 and trim:FindFirstChild("BracketL") and trim:FindFirstChild("BracketR")
			and tab1 and tab1.Position.Y.Offset + tab1.Size.Y.Offset > roof.Size.Y.Offset and roof.Size == UDim2.fromOffset(360, SK.Sizes.RoofH) and roof.Position == UDim2.new(0.5, 0, 0, -10),
			"finish pass awning: cream stripes, a scalloped valance over the rim, two wood brackets; the roof's box unchanged", fmt("%d stripes, %d tabs", stripes, tabs))

		-- a plank (SignKit.Plank): the raised block
		local plank = SK.Plank(win, { Text = "Claim!", Style = "Grass", Width = 200, Height = 56 })
		local block = plank:FindFirstChild("Block")
		local face = block and block:FindFirstChild("Face")
		ok, why = bevelOk(block and block:FindFirstChild("FinishBevel"), F.Line)
		T.check(ok, "finish pass plank: its wood edge has the 1 px lit / shaded line", why)
		local shine = face and face:FindFirstChild("FinishShine")
		T.check(shine and px(shine, "Y") == F.Shine and sameColor(shine.BackgroundColor3, Theme.Mix(Sg.Grass, Color3.new(1, 1, 1), F.ShineMix)),
			"finish pass plank: the face's lit top band (2 px, the face toward white)", shine and hex(shine.BackgroundColor3) or "none")
		ok, why = shadowOk(plank:FindFirstChild("FinishShadow"), F.Card)
		T.check(ok, "finish pass plank: the card shadow (5 px, two steps)", why)
		local rest = face and face.BackgroundColor3
		Mock.FireSignal(plank, "MouseButton1Down")
		local pressed = face and face.BackgroundColor3
		T.check(rest and pressed and not sameColor(pressed, rest) and (pressed.R + pressed.G + pressed.B) < (rest.R + rest.G + rest.B) and block.Position.Y.Offset == SK.Sizes.Sink,
			"finish pass press: a press shows one darker frame and sinks the plank", (pressed and hex(pressed) or "?") .. " vs " .. (rest and hex(rest) or "?"))
		LKC.advance(0.2)
		T.check(face and sameColor(face.BackgroundColor3, rest) and block.Position.Y.Offset == SK.Sizes.Sink, "finish pass press: ...one frame only: the face is back while it stays sunk",
			face and hex(face.BackgroundColor3) or "?")
		Mock.FireSignal(plank, "MouseButton1Up")
		local off = SK.Plank(win, { Text = "Locked", Style = "Off", Width = 200 })
		local offFace = off:FindFirstChild("Block") and off.Block:FindFirstChild("Face")
		local sunk = offFace and offFace:FindFirstChild("FinishSunk")
		T.check(sunk and sunk:FindFirstChild("ShadeT") and px(sunk.ShadeT, "Y") == F.WellShade and not shown(off:FindFirstChild("FinishShadow")),
			"finish pass well: an Off plank is a sunk well (the shaded top band) with no shadow")
		local notice = SK.Notice(win, { Text = "A tip", Width = 300 })
		T.check(shadowOk(notice:FindFirstChild("FinishShadow"), F.Card) and bevelOk(notice:FindFirstChild("FinishBevel"), F.Line), "finish pass notice: a notice card is lit and casts the card shadow")

		-- CloudUI.SignBlock (the kit block every window paints in place): the light on its wood edge (outside the box, on the
		-- edge stroke), the shine, the card shadow; once, however often it repaints
		local card = Instance.new("TextButton")
		card.Size = UDim2.fromOffset(160, 50)
		card.Parent = win
		CloudUI.SignBlock(card, "Stone")
		CloudUI.SignBlock(card, "Stone")
		local edge = card:FindFirstChild("SignEdge")
		local bev = card:FindFirstChild("FinishBevel")
		ok, why = bevelOk(bev, F.Line)
		T.check(ok and edge and bev.Position.X.Offset == -edge.Thickness and bev.Size.X.Offset == 2 * edge.Thickness,
			"finish pass block: a kit block's wood edge has the lit / shaded line on the edge stroke (outside the box)", why .. (bev and (" @" .. tostring(bev.Position)) or ""))
		local nShadow = 0
		for _, c in ipairs(card:GetChildren()) do
			if c.Name == "FinishShadow" then
				nShadow = nShadow + 1
			end
		end
		ok, why = shadowOk(card:FindFirstChild("FinishShadow"), F.Card)
		T.check(ok and nShadow == 1 and card:FindFirstChild("FinishShine"), "finish pass block: one shine and one card shadow, however often it repaints", why .. " x" .. nShadow)
		local well = Instance.new("Frame")
		well.Size = UDim2.fromOffset(160, 50)
		well.Parent = win
		CloudUI.SignBlock(well, "Stone")
		CloudUI.SignBlock(well, "Off")
		T.check(well:FindFirstChild("FinishSunk") and not shown(well:FindFirstChild("FinishShadow")) and not shown(well:FindFirstChild("FinishShine")),
			"finish pass block: repainted Off it is a sunk well (no shadow, no shine)")
		local chip = Instance.new("Frame")
		chip.Size = UDim2.fromOffset(60, 22)
		chip.Parent = win
		CloudUI.SignBlock(chip, "Selected")
		T.check(not shown(chip:FindFirstChild("FinishShadow")), "finish pass block: a chip under 30 px casts no shadow")
		local inked = Instance.new("Frame")
		inked.Size = UDim2.fromOffset(160, 50)
		inked.Parent = win
		CloudUI.SignBlock(inked, "Stone", { Edge = Sg.Text })
		T.check(not shown(inked:FindFirstChild("FinishBevel")), "finish pass block: an ink edge takes no wood light")
		-- a Sign button: one darker frame on the press
		local claim = CloudUI.Button({ Text = "Claim!", Style = "Green", Skin = "Sign", Size = UDim2.fromOffset(200, 56), Parent = win })
		local up = claim.BackgroundColor3
		Mock.FireSignal(claim, "MouseButton1Down")
		local down = claim.BackgroundColor3
		T.check((down.R + down.G + down.B) < (up.R + up.G + up.B) - 0.02, "finish pass press: a Sign button shows one darker frame on the press", hex(down) .. " vs " .. hex(up))
		LKC.advance(0.2)
		T.check(sameColor(claim.BackgroundColor3, up), "finish pass press: ...then its face again (sunk on its lip)", hex(claim.BackgroundColor3))
		Mock.FireSignal(claim, "MouseButton1Up")

		-- a Signboard window (CloudUI.Panel): its frame and body
		local panel = CloudUI.Panel({ Skin = "Signboard", Title = "Pets", Size = UDim2.fromOffset(700, 500), Parent = gui })
		ok, why = bevelOk(panel.Body:FindFirstChild("FinishBevel"), F.Bevel)
		local ok2, why2 = shadowOk(panel.Body:FindFirstChild("FinishShadow"), F.Window)
		T.check(ok and ok2 and panel.Body:FindFirstChild("Stone") and panel.Body.Stone:FindFirstChild("FinishCarve"),
			"finish pass panel: a Signboard window's frame is lit, casts the window shadow, its stone carved", why .. " / " .. why2)

		-- the open: the window rises 12 px in 3 hard steps
		local riser = Instance.new("Frame")
		riser.Position = UDim2.new(0.5, 10, 0.5, 20)
		riser.Parent = gui
		SK.Rise(riser)
		local seen, t = { riser.Position.Y.Offset }, 0
		while t < 0.6 do -- every distinct place it shows, frame by frame
			LKC.advance(0.01)
			t = t + 0.01
			if riser.Position.Y.Offset ~= seen[#seen] then
				seen[#seen + 1] = riser.Position.Y.Offset
			end
		end
		T.check(#seen == 4 and seen[1] == 32 and seen[2] == 28 and seen[3] == 24 and seen[4] == 20 and riser.Position == UDim2.new(0.5, 10, 0.5, 20),
			"finish pass open: the window rises 12 px in 3 hard steps to where it was", table.concat(seen, " > "))
		SK.Rise(riser)
		riser.Position = UDim2.new(0.5, 10, 0.5, 50) -- a layout moves it mid-rise: the layout wins
		LKC.advance(0.3)
		T.check(riser.Position == UDim2.new(0.5, 10, 0.5, 50), "finish pass open: a layout that moves the window mid-rise wins", tostring(riser.Position))
		gui:Destroy()

		-- the walk: the four windows of the mock-ups
		local Shop, Daily, PC, Menu = U7.client("Controllers/ShopController"), U7.client("Controllers/DailyController"), U7.client("Controllers/PetsController"), U7.client("Controllers/MenuController")
		if not T.check(Shop and Daily and PC and Menu, "finish pass walk: the windows load") then
			return
		end
		U8.at(1920, 1080, false, "finish pass", function(tag)
			local frames, bodies, blocks, bad, numbers, comma = 0, 0, 0, {}, 0, {}
			local function walk(root, family)
				for _, d in ipairs(root and root:GetDescendants() or {}) do
					if d:IsA("GuiObject") and U8.shown(d) then
						-- (F0: one number style) the four windows' numbers read in Theme.Short ("13.2K", "$1.45K", "5K"),
						-- never with a thousands separator ("13,213")
						if (d:IsA("TextLabel") or d:IsA("TextButton")) and type(d.Text) == "string" and d.Text:find("%d") then
							numbers = numbers + 1
							if d.Text:find("%d,%d%d%d") then
								comma[#comma + 1] = family .. ": " .. d.Name .. " '" .. d.Text .. "'"
							end
						end
						local kind = d:GetAttribute("SignKit")
						if kind == "Frame" then
							frames = frames + 1
							local b1, w1 = bevelOk(d:FindFirstChild("FinishBevel"), F.Bevel)
							local s1, w2 = shadowOk(d:FindFirstChild("FinishShadow"), F.Window)
							if not (b1 and s1) then
								bad[#bad + 1] = family .. ": " .. d.Name .. " (" .. w1 .. " / " .. w2 .. ")"
							end
						elseif kind == "Body" then
							bodies = bodies + 1
							if not d:FindFirstChild("FinishCarve") then
								bad[#bad + 1] = family .. ": " .. d.Name .. " has no carved rim"
							end
						end
						local e = d:FindFirstChild("SignEdge")
						if e and e:IsA("UIStroke") and sameColor(e.Color, Sg.Wood) and d.BackgroundTransparency == 0 and d.Size.Y.Scale == 0 and d.Size.Y.Offset >= 30
							and d:GetAttribute("SignLook") ~= "Off" and not sameColor(d.BackgroundColor3, Sg.Well) then
							blocks = blocks + 1
							if not shown(d:FindFirstChild("FinishShine")) then
								bad[#bad + 1] = family .. ": " .. d.Name .. " has no shine"
							end
						end
					end
				end
			end
			Shop.Open({ Tab = "Eggs" })
			LKC.advance(1)
			walk(pg:FindFirstChild("NimbusShop"), "Shop")
			pcall(Shop.Close)
			LKC.advance(0.4)
			pcall(Daily.Open)
			LKC.advance(1)
			walk(pg:FindFirstChild("NimbusDaily"), "Gifts")
			pcall(Daily.Close)
			LKC.advance(0.4)
			PC.Open({ Key = U8.KEYS[4] })
			LKC.advance(1)
			walk(pg:FindFirstChild("NimbusPets"), "Pets")
			PC.Close(true)
			LKC.advance(0.4)
			Menu.Open("Index")
			LKC.advance(1)
			walk(pg:FindFirstChild("NimbusIndex"), "Index")
			pcall(Menu.Close)
			LKC.advance(0.4)
			T.check(frames >= 4 and bodies >= 4 and blocks >= 10, tag .. ": the walk met the windows' frames, bodies and blocks", fmt("%d frames, %d bodies, %d blocks", frames, bodies, blocks))
			T.check(#bad == 0, fmt("%s: every frame lit and shadowed, every body carved, every raised block shined (%d off)", tag, #bad), table.concat(bad, "; ", 1, math.min(#bad, 40)))
			T.check(numbers >= 20 and #comma == 0, fmt("%s: the windows' numbers read short (Theme.Short), none with a thousands separator (%d of %d)", tag, #comma, numbers),
				table.concat(comma, "; ", 1, math.min(#comma, 20)))
		end)
		-- (look review of finish pass A, major 1: the awning hung into the header band, its scallops over the Daily's Play
		-- time tab, the Index's PET INDEX and the phone's GIFTS; the Settings window wore a full-width one off the screen)
		-- the awning SITS on the frame, as the mock's: its valance (AwningSizes.Hang under the roof's box) reaches no text,
		-- title ribbon or control of the window, it is the kit's one short centred awning (at most 360 px), and with its
		-- brackets it stays over the window and on the screen. In the Shop, Gifts, Pets, Index, Sky Trove and Settings at
		-- every grid size it shows at
		local Trove = U7.client("Controllers/TroveController")
		for _, s in ipairs(U8.SIZES) do
			U8.at(s[1], s[2], s[3], "finish awning", function(tag)
				local vp = Mock.Viewport
				local seen, bad = 0, {}
				local function check(root, family)
					for _, roof in ipairs(root and root:GetDescendants() or {}) do
						if roof:GetAttribute("SignKit") == "Roof" and U8.shown(roof) and roof:FindFirstChild("FinishTrim") then
							seen = seen + 1
							local r = U8.rect(roof)
							local sc = r.B > r.Y and (r.B - r.Y) / math.max(1, roof.Size.Y.Offset) or 1
							local hang, br = r.B + SK.AwningSizes.Hang * sc, SK.AwningSizes.Bracket * sc
							local wr = U8.rect(roof.Parent)
							if roof.Size.X.Offset > 360 then
								bad[#bad + 1] = fmt("%s: the awning is %d px wide (the kit's short awning is at most 360)", family, roof.Size.X.Offset)
							end
							if r.X - br < wr.X - 0.5 or r.R + br > wr.R + 0.5 or r.X - br < -0.5 or r.R + br > vp.X + 0.5 then
								bad[#bad + 1] = fmt("%s: the awning %d..%d runs past its window %d..%d or the screen", family, r.X - br, r.R + br, wr.X, wr.R)
							end
							for _, d in ipairs(roof.Parent:GetDescendants()) do
								local isText = (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and d.TextTransparency < 1
								local isPart = d:IsA("GuiButton") or d:GetAttribute("Ribbon") == "Band" or d:GetAttribute("Ribbon") == "Tail"
								if (isText or isPart) and U8.shown(d) and not d:IsDescendantOf(roof) and d:GetAttribute("TitleLook") ~= "Ribbon" then
									local q = U8.rect(d)
									if isText and not isPart then
										-- a label's glyphs, not its box (a header title's box is the plate's height)
										local tb = d.TextBounds
										local mid = (q.Y + q.B) / 2
										q = { X = q.X, R = q.R, Y = mid - tb.Y / 2, B = mid + tb.Y / 2 }
									end
									if q.R > r.X + 0.5 and q.X < r.R - 0.5 and q.Y < hang - 0.5 and q.B > r.Y + 0.5 then
										bad[#bad + 1] = fmt("%s: the valance (to y %.0f) reaches %s (y %.0f..%.0f)", family, hang, d.Name, q.Y, q.B)
									end
								end
							end
						end
					end
				end
				Shop.Open({ Tab = "Eggs" })
				LKC.advance(1)
				check(pg:FindFirstChild("NimbusShop"), "Shop")
				pcall(Shop.Close)
				LKC.advance(0.4)
				pcall(Daily.Open)
				LKC.advance(1)
				check(pg:FindFirstChild("NimbusDaily"), "Gifts")
				pcall(Daily.Close)
				LKC.advance(0.4)
				PC.Open({ Key = U8.KEYS[4] })
				LKC.advance(1)
				check(pg:FindFirstChild("NimbusPets"), "Pets")
				PC.Close(true)
				LKC.advance(0.4)
				Menu.Open("Index")
				LKC.advance(1)
				check(pg:FindFirstChild("NimbusIndex"), "Index")
				pcall(Menu.Close)
				LKC.advance(0.4)
				if Trove then
					pcall(Trove.Open, {})
					LKC.advance(1)
					check(pg, "Sky Trove")
					pcall(Trove.Close)
					LKC.advance(0.4)
				end
				local MMC = MenuH.mmc()
				if MMC then
					MMC.CloseWindows()
					MMC.OpenSettings()
					LKC.advance(0.6)
					check(MMC.Window(), "Settings")
					MMC.CloseWindows()
					LKC.advance(0.3)
				end
				T.check(seen >= (s[3] and 1 or 5), fmt("%s: the walk met the windows' awnings (%d)", tag, seen))
				T.check(#bad == 0, fmt("%s: every awning sits on its frame, short and centred, clear of the header (%d off)", tag, #bad),
					table.concat(bad, "; ", 1, math.min(#bad, 12)))
			end)
		end
		-- (look review of finish pass A, minor: motion not checked; the Shop, Gifts, Pets, Index and the game menu's windows
		-- rise on open, the Sky Trove and the title screen's windows did not) they open with the kit's rise: 12 px under
		-- their place on the first frame, then up in hard steps to it
		U8.at(1920, 1080, false, "finish rise", function(tag)
			local Trove = U7.client("Controllers/TroveController")
			if Trove then
				pcall(Trove.Close)
				LKC.advance(0.4)
				pcall(Trove.Open, {})
