				local y1 = panel and panel.AbsolutePosition.Y
				T.check(y0 and y1 and y0 - y1 >= 11.5 and y0 - y1 <= 12.5, tag .. ": the Sky Trove rises 12 px on open", fmt("%s -> %s", tostring(y0), tostring(y1)))
				pcall(Trove.Close)
