								end
							end
						end
					end
					for _, list in pairs(steps) do
						table.sort(list, function(a, b)
							return a.X < b.X
						end)
						for i = 2, #list do
							if list[i].X - list[i - 1].R > 0.5 then
								bad[#bad + 1] = fmt("%s volume steps %d and %d %.1f px apart", family, i - 1, i, list[i].X - list[i - 1].R)
								break
