				end
				local xs, lowest, cellH = {}, -math.huge, 0
				for _, r in ipairs(cells) do
					xs[math.floor(r.X + 0.5)] = true
					lowest = math.max(lowest, r.B)
					cellH = math.max(cellH, r.B - r.Y)
