						pt .. ": Leave is the match panel's Leave (the same size and text)",
						fmt("party %s / %s, match %s", pl and tostring(pl.AbsoluteSize) or "-", pl and tostring(pl.TextSize) or "-",
							matchLeave and fmt("%.1f, %.1f / %d", matchLeave.X, matchLeave.Y, matchLeave.Text) or "-"))
					local count, status = pin:FindFirstChild("Count"), pin:FindFirstChild("Status")
					local cl, sl = count and count:FindFirstChild("LeadIcon"), status and status:FindFirstChild("LeadIcon")
					T.check(count and count.Text == "4 / 4" and cl and cl:GetAttribute("PixelIcon") == "people" and status and sl and sl:GetAttribute("PixelIcon") == "clock"
						and tostring(status.Text):find("Starting in", 1, true) ~= nil,
						pt .. ": the countdown after the clock, the head count '4 / 4' after the people", fmt("%s | %s", status and status.Text or "-", count and count.Text or "-"))
					badge(pin, pt, 4, k)
					stars(pin:FindFirstChild("Level"), pt, 4)
					chips(pin:FindFirstChild("Players"), pt, 4, k, false)
				end
				LKC.toClient("PartyState", nil)
				LKC.advance(0.6)
			end)
		end
		LKC.flushErrors("hud_panels_signboard")
	end)

	S.vitals_stamina_blocks = guarded("vitals_stamina_blocks", function()
		local Theme = LoadingH.shared("Theme")
		local Config = LoadingH.shared("Config")
		local Sign = Theme.Sign
		local lp = game:GetService("Players").LocalPlayer
		local maxSt, cost = Config.Physics.MaxStamina, Config.Physics.DashStaminaCost
		local n = math.floor(maxSt / cost)
		local function whole(v)
			return math.abs(v - math.floor(v + 0.5)) < 0.01
		end
		local function blocksOf(bar, most)
			local out = {}
			for i = 1, most do
				out[#out + 1] = bar:FindFirstChild("Block" .. i)
			end
			return out
		end
		local function kitBlocks(blocks)
			local kit = {}
			for _, b in ipairs(blocks) do
				local face = b:FindFirstChild("Face")
				local okKit = face ~= nil and sameColor(b.BackgroundColor3, Sign.Wood) and b.BackgroundTransparency == 0 and b:FindFirstChildOfClass("UICorner") == nil
				for _, d in ipairs(b:GetDescendants()) do
					okKit = okKit and not d:IsA("UIGradient") and not d:IsA("UICorner") and not d:IsA("UIStroke")
				end
				if face then
					local fr, br = U8.rect(face), U8.rect(b)
					okKit = okKit and fr.X - br.X >= 1.5 and br.R - fr.R >= 1.5 and fr.Y - br.Y >= 1.5 and br.B - fr.B >= 1.5 -- (the face inset by the wood edge)
				end
				if not okKit then
					kit[#kit + 1] = b.Name
				end
			end
			return kit
		end
		local function equal(blocks)
			local bad = {}
