				if math.abs(b.AbsoluteSize.X - blocks[1].AbsoluteSize.X) > 0.01 then
					bad[#bad + 1] = fmt("%s %.2f px (Block1 %.2f)", b.Name, b.AbsoluteSize.X, blocks[1].AbsoluteSize.X)
				end
