				T.check(#edges == 0, fmt("%s: every wood edge a whole number of screen px (%d not)", tag, #edges), table.concat(edges, "; ", 1, math.min(#edges, 8)))
				lp:SetAttribute(Config.Attr.Stamina, maxSt)
