	-- (U9-8) the dash key (was the sky sweep ring around a gold face): a kit B keycap at the end of the stamina row with the
	-- pixel dash on it. Ready: raised on its lip, the stone tile face, the brown icon. Cooling down: pressed down onto its
	-- lip (the face drops, the lip thins), the well face, a sky charge rising from the bottom in whole-px steps as the
	-- cooldown runs out (MovementController.GetDashCooldownFraction), the icon muted; then it rises again. Out of stamina for a
	-- dash: the sunk Off key (the well face, the muted icon). Square, flat, nothing rotated, no gradient
	S.vitals_dash_key = guarded("vitals_dash_key", function()
		local Theme = LoadingH.shared("Theme")
		local Config = LoadingH.shared("Config")
		local Sign = Theme.Sign
		local lp = game:GetService("Players").LocalPlayer
		local MC = U7.client("Controllers/MovementController")
		local function whole(v)
			return math.abs(v - math.floor(v + 0.5)) < 0.01
		end
		U8.at(1920, 1080, false, "dash key", function(tag)
			lp:SetAttribute(Config.Attr.InMatch, true)
			LKC.toClient("MatchState", LKC.matchState({}))
			LKC.advance(1)
			local hud = U8.pg():FindFirstChild("NimbusHud")
			local key = hud and hud:FindFirstChild("DashKey", true)
			if not T.check(key ~= nil and U8.shown(key) and hud:FindFirstChild("DashRing", true) == nil, tag .. ": the dash key shows (the ring is gone)") then
				return
			end
			local function parts()
				local block = key:FindFirstChild("Block")
				return block, block and block:FindFirstChild("Lip"), block and block:FindFirstChild("Charge"), block and block:FindFirstChild("Icon")
			end
			local function flat()
				local bad = {}
				for _, d in ipairs(key:GetDescendants()) do
					if d:IsA("UIGradient") or d:IsA("UICorner") or (d:IsA("GuiObject") and d.Rotation ~= 0) then
						bad[#bad + 1] = d.Name .. ":" .. d.ClassName
					end
				end
				return #bad == 0, table.concat(bad, ", ")
			end
			local block, lip, charge, icon = parts()
			if not T.check(block and lip and charge and icon and icon:GetAttribute("PixelIcon") == "dash", tag .. ": the key is a block with its lip, a charge and the pixel dash") then
				return
			end
			local okFlat, why = flat()
			T.check(okFlat, tag .. ": square and flat (no gradient, corner or rotation)", why)
			local kr = U8.rect(key)
			local restTop = U8.rect(block).Y
			T.check(math.abs(restTop - kr.Y) < 0.5 and lip.AbsoluteSize.Y >= 3.5 and sameColor(block.BackgroundColor3, Sign.Tile) and not U8.shown(charge),
				tag .. ": ready: raised on its lip, the stone tile face, no charge", fmt("top %+.1f, lip %.1f, face %s", restTop - kr.Y, lip.AbsoluteSize.Y, hex(block.BackgroundColor3)))
			-- a dash: pressed, the charge rises as the cooldown runs out
			local h = LKC.hum()
			if h then
				h.MoveDirection = Vector3.new(0, 0, -1)
			end
			Mock.TriggerAction("NimbusDash", "Begin", Mock.NewInput("Q", "Keyboard", "Begin"))
			LKC.advance(0.05)
			Mock.TriggerAction("NimbusDash", "End", Mock.NewInput("Q", "Keyboard", "End"))
			if h then
				h.MoveDirection = Vector3.new(0, 0, 0)
			end
			LKC.advance(0.4)
			local cd = MC and MC.GetDashCooldownFraction and MC.GetDashCooldownFraction() or -1
			T.check(cd > 0.2 and cd < 0.95, tag .. ": the dash is cooling down (precondition)", fmt("%.2f", cd))
			local br = U8.rect(block)
			T.check(br.Y - kr.Y >= 2 and lip.AbsoluteSize.Y <= 2 and math.abs(br.B - kr.B) < 0.5 and sameColor(block.BackgroundColor3, Sign.Well),
				tag .. ": cooling: pressed onto its lip (the face down, the lip thin, the bottom kept), the well face",
				fmt("top %+.1f, lip %.1f, bottom %+.1f, face %s", br.Y - kr.Y, lip.AbsoluteSize.Y, br.B - kr.B, hex(block.BackgroundColor3)))
			local faceH = block.AbsoluteSize.Y - lip.AbsoluteSize.Y
			local want = (1 - cd) * faceH
			T.check(U8.shown(charge) and sameColor(charge.BackgroundColor3, Sign.Sky) and math.abs(charge.AbsoluteSize.Y - want) <= 3.5 and whole(charge.AbsoluteSize.Y)
				and math.abs(U8.rect(charge).B - (br.B - lip.AbsoluteSize.Y)) < 0.5,
				tag .. ": the sky charge rises from the bottom with the cooldown, in whole px", fmt("charge %.1f px, want %.1f of %.1f", charge.AbsoluteSize.Y, want, faceH))
			local cells = icon:FindFirstChildWhichIsA("Frame")
			T.check(cells and (cells.BackgroundTransparency > 0.2 or sameColor(cells.BackgroundColor3, Sign.TextMuted)), tag .. ": the icon is muted while it cools down")
			local last, grows = charge.AbsoluteSize.Y, true
			for _ = 1, 10 do
				LKC.advance(0.08)
				if charge.AbsoluteSize.Y < last - 0.5 then
					grows = false
				end
				last = charge.AbsoluteSize.Y
			end
			T.check(grows, tag .. ": the charge only grows while it cools down")
			okFlat, why = flat()
			T.check(okFlat, tag .. ": still flat while it cools down", why)
			LKC.advance(1.6)
			br = U8.rect(block)
			T.check(math.abs(br.Y - kr.Y) < 0.5 and lip.AbsoluteSize.Y >= 3.5 and sameColor(block.BackgroundColor3, Sign.Tile) and not U8.shown(charge),
				tag .. ": ready again: it rises back onto its lip, the tile face")
			-- run dry: no dash to pay for: the sunk Off key
			if h then
				h.MoveDirection = Vector3.new(0, 0, -1)
			end
			Mock.KeysDown.LeftShift = true
			Mock.TriggerAction("NimbusRun", "Begin", Mock.NewInput("LeftShift", "Keyboard", "Begin"))
			for _ = 1, 400 do
				LKC.advance(1 / 30)
				local v = lp:GetAttribute(Config.Attr.Stamina)
				if type(v) == "number" and v <= 0 then
					break
				end
			end
			LKC.advance(0.2)
			br = U8.rect(block)
			T.check(br.Y - kr.Y >= 2 and sameColor(block.BackgroundColor3, Sign.Well) and cells and (cells.BackgroundTransparency > 0.2 or sameColor(cells.BackgroundColor3, Sign.TextMuted)),
				tag .. ": out of stamina for a dash: the sunk Off key, the icon muted", fmt("stamina %s, top %+.1f, face %s", tostring(lp:GetAttribute(Config.Attr.Stamina)), br.Y - kr.Y, hex(block.BackgroundColor3)))
			Mock.KeysDown.LeftShift = false
			Mock.TriggerAction("NimbusRun", "End", Mock.NewInput("LeftShift", "Keyboard", "End"))
			if h then
				h.MoveDirection = Vector3.new(0, 0, 0)
			end
			lp:SetAttribute("Downed", true)
			LKC.advance(0.6)
			T.check(not U8.shown(key), tag .. ": downed: the key makes room for the notice")
			lp:SetAttribute("Downed", false)
			lp:SetAttribute(Config.Attr.InMatch, false)
			LKC.toClient("MatchState", nil)
			LKC.advance(4)
		end)
		LKC.flushErrors("vitals_dash_key")
	end)

	-- (U9-8; the owner's look bar) the touch RUN and DASH (were round see-through buttons with a dark cooldown overlay and a
	-- rotating shake): square kit B keycaps in the layout's boxes. DASH: the sky face on its SkyLip lip, the pixel dash over
	-- its caption; RUN: the stone tile with the pixel bolt, gold while running is on. A press sinks the face onto its lip;
	-- while the dash cools down DASH stays sunk (the well face) with a sky charge rising from the bottom in whole px, its
	-- caption still dark; with too little stamina it is the Off key. A refused press flashes the edge red and shakes the face
	-- sideways in whole px (nothing rotates). The taps themselves are client_mobile's
	S.obby_keys_mobile = guarded("obby_keys_mobile", function()
		local Theme = LoadingH.shared("Theme")
		local Config = LoadingH.shared("Config")
		local Sign = Theme.Sign
		local lp = game:GetService("Players").LocalPlayer
		local MC = U7.client("Controllers/MovementController")
		local mobile = U8.pg():FindFirstChild("MobileControls")
		if not T.check(mobile ~= nil and mobile.Enabled, "keys (phone): the touch controls are on screen (precondition)") then
			return
		end
		local dash, run = mobile:FindFirstChild("DashButton", true), mobile:FindFirstChild("RunButton", true)
		if not T.check(dash ~= nil and run ~= nil, "keys (phone): DASH and RUN exist") then
			return
		end
		local function whole(v)
			return math.abs(v - math.floor(v + 0.5)) < 0.01
		end
		local function parts(b)
			local block = b:FindFirstChild("Block")
			return block, block and block:FindFirstChild("Lip"), block and block:FindFirstChild("Charge"), block and block:FindFirstChild("Icon"),
				block and block:FindFirstChild("Label"), block and block:FindFirstChild("SignEdge")
		end
		local function flat(b)
			local bad = {}
			for _, d in ipairs(b:GetDescendants()) do
				if d:IsA("UIGradient") or (d:IsA("UICorner") and (d.CornerRadius.Scale > 0 or d.CornerRadius.Offset > 0)) or (d:IsA("GuiObject") and d.Rotation ~= 0) then
					bad[#bad + 1] = d.Name .. ":" .. d.ClassName
				end
			end
			if b:FindFirstChildOfClass("UICorner") or b.Rotation ~= 0 then
				bad[#bad + 1] = b.Name
			end
			return #bad == 0, table.concat(bad, ", ")
		end
		local function hum()
			return LKC.hum()
		end
		for _, size in ipairs({ { 844, 390 }, { 390, 844 } }) do
			Mock.SetViewport(size[1], size[2])
			LKC.advance(1)
			local tag = fmt("keys %dx%d", size[1], size[2])
			for _, spec in ipairs({ { dash, "DASH", "dash", Sign.Sky, Sign.SkyLip }, { run, "RUN", "bolt", Sign.Tile, Sign.StoneLip } }) do
				local b = spec[1]
				local block, lip, _, icon, label, edge = parts(b)
				local okFlat, why = flat(b)
				T.check(block ~= nil and lip ~= nil and icon ~= nil and label ~= nil and edge ~= nil and b.BackgroundTransparency >= 0.99 and okFlat,
					tag .. ": " .. spec[2] .. " is a square kit B keycap (a face in a wood edge on its lip; no corner, gradient or rotation)", why)
				if block and lip and icon and label and edge then
					T.check(sameColor(block.BackgroundColor3, spec[4]) and block.BackgroundTransparency == 0 and sameColor(lip.BackgroundColor3, spec[5]) and lip.AbsoluteSize.Y >= 4.5
						and block.Position.Y.Offset == 0 and sameColor(edge.Color, Sign.Wood),
						tag .. ": " .. spec[2] .. " at rest: its role's face raised on its lip", fmt("face %s, lip %s %.0f px", hex(block.BackgroundColor3), hex(lip.BackgroundColor3), lip.AbsoluteSize.Y))
					local ir, lr, br, pr = U8.rect(icon), U8.rect(label), U8.rect(block), U8.rect(lip)
					T.check(icon:GetAttribute("PixelIcon") == spec[3] and U8.shown(icon) and tostring(label.Text) == spec[2] and Theme.FontOf(label) == Theme.Fonts.Heading
						and ir.B <= lr.Y + 0.5 and ir.Y >= br.Y and lr.B <= pr.Y + 0.5 and ir.X >= br.X and ir.R <= br.R,
						tag .. ": " .. spec[2] .. ": the pixel " .. spec[3] .. " over its caption (FredokaOne), both on the face above the lip")
				end
			end
			-- a press sinks RUN onto its lip; let go, it rises gold (running is on); tap again: back to the tile
			local block, lip = parts(run)
			local dBlock0, dLip0, charge0, _, dLabel0 = parts(dash)
			if not T.check(block ~= nil and lip ~= nil and dBlock0 ~= nil and dLip0 ~= nil and charge0 ~= nil and dLabel0 ~= nil, tag .. ": the keycaps' parts (for the press checks)") then
				return
			end
			Mock.FireSignal(run, "InputBegan", Mock.NewInput("Unknown", "Touch", "Begin"), false)
			LKC.advance(0.05)
			T.check(block.Position.Y.Offset >= 2 and lip.AbsoluteSize.Y <= 3 and math.abs(U8.rect(block).B - U8.rect(run).B) < 0.5,
				tag .. ": a press sinks RUN onto its lip (the bottom kept)", fmt("down %d, lip %.0f", block.Position.Y.Offset, lip.AbsoluteSize.Y))
			Mock.FireSignal(run, "InputEnded", Mock.NewInput("Unknown", "Touch", "End"), false)
			LKC.advance(0.3)
			T.check(block.Position.Y.Offset == 0 and sameColor(block.BackgroundColor3, Sign.Gold) and sameColor(lip.BackgroundColor3, Sign.GoldLip),
				tag .. ": let go, RUN rises gold: running is on", hex(block.BackgroundColor3))
			Mock.Click(run)
			LKC.advance(0.3)
			T.check(sameColor(block.BackgroundColor3, Sign.Tile), tag .. ": tapped again, RUN is the tile again")
			-- a dash: DASH stays sunk while it cools down, the sky charge rising in whole px, its caption still dark
			local dBlock, dLip, charge, _, dLabel = parts(dash)
			if hum() then
				hum().MoveDirection = Vector3.new(0, 0, -1)
			end
			Mock.Click(dash)
			LKC.advance(0.45)
			if hum() then
				hum().MoveDirection = Vector3.new(0, 0, 0)
			end
			local cd = MC and MC.GetDashCooldownFraction and MC.GetDashCooldownFraction() or -1
			T.check(cd > 0.2 and cd < 0.95, tag .. ": the dash is cooling down (precondition)", fmt("%.2f", cd))
			local faceH = dBlock.AbsoluteSize.Y - dLip.AbsoluteSize.Y
			T.check(dBlock.Position.Y.Offset >= 2 and sameColor(dBlock.BackgroundColor3, Sign.Well) and U8.shown(charge) and sameColor(charge.BackgroundColor3, Sign.Sky)
				and math.abs(charge.AbsoluteSize.Y - (1 - cd) * faceH) <= 4.5 and whole(charge.AbsoluteSize.Y) and math.abs(U8.rect(charge).B - (U8.rect(dBlock).B - dLip.AbsoluteSize.Y)) < 0.5,
				tag .. ": cooling: DASH sunk, the well face, the sky charge rising from the bottom in whole px",
				fmt("down %d, face %s, charge %.1f of %.1f (want %.1f)", dBlock.Position.Y.Offset, hex(dBlock.BackgroundColor3), charge.AbsoluteSize.Y, faceH, (1 - cd) * faceH))
			T.check(sameColor(dLabel.TextColor3, Sign.Text) and dLabel.TextTransparency < 0.01, tag .. ": ...its caption still dark and solid (it reads on the charge)")
			local okFlat, why = flat(dash)
			T.check(okFlat, tag .. ": still flat while it cools down", why)
			LKC.advance(2)
			T.check(dBlock.Position.Y.Offset == 0 and sameColor(dBlock.BackgroundColor3, Sign.Sky) and not U8.shown(charge), tag .. ": ready again: DASH rises, the sky face")
			-- run dry: DASH is the Off key; a RUN tap is refused: a red edge, a whole-px shake, nothing rotates
			if size[1] == 844 then
				Mock.Click(run)
				if hum() then
					hum().MoveDirection = Vector3.new(0, 0, -1)
				end
				for _ = 1, 420 do
					LKC.advance(1 / 30)
					local v = lp:GetAttribute(Config.Attr.Stamina)
					if type(v) == "number" and v <= 0 then
						break
					end
				end
				LKC.advance(0.2)
				T.check(dBlock.Position.Y.Offset >= 2 and sameColor(dBlock.BackgroundColor3, Sign.Well) and sameColor(dLip.BackgroundColor3, Sign.Well) and not U8.shown(charge)
					and sameColor(dLabel.TextColor3, Sign.TextMuted),
					tag .. ": out of stamina: DASH is the sunk Off key (the well face and lip, the muted caption)",
					fmt("stamina %s, face %s", tostring(lp:GetAttribute(Config.Attr.Stamina)), hex(dBlock.BackgroundColor3)))
				local edge = select(6, parts(run))
				Mock.Click(run)
				local moved, halfPx, turned, red = 0, 0, 0, false
				for _ = 1, 12 do
					LKC.advance(1 / 30)
					moved = math.max(moved, math.abs(block.Position.X.Offset))
					if not whole(block.Position.X.Offset) then
						halfPx = halfPx + 1
					end
					if run.Rotation ~= 0 or block.Rotation ~= 0 then
						turned = turned + 1
					end
					red = red or (edge.Color.R > edge.Color.G + 0.25)
				end
				T.check(red and moved >= 1 and halfPx == 0 and turned == 0, tag .. ": a refused RUN tap flashes the edge red and shakes the face in whole px (nothing rotates)",
					fmt("red %s, moved %.1f, half px %d, turned %d", tostring(red), moved, halfPx, turned))
				LKC.advance(0.8)
				T.check(block.Position.X.Offset == 0 and sameColor(edge.Color, Sign.Wood), tag .. ": ...then it settles, the wood edge back")
				if hum() then
					hum().MoveDirection = Vector3.new(0, 0, 0)
				end
				LKC.advance(5)
			end
		end
		Mock.SetViewport(390, 844)
		LKC.advance(0.8)
		LKC.flushErrors("obby_keys_mobile")
	end)

	-- (U9-7 review) a fitted label lets go when it is destroyed. fitWidth's weak-key table must hold nothing that points back
	-- at its label: Luau has no ephemerons, so a value that closes over its key keeps the key (and the destroyed label) alive
	-- for good. The Ring's BAND tag is rebuilt on every refresh; after one, the old tag is collected like a plain TextLabel
	-- destroyed beside it (the control: the mock frees a destroyed label nothing else holds)
	S.arena_fit_labels_freed = guarded("arena_fit_labels_freed", function()
		U8.at(1920, 1080, false, "fit labels freed", function(tag)
			U97.open("ring")
			local probe = setmetatable({}, { __mode = "v" })
			-- (in its own call: a dead local of this frame would still hold the old tag during the collection)
			local function grab()
				local gui = U8.pg():FindFirstChild("NimbusArena")
				for _, d in ipairs(gui and gui:GetDescendants() or {}) do
					if d.Name == "Band" and d:IsA("TextLabel") and U8.shown(d) then
						probe.band = d
						local control = Instance.new("TextLabel")
						control.Name = "FitControl"
						control.Parent = d.Parent
						probe.control = control
						break
					end
				end
			end
			grab()
			if not T.check(probe.band ~= nil and probe.control ~= nil, tag .. ": the Ring shows its BAND tag") then
				U97.close()
				return
			end
			U8.feed() -- State.Changed: Ring.refresh destroys the old tag (and the control beside it) and builds a new one
			LKC.advance(0.4)
			collectgarbage("collect")
			collectgarbage("collect")
			T.check(probe.control == nil, tag .. ": a destroyed plain TextLabel is collected (the probe works)")
			T.check(probe.band == nil, tag .. ": the BAND tag a refresh destroyed is collected (fitWidth keeps no hold on it)")
			U97.close()
		end)
		LKC.flushErrors("arena_fit_labels_freed")
	end)

	-- (U9-7 review) a phone's dungeon LEAVE is reachable (the run chip's button is the only one a phone player has in a run):
	-- at both phone sizes, in the room fight (the battle HUD up, the HUD's strips in Roblox's top band) and in the chest
	-- alcove, after the loot toast: the chip's LEAVE shows, whole on the screen, not under the top bar's pill (it draws above
	-- the run gui: a tap there opens Settings), Roblox's "..." button, the HUD's currency strips, any part of the battle HUD
	-- or the thumbstick / jump button, and the chip stays out of the screen's centre third. The same for the party
	-- countdown's chip in the lobby (its READY), where the gift and the boost chips hang under the strips too
	S.dungeon_chip_leave_reachable = guarded("dungeon_chip_leave_reachable", function()
		local GuiService = game:GetService("GuiService")
		local function screenRect(o)
			local gui = o:FindFirstAncestorWhichIsA("LayerCollector")
			local dy = (gui and gui.IgnoreGuiInset) and 0 or Mock.TopInset
			local r = U8.rect(o)
			return { X = r.X, Y = r.Y + dy, R = r.R, B = r.B + dy }
		end
		local function solid(o)
			return o:IsA("GuiObject") and U8.shown(o) and o.AbsoluteSize.X > 4 and o.AbsoluteSize.Y > 4
		end
		for _, s in ipairs({ { 844, 390 }, { 390, 844 } }) do
			local W, Hh = s[1], s[2]
			for _, view in ipairs({ "dungeon:run", "dungeon:treasure", "dungeon:countdown" }) do
				U8.at(W, Hh, true, "dungeon chip " .. view, function(tag)
					U97.open(view)
					local pg = U8.pg()
					local chip = pg:FindFirstChild("NimbusDungeonRun") and pg.NimbusDungeonRun:FindFirstChild("RunChip")
					local leave = chip and chip:FindFirstChild("LeaveButton", true) -- (LEAVE in a run, READY in a countdown)
					if not T.check(leave ~= nil and U8.shown(leave) and leave.Text ~= "", tag .. ": the chip shows its button (" .. tostring(leave and leave.Text) .. ")") then
						U97.close()
						return
					end
					local lr, cr = screenRect(leave), screenRect(chip)
					T.check(lr.X >= -0.5 and lr.R <= W + 0.5 and lr.Y >= -0.5 and lr.B <= Hh + 0.5, tag .. ": the chip's button is whole on the screen", U8.show(lr))
					local hits = {}
					local function avoid(o, what)
						if o and solid(o) and U8.overlap(cr, screenRect(o)) then
							hits[#hits + 1] = what .. " " .. U8.show(screenRect(o))
						end
					end
					local bar = pg:FindFirstChild("NimbusTopBar")
					avoid(bar and bar.Enabled and bar:FindFirstChild("Pill"), "the top bar's pill")
					local hud = pg:FindFirstChild("NimbusHud")
					avoid(hud and hud:FindFirstChild("Currency", true), "the currency strips")
					local daily = pg:FindFirstChild("NimbusDaily")
					avoid(daily and daily.Enabled and daily:FindFirstChild("GiftsButton"), "the gift")
					local boosts = pg:FindFirstChild("NimbusBoosts")
					avoid(boosts and boosts.Enabled and boosts:FindFirstChild("BoostChips"), "the boost chips")
					local bg = pg:FindFirstChild("NimbusBattle")
					local root = bg and bg.Enabled and bg:FindFirstChild("Root")
					for _, c in ipairs(root and root:GetChildren() or {}) do
						avoid(c, "the battle HUD's " .. c.Name)
					end
					for _, d in ipairs(bg and bg.Enabled and bg:GetDescendants() or {}) do
						if d:IsA("GuiButton") then
							avoid(d, "the battle HUD's " .. d.Name)
						end
					end
					-- (Roblox's "..." button: 44 px, 12 px off the right edge, centred in the top band, as render_gui sketches it)
					local by = (Mock.TopInset - 44) / 2
					local zones = { { X = W - 56, Y = by, R = W - 12, B = by + 44, Name = "Roblox's \"...\" button" } }
					T.info(fmt("%s: the chip %s, LEAVE %s, the HUD's strips %s", tag, U8.show(cr), U8.show(lr), tostring(hud and hud:GetAttribute("CurrencyMode"))))
					if GuiService.TouchControlsEnabled ~= false then
						zones[#zones + 1] = { X = 25, Y = Hh - 90, R = 95, B = Hh - 20, Name = "the thumbstick" }
						zones[#zones + 1] = { X = W - 115, Y = Hh - 90, R = W - 45, B = Hh - 20, Name = "the jump button" }
					end
					for _, z in ipairs(zones) do
						if U8.overlap(cr, z) then
							hits[#hits + 1] = z.Name
						end
					end
					T.check(#hits == 0, fmt("%s: the chip %s is clear of the top bar, the strips, the battle HUD and Roblox's buttons (%d)", tag, U8.show(cr), #hits),
						table.concat(hits, "; ", 1, math.min(#hits, 6)))
					local cx, cy = (cr.X + cr.R) / 2, (cr.Y + cr.B) / 2
					T.check(not (cx > W / 3 and cx < 2 * W / 3 and cy > Hh / 3 and cy < 2 * Hh / 3), tag .. ": the chip is not in the screen's centre third", U8.show(cr))
					U97.close()
				end)
			end
		end
		LKC.flushErrors("dungeon_chip_leave_reachable")
	end)

	-- (U8) CloudUI.Panel's Signboard skin (Skin = "Signboard"; the Pets window and the Index wear it): the flat pink awning at a
	-- FIXED size centred on the top (never stretched with the window: Gemini's sign rule), the navy header plank in its wood
	-- rim with the title in gold through Theme.StyleTitle (stamped TitleLook), the wood frame and the stone body, the red
	-- close block with the drawn X; Panel.Content where it always was (callers' layouts do not move); no glow, gradient or
	-- corner
	S.panel_signboard_skin = guarded("panel_signboard_skin", function()
		local Theme = LoadingH.shared("Theme")
		local Sign = Theme.Sign
		local CloudUI = U7.client("UI/CloudUI")
		local SK = LoadingH.shared("SignKit")
		local gui = Instance.new("ScreenGui")
		gui.Name = "U8PanelProbe"
		gui.Parent = U8.pg()
		local function build(w, h)
			return CloudUI.Panel({ Name = "Probe", Title = "Pets", Closable = true, Skin = "Signboard", Icon = "paw", Size = UDim2.fromOffset(w, h), Parent = gui })
		end
		local a, b = build(900, 600), build(1200, 760)
		local plain = CloudUI.Panel({ Name = "Plain", Title = "Pets", Size = UDim2.fromOffset(900, 600), Parent = gui })
		LKC.advance(0.1)
		for _, p in ipairs({ a, b }) do
			local root = p.Root
			local roof = root:FindFirstChild("Roof")
			T.check(roof and roof:GetAttribute("SignKit") == "Roof" and roof.Size.X.Scale == 0 and roof.Size.Y.Scale == 0, "panel skin: a SignKit roof of fixed offset size")
			local head = nil
			for _, d in ipairs(root:GetDescendants()) do
				head = head or (d:GetAttribute("SignKit") == "Header" and d or nil)
			end
			local plate = head and head:FindFirstChild("Plate")
			T.check(head and head:GetAttribute("SignKit") == "Header" and plate and sameColor(plate.BackgroundColor3, Sign.Navy), "panel skin: the navy header plank (SignKit Header)")
			T.check(p.TitleLabel and sameColor(p.TitleLabel.TextColor3, Sign.Gold) and p.TitleLabel:GetAttribute("TitleLook") ~= nil and p.TitleLabel:GetAttribute("FontRole") == "Title",
				"panel skin: the title in gold, Title role, through Theme.StyleTitle", p.TitleLabel and hex(p.TitleLabel.TextColor3) or "no title")
			local icon = false
			for _, d in ipairs(root:GetDescendants()) do
				icon = icon or d:GetAttribute("PixelIcon") == "paw"
			end
			T.check(icon, "panel skin: the header carries the window's pixel icon (paw)")
			T.check(p.Body and sameColor(p.Body.BackgroundColor3, Sign.Wood) and p.Body.BackgroundTransparency < 0.05, "panel skin: the wood frame (Body)", p.Body and hex(p.Body.BackgroundColor3) or "")
			local stone = p.Body:FindFirstChild("Stone")
			T.check(stone and sameColor(stone.BackgroundColor3, Sign.Stone), "panel skin: the stone body inside the frame")
			T.check(p.CloseButton and U8.faceOf(p.CloseButton) and sameColor(U8.faceOf(p.CloseButton), Sign.Red) and p.CloseButton:FindFirstChild("CloseMark"),
				"panel skin: the red close block with the drawn X")
			local bad = {}
			for _, d in ipairs(root:GetDescendants()) do
				if designedLook(d) then
					-- (kit-b merge) the title's T1 ribbon (the owner's pick)
				elseif d:IsA("UIGradient") or d:IsA("UICorner") then
					bad[#bad + 1] = d.ClassName .. " on " .. d.Parent.Name
				elseif d.Name == "Glow" and d:IsA("GuiObject") and d.Visible then
					bad[#bad + 1] = "a glow on " .. d.Parent.Name
				end
			end
			T.check(#bad == 0, "panel skin: no gradient, corner or glow", table.concat(bad, ", "))
		end
		T.check(a.Root:FindFirstChild("Roof").Size == b.Root:FindFirstChild("Roof").Size, "panel skin: the roof keeps its size on a bigger window")
		T.check(a.Content.Position == plain.Content.Position and a.Content.Size == plain.Content.Size, "panel skin: Panel.Content sits where the plain panel's does")
		T.eq(SK.Sizes.RoofH, a.Root:FindFirstChild("Roof").Size.Y.Offset, "panel skin: the roof is the SignKit roof's height")
		gui:Destroy()
		LKC.flushErrors("panel_signboard_skin")
	end)

	-- (sign/logo review, SIGN2 renders) a header title's ribbon stays clear of its neighbours: at 390x844 and 844x390 the
	-- Shop, Pets, Training, Fusion, the pet picker and the Sky Trove are opened, and no piece of a visible ribbon (band,
	-- tails with their notches, underline, steps) may cross a visible sibling of the title (the Shop's egg icon, a tab or
	-- close button, a balance pill; a strip under the title's whole width and a thin rule of 4 px or less do not count) or
	-- a button of its window laid over the header (the Pets window's A/B/C),
	-- nor leave its window's frame by more than TailOver
	S.kitb_title_ribbon_clear = guarded("kitb_title_ribbon_clear", function()
		local Theme = LoadingH.shared("Theme")
		local pg = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if not T.check(Theme and Theme.TitleRibbon and pg, "kitb ribbon clear: Theme.TitleRibbon and PlayerGui exist") then
			return
		end
		local function client(path)
			local inst = Mock.GetPath(ROOTS.client .. "/" .. path)
			local ok, mod = false, nil
			if inst then
				ok, mod = pcall(require, inst)
			end
			return ok and type(mod) == "table" and mod or nil
		end
		local function shown(g)
			local p = g
			while p and not p:IsA("LayerCollector") do
				if p:IsA("GuiObject") and not p.Visible then
					return false
				end
				p = p.Parent
			end
			return p ~= nil and p.Enabled ~= false
		end
		local function rect(g)
			local p, s = g.AbsolutePosition, g.AbsoluteSize
			return { p.X, p.Y, p.X + s.X, p.Y + s.Y }
		end
		local function cross(a, b)
			return math.min(a[3], b[3]) - math.max(a[1], b[1]) > 0.5 and math.min(a[4], b[4]) - math.max(a[2], b[2]) > 0.5
		end
		-- a strip that runs under the title's whole width (the header's band, its foot) is the plate the ribbon sits on
		local function spans(outer, inner)
			return outer[1] <= inner[1] + 0.5 and outer[3] >= inner[3] - 0.5
		end
		local problems, seen = {}, {}
		local function check(where)
			for _, l in ipairs(pg:GetDescendants()) do
				if l:IsA("TextLabel") and l:GetAttribute("TitleLook") == "Ribbon" and l.TextXAlignment ~= Enum.TextXAlignment.Center and shown(l) then
					local name = l:GetFullName():gsub("^Players%.[^.]+%.PlayerGui%.", "")
					seen[#seen + 1] = where .. " " .. name
					local own = rect(l)
					local k = (tonumber(l.TextSize) or 20) / Theme.TitleRibbon.Base
					local slack = math.max(1, math.floor(Theme.TitleRibbon.TailOver * k + 0.5))
					-- the window: the title's ancestor right under its ScreenGui
					local win = l
					while win.Parent and not win.Parent:IsA("LayerCollector") do
						win = win.Parent
					end
					local frame = rect(win)
					local pieces = {}
					for _, d in ipairs(l:GetDescendants()) do
						if d:IsA("Frame") and d.BackgroundTransparency < 1 and shown(d) then
							local r = rect(d)
							if r[3] - r[1] > 0 and r[4] - r[2] > 0 then
								pieces[#pieces + 1] = { d, r }
							end
						end
					end
					-- its siblings, and every button of its window laid over the header (the Pets window's A/B/C sit on
					-- the right end of the title's box on a phone)
					local near = l.Parent:GetChildren()
					for _, b in ipairs(win:GetDescendants()) do
						if b:IsA("GuiButton") and b.Parent ~= l.Parent and not b:IsDescendantOf(l) and shown(b) then
							near[#near + 1] = b
						end
					end
					for _, sib in ipairs(near) do
						if sib ~= l and sib:IsA("GuiObject") and sib.Visible then
							local r = rect(sib)
							if r[3] - r[1] > 4 and r[4] - r[2] > 4 and not spans(r, own) then
								for _, pc in ipairs(pieces) do
									if cross(pc[2], r) then
										problems[#problems + 1] = fmt("%s %s: %s crosses %s (title x %d..%d, piece x %d..%d, %s x %d..%d)", where, name, pc[1].Name, sib.Name,
											own[1], own[3], pc[2][1], pc[2][3], sib.Name, r[1], r[3])
										break
									end
								end
							end
						end
					end
					for _, pc in ipairs(pieces) do
						local r = pc[2]
						if r[1] < frame[1] - slack or r[3] > frame[3] + slack then
							problems[#problems + 1] = fmt("%s %s: %s leaves the window by %d px", where, name, pc[1].Name,
								math.floor(math.max(frame[1] - r[1], r[3] - frame[3])))
						end
					end
				end
			end
		end
		local old = { Mock.Viewport.X, Mock.Viewport.Y }
		local windows = {
			{ "Shop", function()
				client("Controllers/ShopController").Open({ Tab = "Eggs" })
			end, function()
				client("Controllers/ShopController").Close()
			end },
			{ "Pets", function()
				client("Controllers/MenuController").Open("Pets")
			end, function()
				client("Controllers/MenuController").Close()
			end },
			{ "Training", function()
				client("Controllers/TrainController").Open({})
			end, function()
				client("Controllers/TrainController").Close()
			end },
			{ "Fusion", function()
				client("Controllers/FusionController").Open("Upgrade", {})
			end, function()
				client("Controllers/FusionController").Close()
			end },
			{ "the pet picker", function()
				client("UI/PetPicker").Open({ Context = "Train", Title = "Pick a pet to train", OnPick = function() end, OnClose = function() end })
			end, function()
				client("UI/PetPicker").Close()
			end },
			{ "the Sky Trove", function()
				client("Controllers/TroveController").Open({})
			end, function()
				client("Controllers/TroveController").Close()
			end },
			{ "the Home window", function() -- (U9-1) its Signboard header
				client("Controllers/MenuController").Open("Home")
			end, function()
				client("Controllers/MenuController").Close()
			end },
		}
		for _, size in ipairs({ { 390, 844 }, { 844, 390 } }) do
			Mock.SetViewport(size[1], size[2])
			LKC.advance(0.3)
			for _, w in ipairs(windows) do
				local ok, err = pcall(w[2])
				T.check(ok, "kitb ribbon clear: " .. w[1] .. " opens at " .. size[1] .. "x" .. size[2], tostring(err))
				LKC.advance(0.4)
				check(size[1] .. "x" .. size[2] .. " " .. w[1])
				pcall(w[3])
				LKC.advance(0.2)
			end
		end
		T.check(#seen >= 8, "kitb ribbon clear: (setup) the walk saw the header titles", table.concat(seen, "; "))
		T.check(#problems == 0, "kitb ribbon clear: no header ribbon crosses a neighbour of its title or leaves its window", table.concat(problems, "; "))
		Mock.SetViewport(old[1], old[2])
		LKC.advance(0.2)
		LKC.flushErrors("kitb_title_ribbon_clear")
	end)

	------------------------------------------------------------------------------------------------
	-- U9-1 (finding 15; BUILD_PLAN "Coverage check", U9 family 1 "Inventory"): OpenPanel("Inventory") lands on the Pets
	-- window (a Signboard since U8), and the menu window the old Inventory sat beside, the Home window (MenuController,
	-- in no other U9 family), is a kit B sign too. U9.at runs fn(tag, win) with the Home window open (a claimed home unless
	-- `noHome`) and puts the home attribute back after
	local U9 = {}
	function U9.home()
		local menu = U8.pg():FindFirstChild("NimbusMenu")
		return menu and menu:FindFirstChild("Window_Home")
	end
	-- the contrast walk's failures inside the Home window (SmokeCommon.Contrast reads the whole PlayerGui in paint order)
	function U9.contrast()
		local out = {}
		for _, line in ipairs((SmokeCommon.Contrast.Walk(U8.pg()))) do
			if line:find("Window_Home", 1, true) then
				out[#out + 1] = line
			end
		end
		return out
	end
	function U9.at(w, h, touch, label, noHome, fn)
		local Config = LoadingH.shared("Config")
		local lp = game:GetService("Players").LocalPlayer
		U8.at(w, h, touch, label, function(tag)
			local oldSpot = lp:GetAttribute(Config.Attr.SpotIndex)
			lp:SetAttribute(Config.Attr.SpotIndex, (not noHome) and 1 or nil)
			LKC.advance(0.2)
			U7.client("Controllers/MenuController").Open("Home")
			LKC.advance(1)
			local win = U9.home()
			local ok, err = pcall(function()
				if T.check(win ~= nil and U8.shown(win), tag .. ": the Home window opens") then
					fn(tag, win)
				end
			end)
			T.check(ok, tag .. ": the Home check ran", tostring(err))
			pcall(U7.client("Controllers/MenuController").Close)
			LKC.advance(0.4)
			lp:SetAttribute(Config.Attr.SpotIndex, oldSpot)
			LKC.advance(0.2)
		end)
	end

	-- the Home window on the Signboard kit at 1920x1080 and 844x390: CloudUI.Panel's Signboard skin with "My Home" as the
	-- window's T1 ribbon; the Go home hero a green kit B plank (the window's ONE green action; Claim a home when there is no
	-- home) whose title is a plain "Section" heading, as is the Prestige confirm's (the owner's ruling 2026-11-14: the ribbon
	-- is for WINDOW titles only); every summary card and station row a square block in its wood edge; nothing round; every
	-- text reads on its fill (SmokeCommon.Contrast, 3:1 from 18 px, 4.5:1 below)
	S.home_signboard_skin = guarded("home_signboard_skin", function()
		local pets = nil
		U8.at(1920, 1080, false, "inventory route", function(tag)
			LKC.toClient("OpenPanel", "Inventory", {})
			LKC.advance(1)
			pets = U8.pg():FindFirstChild("NimbusPets")
			local panel = pets and pets:FindFirstChild("Window_Pets", true)
			local skinned = false
			for _, d in ipairs(pets and pets:GetDescendants() or {}) do
				if d:GetAttribute("Skin") == "Signboard" and U8.shown(d) then
					skinned = true
				end
			end
			T.check(panel ~= nil and U8.shown(panel) and skinned, tag .. ": OpenPanel('Inventory') opens the Pets window on the Signboard skin")
		end)
		for _, s in ipairs({ { 1920, 1080, false }, { 844, 390, true } }) do
			U9.at(s[1], s[2], s[3], "home kit b", false, function(tag, win)
				local panel = win:FindFirstChild("HomePanel")
				T.check(panel ~= nil and panel:GetAttribute("Skin") == "Signboard", tag .. ": the Home window wears the Signboard skin")
				local title = panel and panel:FindFirstChild("TitleBar", true) and panel:FindFirstChild("TitleBar", true):FindFirstChild("Title", true)
				T.check(title ~= nil and title:GetAttribute("TitleLook") == "Ribbon", tag .. ": 'My Home' is the window's ribbon title",
					title and tostring(title:GetAttribute("TitleLook")) or "no title")
				local hero = win:FindFirstChild("GoHome", true)
				T.check(hero ~= nil and U8.shown(hero) and hero:GetAttribute("SignLook") == "Primary" and hero:FindFirstChildOfClass("UICorner") == nil,
					tag .. ": Go home is a green kit B plank (square, its lip, its wood edge)", hero and tostring(hero:GetAttribute("SignLook")) or "none")
				local heroTitle = hero and hero:FindFirstChild("Title", true)
				T.check(heroTitle ~= nil and heroTitle:GetAttribute("TitleLook") == "Section", tag .. ": the hero's 'Go home' is a plain Section heading, no ribbon",
					heroTitle and tostring(heroTitle:GetAttribute("TitleLook")) or "none")
				local confirmTitle = win:FindFirstChild("PrestigeConfirm", true)
				confirmTitle = confirmTitle and confirmTitle:FindFirstChild("Box") and confirmTitle.Box:FindFirstChild("Title")
				T.check(confirmTitle ~= nil and confirmTitle:GetAttribute("TitleLook") == "Section", tag .. ": the Prestige confirm's title is a plain Section heading",
					confirmTitle and tostring(confirmTitle:GetAttribute("TitleLook")) or "none")
				local greens = U8.greenActions(win)
				T.check(#greens == 1 and greens[1] == "GoHome", tag .. ": Go home is the window's one green action", table.concat(greens, ", "))
				local round, blocks, rows = {}, {}, 0
				for _, d in ipairs(win:GetDescendants()) do
					if d:IsA("UICorner") and d.Parent and d.Parent:IsA("GuiObject") and U8.shown(d.Parent) then
						round[#round + 1] = d.Parent.Name
					end
					if d:IsA("GuiObject") and U8.shown(d) and (d.Name:match("^Station_") or d.Name == "HouseCard" or d.Name == "IncomeCard" or d.Name == "PrestigeCard") then
						rows = rows + 1
						local edge = d:FindFirstChild("SignEdge")
						if d.BackgroundTransparency > 0 or not edge then
							blocks[#blocks + 1] = d.Name
						end
					end
				end
				T.check(#round == 0, tag .. ": nothing in the Home window is round (kit B is square)", table.concat(round, ", ", 1, math.min(#round, 10)))
				T.check(rows >= 6 and #blocks == 0, fmt("%s: every summary card and station row is a solid block in its wood edge (%d seen)", tag, rows), table.concat(blocks, ", "))
				local bad = U9.contrast()
				T.check(#bad == 0, fmt("%s: every text of the Home window reads on its fill (%d not)", tag, #bad), table.concat(bad, "; ", 1, math.min(#bad, 8)))
			end)
		end
		U9.at(1920, 1080, false, "home kit b, no home", true, function(tag, win)
			local greens = U8.greenActions(win)
			T.check(#greens == 1 and greens[1] == "ClaimHome", tag .. ": Claim a home is the window's one green action", table.concat(greens, ", "))
			local bad = U9.contrast()
			T.check(#bad == 0, fmt("%s: the claim steps read on their fills (%d not)", tag, #bad), table.concat(bad, "; ", 1, math.min(#bad, 8)))
		end)
		LKC.flushErrors("home_signboard_skin")
	end)

	-- the Home window on a touch phone (844x390 and 390x844): the panel inside the screen, and nothing of it under Roblox's
	-- thumbstick or jump button: the touch controls go while it is open, as the Pets window and the Index do (its station list
	-- scrolls Upgrade buttons through both bottom corners); they come back as they were on Close. The hero's texts sit inside
	-- the hero
	S.home_fits_phone = guarded("home_fits_phone", function()
		local GuiService = game:GetService("GuiService")
		for _, s in ipairs({ { 844, 390, true }, { 390, 844, true } }) do
			local before = GuiService.TouchControlsEnabled
			U9.at(s[1], s[2], s[3], "home phone", false, function(tag, win)
				local gui = win:FindFirstAncestorWhichIsA("LayerCollector")
				local panel = win:FindFirstChild("HomePanel")
				local screen = { X = 0, Y = 0, R = gui.AbsoluteSize.X, B = gui.AbsoluteSize.Y }
				local p = panel and U8.rect(panel)
				T.check(p ~= nil and p.X >= screen.X - 0.5 and p.R <= screen.R + 0.5 and p.Y >= screen.Y - 0.5 and p.B <= screen.B + 0.5,
					tag .. ": the Home window sits inside the screen", p and (U8.show(p) .. " in " .. U8.show(screen)) or "no panel")
				-- Roblox's touch controls in the window's own coordinates (HudController K: the jump button J = 70, from 1.5 J + 10 to
				-- 0.5 J + 10 off the right edge, its bottom 20 px over the bottom edge; the thumbstick's ring in the bottom-left 150 px)
				local J = 70
				local inset = gui.IgnoreGuiInset and 0 or 58
				local jump = { X = s[1] - (1.5 * J + 10), R = s[1] - (0.5 * J + 10), Y = s[2] - 20 - J - inset, B = s[2] - 20 - inset }
				local stick = { X = 0, R = 150, Y = s[2] - 150 - inset, B = s[2] - inset }
				local hidden = GuiService.TouchControlsEnabled == false
				local under = {}
				for _, b in ipairs(win:GetDescendants()) do
					if b:IsA("GuiButton") and U8.shown(b) then
						local r = U8.rect(b)
						if U8.overlap(r, jump) or U8.overlap(r, stick) then
							under[#under + 1] = b.Name .. " " .. U8.show(r)
						end
					end
				end
				-- the station list scrolls its Upgrade buttons through the bottom corners, so being clear right now is not enough:
				-- the controls go while the window is open (the list then has the whole sheet)
				T.check(hidden, tag .. ": Roblox's thumbstick and jump button go while the Home window is open (its list scrolls through their corners)",
					fmt("touch controls %s; buttons under them now: %s", tostring(GuiService.TouchControlsEnabled), table.concat(under, ", ")))
				local hero = win:FindFirstChild("GoHome", true)
				local h = hero and U8.rect(hero)
				local out = {}
				for _, l in ipairs(hero and hero:GetDescendants() or {}) do
					if l:IsA("TextLabel") and U8.shown(l) and l.Text ~= "" then
						local r = U8.rect(l)
						if r.X < h.X - 0.5 or r.R > h.R + 0.5 or r.Y < h.Y - 0.5 or r.B > h.B + 0.5 then
							out[#out + 1] = l.Name .. " " .. U8.show(r)
						end
					end
				end
				T.check(hero ~= nil and #out == 0, tag .. ": the Go home hero's texts sit inside it", table.concat(out, ", ") .. (h and (" | hero " .. U8.show(h)) or ""))
			end)
			T.eq(GuiService.TouchControlsEnabled, before, fmt("home phone %dx%d: the touch controls are back as they were after Close", s[1], s[2]))
		end
		LKC.flushErrors("home_fits_phone")
	end)

	-- the Prestige confirm on a touch phone (390x844 and 844x390), for a home ready for its FIRST star (Sky Castle, Home Level
	-- 41: the "You get" line also names the Fusion Machine, the longest it gets), opened by its Prestige button as a player
	-- does: each line's text inside its line, Prestige! and Not yet inside the box's 6 px wood edge, on the portrait phone the
	-- three lines whole in the list (sized from the real text, not an estimate: no scroll while the window has room), the box
	-- inside the screen, every text reads on its fill with the dialog up, and Prestige! the dialog's one green plank
	S.home_prestige_fits = guarded("home_prestige_fits", function()
		local ready = { Level = 41, Prestige = 0, Garden = {}, Gym = {}, CollectorCash = 0, Stations = { Press1 = 40, Garden = 8, Kitchen = 5, Gym = 5,
			Vault = 5, House = 4, FusionMachine = 3, ArenaGate = 1, DecorFence = 3, DecorFountain = 3, DecorPodium = 3 } }
		for _, s in ipairs({ { 390, 844, true }, { 844, 390, true } }) do
			U9.at(s[1], s[2], s[3], "home prestige", false, function(tag, win)
				U8.feed(nil, nil, nil, ready)
				LKC.advance(0.5)
				local button = win:FindFirstChild("Prestige", true)
				T.check(button ~= nil and button:IsA("GuiButton"), tag .. ": (setup) the Home window has its Prestige button")
				if button then
					Mock.Click(button)
					LKC.advance(0.5)
				end
				local confirm = win:FindFirstChild("PrestigeConfirm", true)
				local box = confirm and confirm:FindFirstChild("Box")
				local list = box and box:FindFirstChild("Lines")
				if not T.check(box ~= nil and list ~= nil and U8.shown(box), tag .. ": the Prestige button opens the confirm") then
					return
				end
				local gain = list:FindFirstChild("Line_Gain") and list.Line_Gain:FindFirstChild("Text")
				T.check(gain ~= nil and gain.Text:find("Fusion Machine", 1, true) ~= nil, tag .. ": (setup) the first star's 'You get' names the Fusion Machine",
					gain and gain.Text or "no Gain text")
				local function inside(r, o)
					return r.X >= o.X - 0.5 and r.R <= o.R + 0.5 and r.Y >= o.Y - 0.5 and r.B <= o.B + 0.5
				end
				local out, cut = {}, {}
				local l = U8.rect(list)
				for _, id in ipairs({ "Reset", "Keep", "Gain" }) do
					local line = list:FindFirstChild("Line_" .. id)
					local text = line and line:FindFirstChild("Text")
					if not line or not text then
						out[#out + 1] = id .. " missing"
					else
						local r, lr = U8.rect(text), U8.rect(line)
						-- the drawn text (TextBounds, screen px) fits the label's box, and the label sits in its line
						if not inside(r, lr) or text.TextBounds.Y > text.AbsoluteSize.Y + 0.5 then
							out[#out + 1] = fmt("%s text %s (%d px of text) in line %s", id, U8.show(r), text.TextBounds.Y, U8.show(lr))
						end
						if not inside(lr, l) then
							cut[#cut + 1] = id .. " " .. U8.show(lr)
						end
					end
				end
				T.check(#out == 0, tag .. ": every line's text sits inside its line", table.concat(out, "; "))
				if s[2] > s[1] then
					T.check(#cut == 0, tag .. ": the three lines are whole in the list, no scroll (the window has the room)",
						table.concat(cut, ", ") .. " | list " .. U8.show(l))
				end
				local gui = win:FindFirstAncestorWhichIsA("LayerCollector")
				local b = U8.rect(box)
				T.check(inside(b, { X = 0, Y = 0, R = gui.AbsoluteSize.X, B = gui.AbsoluteSize.Y }), tag .. ": the confirm box sits inside the screen", U8.show(b))
				-- the buttons' row is the box less its 16 px margins (the 6 px wood edge and a gap): a button wider than the row
				-- runs past the margin onto the frame
				local edge = 6 * U8.scaleOf(box)
				local row = box:FindFirstChild("Buttons")
				local inner = row and U8.rect(row) or { X = b.X + edge, Y = b.Y + edge, R = b.R - edge, B = b.B - edge }
				local spill = {}
				for _, name in ipairs({ "ConfirmPrestige", "CancelPrestige" }) do
					local btn = box:FindFirstChild(name, true)
					local r = btn and U8.rect(btn)
					if not r or not inside(r, inner) or r.X < b.X + edge or r.R > b.R - edge then
						spill[#spill + 1] = name .. " " .. (r and U8.show(r) or "missing")
					end
				end
				T.check(#spill == 0, tag .. ": Prestige! and Not yet sit inside their row, clear of the box's wood edge", table.concat(spill, ", ") .. " | row " .. U8.show(inner) .. " | box " .. U8.show(b))
				local bad = U9.contrast()
				T.check(#bad == 0, fmt("%s: every text reads on its fill with the confirm up (%d not)", tag, #bad), table.concat(bad, "; ", 1, math.min(#bad, 8)))
				local greens = U8.greenActions(confirm)
				T.check(#greens == 1 and greens[1] == "ConfirmPrestige", tag .. ": Prestige! is the dialog's one green plank", table.concat(greens, ", "))
			end)
		end
		LKC.flushErrors("home_prestige_fits")
	end)

	------------------------------------------------------------------------------------------------
	-- U9-2 (finding 15; BUILD_PLAN "Coverage check", U9 family 2 "Shop + Gems + Robux Store"): the Shop window (ShopController
	-- with its Eggs page ShopEggs and Gems page ShopGems) on the Signboard kit, and the render gate's three Shop findings:
	-- the balances shown twice (the window's pills and the HUD strips), the X over the HUD strips at 1280x720, the x3 / gem
	-- row cut by the window's bottom edge at 1280x720. U92.at runs fn(tag, win) with the Shop open on `tab`, on an account
	-- that may spin (allowed, gems settled, at the altar unless `away`), and puts everything back after
	local U92 = {}
	function U92.win()
		local gui = U8.pg():FindFirstChild("NimbusShop")
		return gui and gui:FindFirstChild("ShopWindow")
	end
	-- the contrast walk's failures inside the Shop
	function U92.contrast()
		local out = {}
		for _, line in ipairs((SmokeCommon.Contrast.Walk(U8.pg()))) do
			if line:find("NimbusShop", 1, true) then
				out[#out + 1] = line
			end
		end
		return out
	end
	-- an illustration, not a panel: the gumball machine (attribute Art), an EggArt egg (attributes Form + Rarity), the
	-- drawn cut gem (GemIcon), a pet viewport; their round shapes and tone gradients are the art
	function U92.inArt(d)
		local cur = d
		while cur and not cur:IsA("LayerCollector") do
			if cur:GetAttribute("Art") ~= nil or (cur:GetAttribute("Form") ~= nil and cur:GetAttribute("Rarity") ~= nil) or cur.Name == "GemIcon"
				or cur.Name == "GemAmount" or cur:IsA("ViewportFrame") then
				return true
			end
			cur = cur.Parent
		end
		return false
	end
	function U92.at(w, h, touch, label, tab, away, fn)
		local Shop = U7.client("Controllers/ShopController")
		local SE = U7.client("UI/ShopEggs")
		local lp = game:GetService("Players").LocalPlayer
		U8.at(w, h, touch, label, function(tag)
			local old = { lp:GetAttribute("PaidRandomItemsRestricted"), lp:GetAttribute("GemsSettled"), lp:GetAttribute("SecretPityLeft"), SE._AtAltar,
				lp:GetAttribute("StorePreview"), SE._InLobby }
			SE._InLobby = true -- (in the lobby: TRAVEL can fly)
			lp:SetAttribute("StorePreview", true) -- (the Packs / Passes / Boosts cards show as PREVIEW cards: no product is created here)
			lp:SetAttribute("PaidRandomItemsRestricted", false)
			lp:SetAttribute("GemsSettled", true)
			lp:SetAttribute("SecretPityLeft", 5)
			SE._AtAltar = not away
			LKC.advance(0.2)
			Shop.Open({ Tab = tab })
			LKC.advance(1.2)
			local win = U92.win()
			local ok, err = pcall(function()
				if T.check(win ~= nil and U8.shown(win), tag .. ": the Shop opens on " .. tab) then
					fn(tag, win)
				end
			end)
			T.check(ok, tag .. ": the Shop check ran", tostring(err))
			pcall(Shop.Close)
			LKC.advance(0.4)
			lp:SetAttribute("PaidRandomItemsRestricted", old[1])
			lp:SetAttribute("GemsSettled", old[2])
			lp:SetAttribute("SecretPityLeft", old[3])
			SE._AtAltar = old[4]
			lp:SetAttribute("StorePreview", old[5])
			SE._InLobby = old[6]
			LKC.advance(0.2)
		end)
	end
	U92.CARD = { "^ShopCard_", "^Card_", "^GemPack_", "^TokenPack_", "^GemHero$", "^GemPotion$", "^Tab_" }
	function U92.isCard(name)
		for _, p in ipairs(U92.CARD) do
			if name:match(p) then
				return true
			end
		end
		return false
	end
	-- the one green action each tab may show (the page's hero action)
	U92.GREEN = { Eggs = { Spin = true, Travel = true }, Gems = { Buy = true }, Packs = { Buy = true }, Passes = { Buy = true }, Boosts = { Buy = true } }

	-- the Shop window on the Signboard kit, every tab, at 1920x1080 and 844x390: the wood frame round a stone body, the flat
	-- awning (SignKit roof, fixed size), the navy header with "Shop" as the window's ribbon, the red close block with the drawn
	-- X, the balances as kit B tags; every tab and card a square block in its wood edge (stone, gold when selected, a hero
	-- card on the navy plank); card headings plain Section titles; nothing round but the art; at most one green action per
	-- tab, its hero's (finding 15: one colour by role); every text reads on its fill (SmokeCommon.Contrast)
	S.shop_signboard_skin = guarded("shop_signboard_skin", function()
		local Theme = LoadingH.shared("Theme")
		local Sign = Theme.Sign
		for _, s in ipairs({ { 1920, 1080, false }, { 844, 390, true } }) do
			for _, tab in ipairs({ "Eggs", "Gems", "Packs", "Passes", "Boosts" }) do
				U92.at(s[1], s[2], s[3], "shop kit b " .. tab, tab, false, function(tag, win)
					local panel = win:FindFirstChild("Panel")
					local stone = panel and panel:FindFirstChild("Stone")
					T.check(panel ~= nil and sameColor(panel.BackgroundColor3, Sign.Wood) and panel.BackgroundTransparency < 0.05 and stone ~= nil
						and sameColor(stone.BackgroundColor3, Sign.Stone), tag .. ": the window is the wood frame round a stone body",
						panel and hex(panel.BackgroundColor3) or "no Panel")
					local roof = win:FindFirstChild("Roof")
					T.check(roof ~= nil and roof:GetAttribute("SignKit") == "Roof" and roof.Size.X.Scale == 0, tag .. ": the flat awning over the top (a SignKit roof of fixed size)")
					-- (render gate, the Pets rule) no roof on a phone: over the short header it lay across the title and the pills
					T.check(roof ~= nil and U8.shown(roof) == not s[3], tag .. (s[3] and ": no roof stub over a phone's header" or ": the roof shows on a PC"))
					local header = win:FindFirstChild("Header")
					local band = header and header:FindFirstChild("Band")
					T.check(band ~= nil and sameColor(band.BackgroundColor3, Sign.Navy), tag .. ": the header is the navy sign plank", band and hex(band.BackgroundColor3) or "no Band")
					local title = header and header:FindFirstChild("Title")
					T.check(title ~= nil and title:GetAttribute("TitleLook") == "Ribbon", tag .. ": 'Shop' is the window's ribbon title")
					local close = header and header:FindFirstChild("CloseButton")
					T.check(close ~= nil and close:GetAttribute("Skin") == "Sign" and U8.faceOf(close) and sameColor(U8.faceOf(close), Sign.Red) and close:FindFirstChild("CloseMark") ~= nil,
						tag .. ": the X is the red close block with the drawn X")
					for _, id in ipairs({ "Gems", "Tokens" }) do
						local pill = header and header:FindFirstChild("Balance_" .. id)
						T.check(pill ~= nil and pill:FindFirstChild("SignEdge") ~= nil and pill.BackgroundTransparency < 0.05 and pill:FindFirstChildOfClass("UICorner") == nil,
							tag .. ": Balance_" .. id .. " is a kit B tag (a square block in its wood edge)")
					end
					local round, loose, cards = {}, {}, 0
					for _, d in ipairs(win:GetDescendants()) do
						if d:IsA("UICorner") and d.Parent and d.Parent:IsA("GuiObject") and U8.shown(d.Parent) and not U92.inArt(d) then
							round[#round + 1] = d.Parent.Name
						end
						if d:IsA("GuiObject") and U8.shown(d) and U92.isCard(d.Name) then
							cards = cards + 1
							if d.BackgroundTransparency > 0.05 or d:FindFirstChild("SignEdge") == nil then
								loose[#loose + 1] = d.Name
							end
						end
					end
					T.check(#round == 0, tag .. ": nothing in the Shop is round but its art (kit B is square)", table.concat(round, ", ", 1, math.min(#round, 10)))
					T.check(cards >= 6 and #loose == 0, fmt("%s: every tab and card is a solid block in its wood edge (%d seen)", tag, cards), table.concat(loose, ", ", 1, math.min(#loose, 10)))
					local selected = header and win:FindFirstChild("Rail") and win.Rail:FindFirstChild("Tab_" .. tab)
					T.check(selected ~= nil and sameColor(selected.BackgroundColor3, Sign.Gold), tag .. ": the selected tab is the gold block",
						selected and hex(selected.BackgroundColor3) or "no tab")
					-- card headings: plain Section titles (the ribbon is the window's name only)
					local ribbons = {}
					for _, d in ipairs(win:GetDescendants()) do
						if d:IsA("TextLabel") and d:GetAttribute("TitleLook") == "Ribbon" and d ~= title then
							ribbons[#ribbons + 1] = d:GetFullName():gsub("^.-ShopWindow%.", "")
						end
					end
					T.check(#ribbons == 0, tag .. ": no ribbon inside the Shop but its header's (card headings are Section)", table.concat(ribbons, ", "))
					-- kit B's casing rule (U6): a button reads in sentence case ("Spin", "Travel", "Preview"; the Shop is not open
					-- during kitb_casing_rule's walk, so it is checked here)
					local shouty = {}
					for _, d in ipairs(win:GetDescendants()) do
						if (d:IsA("TextLabel") or d:IsA("TextButton")) and d:GetAttribute("FontRole") == "Button" and U8.shown(d) then
							for word in tostring(d.Text):gmatch("%a+") do
								if #word >= 4 and word == word:upper() then
									shouty[#shouty + 1] = d.Parent.Name .. "." .. d.Name .. " \"" .. d.Text .. "\""
									break
								end
							end
						end
					end
					T.check(#shouty == 0, tag .. ": the Shop's buttons read in sentence case", table.concat(shouty, ", ", 1, math.min(#shouty, 6)))
					local greens = U8.greenActions(win)
					local ok = #greens == 0 or (#greens == 1 and U92.GREEN[tab][greens[1]] == true)
					T.check(ok, tag .. ": at most one green action, the page's hero action", table.concat(greens, ", "))
					local bad = U92.contrast()
					T.check(#bad == 0, fmt("%s: every text of the Shop reads on its fill (%d not)", tag, #bad), table.concat(bad, "; ", 1, math.min(#bad, 8)))
				end)
			end
		end
		-- the Eggs page's one green action is the Secret hero's: SPIN at the Storm Altar, TRAVEL away from it
		U92.at(1920, 1080, false, "shop kit b hero", "Eggs", false, function(tag, win)
			local greens = U8.greenActions(win)
			local hero = win:FindFirstChild("ShopCard_Secret", true)
			local spin = hero and hero:FindFirstChild("Spin", true)
			T.check(#greens == 1 and greens[1] == "Spin" and spin ~= nil and U8.faceOf(spin) ~= nil and U8.green(U8.faceOf(spin)),
				tag .. ": at the altar the Secret SPIN is the one green action", table.concat(greens, ", "))
