				T.check(body ~= nil and sameColor(body.BackgroundColor3, Sign.Well) and ap.Label and sameColor(ap.Label.TextColor3, Sign.TextMuted),
					tag .. ": a disabled Spin again is the sunk Off well with muted words", body and hex(body.BackgroundColor3) or "no body")
				-- (Pitch 2 item 9 B) the carved coin mutes as an own-colour icon does: every colour its grey twin (PixelIcon.Grey,
				-- the sheet's greyed-row rule); was one ink, Sign.TextMuted, which only the replaced one-ink coin could take
				local offInk, greyInk = coinInk(), tokenInk(true)
				T.check(#greyInk >= 2 and table.concat(offInk, ", ") == table.concat(greyInk, ", ") and table.concat(greyInk, ", ") ~= table.concat(wantInk, ", "),
					tag .. ": ...its coin muted with the price (greyed: PixelIcon.Grey)", table.concat(offInk, ", ") .. " / want " .. table.concat(greyInk, ", "))
				local offBad = U94.contrast("NimbusHatch")
				T.check(#offBad == 0, fmt("%s: disabled, every text still reads on its fill (%d not)", tag, #offBad), table.concat(offBad, "; ", 1, math.min(#offBad, 8)))
				-- (Pitch 2 item 9 B) a layout that resizes the coin while disabled (PixelIcon.Host draws a new icon) lands it greyed
				local c0, ts0, ph0 = ap.Coin and ap.Coin.Size.X.Offset or 30, ap.Label and ap.Label.TextSize or 22, again:GetAttribute("Phone") == true
				HL.SizePill(again, ts0, ph0, c0 + 10)
				LKC.advance(0.1)
				local resizedInk = coinInk()
				HL.SizePill(again, ts0, ph0, c0)
				LKC.advance(0.1)
				T.check(table.concat(resizedInk, ", ") == table.concat(greyInk, ", ") and table.concat(coinInk(), ", ") == table.concat(greyInk, ", "),
					tag .. ": ...and a coin redrawn by a resize while disabled lands greyed", table.concat(resizedInk, ", "))
				CloudUI.SetDisabled(again, false)
				LKC.advance(0.1)
				T.check(table.concat(coinInk(), ", ") == table.concat(wantInk, ", "), tag .. ": ...and armed again, the coin's own colours come back", table.concat(coinInk(), ", "))
				local lip = body and body:FindFirstChild("Lip")
				local k = U8.scaleOf(body)
				local rest = { lip and lip.AbsoluteSize.Y or 0, ap.Label and ap.Label.AbsolutePosition.Y or 0 }
				HL.PillState(again, "Press")
				local pressed = { lip and lip.AbsoluteSize.Y or 0, ap.Label and ap.Label.AbsolutePosition.Y or 0 }
				HL.PillState(again, "Rest")
				local back = { lip and lip.AbsoluteSize.Y or 0, ap.Label and ap.Label.AbsolutePosition.Y or 0 }
				T.check(math.abs(pressed[1] - 2 * k) <= 0.6 and pressed[2] > rest[2] + 1 and math.abs(back[1] - rest[1]) <= 0.01 and math.abs(back[2] - rest[2]) <= 0.01,
					tag .. ": a press sinks Spin again's face onto its lip (the lip 2 px, the words lower) and it comes back",
					fmt("lip %.1f -> %.1f -> %.1f, label y %.1f -> %.1f -> %.1f", rest[1], pressed[1], back[1], rest[2], pressed[2], back[2]))
				U92b.close()
				-- x3: three banded words, no glow, Done still the one green action
				ES = U92b.reveal("x3")
				content = U92b.content()
				local glow3, cols = 0, 0
				for j = 1, 3 do
					local c = content and content.Reveal:FindFirstChild("Col" .. j)
					if c and U8.shown(c) then
						cols = cols + 1
						for _, d in ipairs(c:GetDescendants()) do
							if d.Name:match("^Glow%d*$") and d:IsDescendantOf(c:FindFirstChild("Banner") or c) then
								glow3 = glow3 + 1
							end
						end
					end
				end
				T.check(cols == 3 and glow3 == 0, tag .. ": x3: three columns, no glow round their words", fmt("%d cols, %d glow parts", cols, glow3))
				local g3 = U92b.greens(content and content:FindFirstChild("BottomBar"))
				T.check(#g3 == 1 and g3[1] == "Done", tag .. ": x3: Done is the one green action", table.concat(g3, ", "))
				local r3 = U92b.roundOrGloss(content and content:FindFirstChild("Reveal"))
				T.check(#r3 == 0, tag .. ": x3: nothing round or glossy in the reveal outside the art", table.concat(r3, "; ", 1, math.min(#r3, 8)))
				local bad3 = U94.contrast("NimbusHatch")
				T.check(#bad3 == 0, fmt("%s: x3: every text reads on its fill (%d not)", tag, #bad3), table.concat(bad3, "; ", 1, math.min(#bad3, 8)))
				U92b.close()
			end)
		end
		LKC.flushErrors("hatch_signboard_skin")
	end)

	-- the hatch stage on a touch phone (844x390 and 390x844; x1 and x3 reveals): Roblox's touch controls go while the stage
	-- shows and come back as they were after Done; the bar's items inside the screen, apart (their wood edges included),
	-- each tap box >= 44 px; each plank's words and price tag inside its block; NEW! and EVOLVED's words inside their tags
	-- and the two tags apart; every text of the bar and the reveal >= 15 px. (U9-2b review) the stage lays out with the
	-- real font widths (RedoGeom.realWidth) and a tag's words are measured against its block (RedoGeom.fits: the words'
	-- label fills the tag, so a box-in-box check could not fail); an x3 roll with a NEW stage-2 pet (NEW! and EVOLVED II in
	-- one column) at 390x844, 844x390, 568x320 and 1280x720
	S.hatch_fits_phone = guarded("hatch_fits_phone", function()
		local GuiService = game:GetService("GuiService")
		local function inside(r, o)
			return r.X >= o.X - 0.5 and r.R <= o.R + 0.5 and r.Y >= o.Y - 0.5 and r.B <= o.B + 0.5
		end
		local ESM = U7.client("UI/EggStage")
		local savedMeasure = ESM and ESM.Metrics.MEASURE
		if not T.check(ESM ~= nil and RedoGeom ~= nil, "hatch phone: EggStage and RedoGeom load") then
			return
		end
		ESM.Metrics.MEASURE = function(text, size, font)
			return RedoGeom.realWidth(text, size, font)
		end
		-- a tag's words against its block with the real widths: { "Col3.EvolvedRibbon words: ..." } for each that does not fit
		local function tagWords(col, out)
			for _, t in ipairs({ col and col:FindFirstChild("New"), col and col:FindFirstChild("EvolvedRibbon") }) do
				local text = t and t:FindFirstChild("Text")
				if text and U8.shown(t) then
					local okFit, dFit = RedoGeom.fits(text)
					if not okFit then
						out[#out + 1] = col.Name .. "." .. t.Name .. " words: " .. tostring(dFit)
					end
				end
			end
		end
		for _, s in ipairs({ { 390, 844, true }, { 844, 390, true }, { 568, 320, true }, { 1280, 720, false } }) do
			U8.at(s[1], s[2], s[3], "hatch evolved II x3", function(tag)
				local ES = U92b.reveal("x3evo2")
				local content = U92b.content()
				local reveal = content and content:FindFirstChild("Reveal")
				local col = reveal and reveal:FindFirstChild("Col3")
				local new, rib = col and col:FindFirstChild("New"), col and col:FindFirstChild("EvolvedRibbon")
				local words = rib and rib:FindFirstChild("Text")
				if not T.check(ES ~= nil and new ~= nil and rib ~= nil and U8.shown(new) and U8.shown(rib) and words ~= nil and words.Text:find("II", 1, true) ~= nil,
					tag .. ": (setup) the new stage-2 pull shows NEW! and its stage-II tag", words and words.Text or "no tag") then
					return
				end
				local cramped = {}
				tagWords(col, cramped)
				if U8.overlap(U94.strokeBox(new), U94.strokeBox(rib)) then
					cramped[#cramped + 1] = "NEW! meets " .. words.Text
				end
				local cr, rr = U8.rect(col), U94.strokeBox(rib)
				if not inside(rr, cr) then
					cramped[#cramped + 1] = fmt("%s %s leaves its column %s", words.Text, U8.show(rr), U8.show(cr))
				end
				T.check(#cramped == 0, tag .. ": NEW! and the stage-II tag hold their words (real widths), apart and inside the column", table.concat(cramped, "; "))
				ES.Done()
				LKC.advance(0.6)
			end)
		end
		for _, s in ipairs({ { 844, 390 }, { 390, 844 } }) do
			for _, kind in ipairs({ "x1", "x3" }) do
				local before = GuiService.TouchControlsEnabled
				U8.at(s[1], s[2], true, "hatch phone " .. kind, function(tag)
					local ES = U92b.reveal(kind)
					local content, gui = U92b.content()
					local bar = content and content:FindFirstChild("BottomBar")
					if not T.check(ES ~= nil and bar ~= nil and U8.shown(bar), tag .. ": the reveal's bar shows") then
						return
					end
					T.check(GuiService.TouchControlsEnabled == false, tag .. ": Roblox's touch controls go while the stage shows")
					local area = gui.AbsoluteSize
					local screen = { X = 0, Y = 0, R = area.X, B = area.Y }
					local boxes, out, small = {}, {}, {}
					for _, b in ipairs(bar:GetChildren()) do
						if b:IsA("GuiButton") and U8.shown(b) then
							local r = U8.rect(b)
							local block = b:FindFirstChild("Body", true) or b:FindFirstChild("Pill")
							local box = block and U94.strokeBox(block) or r
							box.Name = b.Name
							boxes[#boxes + 1] = box
							if not inside(box, screen) then
								out[#out + 1] = b.Name .. " " .. U8.show(box)
							end
							if r.B - r.Y < 44 - 0.5 then
								small[#small + 1] = fmt("%s %.1f px tall", b.Name, r.B - r.Y)
							end
						end
					end
					T.check(#boxes >= 3 and #out == 0, tag .. ": the bar's items lie inside the screen (their wood edges included)", table.concat(out, "; "))
					T.check(#small == 0, tag .. ": every tap box of the bar is >= 44 px tall", table.concat(small, "; "))
					local meets = {}
					for i = 1, #boxes do
						for j = i + 1, #boxes do
							if U94.apart(boxes[i], boxes[j]) < 2 - 0.5 then
								meets[#meets + 1] = boxes[i].Name .. " / " .. boxes[j].Name
							end
						end
					end
					T.check(#meets == 0, tag .. ": the bar's blocks keep >= 2 px apart", table.concat(meets, "; "))
					local HL = U7.client("UI/HatchLook")
					local cramped = {}
					for _, name in ipairs({ "SpinAgain", "Done" }) do
						local b = bar:FindFirstChild(name)
						local p = b and HL.PillParts(b)
						if p and p.Body and U8.shown(b) then
							local br = U8.rect(p.Body)
							for _, part in ipairs({ p.Label, p.Chip }) do
								if part and U8.shown(part) and not inside(U8.rect(part), br) then
									cramped[#cramped + 1] = name .. "." .. part.Name
								end
							end
							if p.Chip and U8.shown(p.Chip) and p.Label and U8.overlap(U8.rect(p.Chip), { X = U8.rect(p.Label).X, Y = U8.rect(p.Label).Y, R = U8.rect(p.Label).X + p.Label.TextBounds.X, B = U8.rect(p.Label).B }) then
								cramped[#cramped + 1] = name .. ": the words run under the price tag"
							end
						end
					end
					local reveal = content:FindFirstChild("Reveal")
					for j = 1, 3 do
						local col = reveal and reveal:FindFirstChild("Col" .. j)
						local new, rib = col and col:FindFirstChild("New"), col and col:FindFirstChild("EvolvedRibbon")
						tagWords(col, cramped)
						if new and rib and U8.shown(new) and U8.shown(rib) and U8.overlap(U94.strokeBox(new), U94.strokeBox(rib)) then
							cramped[#cramped + 1] = col.Name .. ": NEW! meets EVOLVED"
						end
					end
					T.check(#cramped == 0, tag .. ": every plank's words and price tag inside its block, the tags' words inside them, the tags apart", table.concat(cramped, "; "))
					local tiny = {}
					for _, root in ipairs({ bar, reveal }) do
						for _, d in ipairs(root and root:GetDescendants() or {}) do
							if (d:IsA("TextLabel") or d:IsA("TextButton")) and U8.shown(d) and d.Text ~= "" and d.TextSize * U8.scaleOf(d) < 15 - 0.01 then
								tiny[#tiny + 1] = fmt("%s %q %.1f", d.Name, d.Text, d.TextSize * U8.scaleOf(d))
							end
						end
					end
					T.check(#tiny == 0, tag .. ": every text of the bar and the reveal is >= 15 px", table.concat(tiny, "; ", 1, math.min(#tiny, 6)))
					ES.Done()
					LKC.advance(0.6)
				end)
				T.eq(GuiService.TouchControlsEnabled, before, fmt("hatch phone %s %dx%d: the touch controls are as they were after Done", kind, s[1], s[2]))
			end
		end
		ESM.Metrics.MEASURE = savedMeasure
		LKC.flushErrors("hatch_fits_phone")
	end)

	-- (U9-2b look review 2, the owner's look bar of 2026-11-17: one pixel size, whole px, no smooth round shapes, no glow)
	-- at 1920x1080, 1280x720, 844x390 and 390x844: the stage runs no fractional UIScale (Fit 1); the strip's nails, the
	-- crack's slab, cloud puffs and stepped backlight, and the reveal's every kit block (a SignEdge: the planks, the chips,
	-- the tags, the nameplate, the slab) sit on whole px with whole-px edges; the slab, the ring, the shock, the backlight,
	-- the cracks and the leaks carry no UICorner, no UIGradient and no Rotation; the ring's motion a bob; the reveal's name
	-- and note on their navy nameplate with no outline or stroke, its lip the rarity's colour
	S.hatch_pixel_art = guarded("hatch_pixel_art", function()
		local HL = U7.client("UI/HatchLook")
		local function soft(root)
			local out = {}
			for _, d in ipairs(root and root:GetDescendants() or {}) do
				if d:IsA("UICorner") or d:IsA("UIGradient") or (d:IsA("GuiObject") and d.Rotation ~= 0) then
					out[#out + 1] = d.ClassName .. " " .. d:GetFullName():gsub("^.-%.Content%.", "")
				end
			end
			if root and root:IsA("GuiObject") and root.Rotation ~= 0 then
				out[#out + 1] = "Rotation " .. root.Name
			end
			return out
		end
		local function blocks(root, out)
			for _, d in ipairs(root and root:GetDescendants() or {}) do
				if d:IsA("UIStroke") and d.Name == "SignEdge" and d.Parent:IsA("GuiObject") and U8.shown(d.Parent) then
					out[#out + 1] = { d.Parent:GetFullName():gsub("^.-%.Content%.", ""), d.Parent }
					if math.abs(d.Thickness - math.floor(d.Thickness + 0.5)) > 1e-6 then
						out[#out + 1] = { "edge " .. d.Thickness .. " of " .. d.Parent.Name, nil }
					end
				end
			end
			return out
		end
		for _, s in ipairs({ { 1920, 1080, false }, { 1280, 720, false }, { 844, 390, true }, { 390, 844, true } }) do
			U8.at(s[1], s[2], s[3], "hatch pixel art", function(tag)
				local ES = U92b.show("x1")
				if not T.check(ES ~= nil, tag .. ": (setup) the x1 roll shows") then
					return
				end
				local content = U92b.content()
				local fit = content and content:FindFirstChild("Fit")
				T.check(fit ~= nil and fit.Scale == 1, tag .. ": the stage runs no fractional UIScale (Fit 1)", fit and tostring(fit.Scale) or "no Fit")
				-- the strip landing (before the rise slides it away): the wood frame's nails
				LKC.advance(3.45)
				local outer = content and content:FindFirstChild("Strip1", true) and content:FindFirstChild("Strip1", true):FindFirstChild("Outer")
				local nails = {}
				for i = 1, 4 do
					nails[#nails + 1] = { "Nail" .. i, outer and outer:FindFirstChild("Nail" .. i) }
				end
				local bad = U92b.offGrid(nails)
				T.check(outer ~= nil and #bad == 0, tag .. ": the rail's four nail pixels sit on whole px in its wood frame's corners", table.concat(bad, "; "))
				-- the crack: the slab, the puffs and the backlight on whole px; nothing soft, round or turned
				LKC.advance(1.45)
				local hero = content and content:FindFirstChild("Hero")
				local ped, ring, back = hero and hero:FindFirstChild("Pedestal1"), hero and hero:FindFirstChild("CloudRing1"), hero and hero:FindFirstChild("Backlight1")
				if T.check(ES.Phase() == "Crack" and ped and ring and back, tag .. ": (setup) the crack with its slab, ring and backlight", tostring(ES.Phase())) then
					local list = { { "Slab", ped:FindFirstChild("Slab") }, { "Foot", ped:FindFirstChild("Foot") } }
					for _, puff in ipairs(ring:GetChildren()) do
						for _, row in ipairs(puff:GetChildren()) do
							if row:IsA("Frame") then
								list[#list + 1] = { puff.Name .. "." .. row.Name, row }
							end
						end
					end
					for _, p in ipairs(back:GetChildren()) do
						list[#list + 1] = { "Backlight." .. p.Name, p }
					end
					bad = U92b.offGrid(list)
					T.check(#bad == 0 and #list >= 20, tag .. ": the slab, the cloud puffs' rows and the stepped backlight sit on whole px", fmt("%d parts; %s", #list, table.concat(bad, "; ")))
					-- (kit-b gate U9 round 3: two navy slabs read as empty nameplates) a plinth: a wood top in its dark wood edge with
					-- a light top row, on a stone base
					local Sign = LoadingH.shared("Theme").Sign
					local slab, foot = ped:FindFirstChild("Slab"), ped:FindFirstChild("Foot")
					local shine = slab and slab:FindFirstChild("Shine")
					T.check(slab and foot and sameColor(slab.BackgroundColor3, Sign.Wood) and sameColor(slab.SignEdge.Color, Sign.WoodDark)
						and shine ~= nil and sameColor(shine.BackgroundColor3, Sign.WoodLight) and sameColor(foot.BackgroundColor3, Sign.Stone),
						tag .. ": the plinth is a wood top (dark wood edge, light top row) on a stone base",
						slab and foot and fmt("slab %s edge %s shine %s, foot %s", hex(slab.BackgroundColor3), hex(slab.SignEdge.Color), shine and hex(shine.BackgroundColor3) or "none", hex(foot.BackgroundColor3)) or "missing")
					local egg = hero:FindFirstChild("Egg1")
					local softs = {}
					for _, root in ipairs({ ped, ring, back, hero:FindFirstChild("Spot") or false, egg and egg:FindFirstChild("Cracks") or false, egg and egg:FindFirstChild("Leaks") or false }) do
						if root then
							for _, x in ipairs(soft(root)) do
								softs[#softs + 1] = x
							end
						end
					end
					local burst = content:FindFirstChild("Burst")
					for _, x in ipairs(soft(burst and burst:FindFirstChild("Shock"))) do
						softs[#softs + 1] = x
					end
					T.check(#softs == 0 and hero:FindFirstChild("Spot") == nil and ring:FindFirstChild("Bob") ~= nil, tag .. ": no UICorner, gradient or turn in the slab, the ring (it bobs), the backlight, the shock, the cracks or the leaks; no spot cone",
						table.concat(softs, "; "))
				end
				U92b.close()
				-- the reveal: every kit block on whole px with a whole-px edge; the nameplate
				ES = U92b.reveal("x1")
				content = U92b.content()
				local reveal, bar = content and content:FindFirstChild("Reveal"), content and content:FindFirstChild("BottomBar")
				local list = blocks(reveal, {})
				blocks(bar, list)
				blocks(hero and content:FindFirstChild("Hero"), list)
				bad = U92b.offGrid(list)
				T.check(#list >= 6 and #bad == 0, tag .. ": every kit block of the reveal (planks, chips, tags, the nameplate, the slab) on whole px with a whole-px edge", fmt("%d blocks; %s", #list, table.concat(bad, "; ")))
				local col = reveal and reveal:FindFirstChild("Col1")
				local plate, name, note = col and col:FindFirstChild("Plate"), col and col:FindFirstChild("Name"), col and col:FindFirstChild("Note")
				local function mid(o)
					return o.AbsolutePosition.Y + o.AbsoluteSize.Y / 2
				end
				local inside = plate and name and note and mid(name) > plate.AbsolutePosition.Y and mid(note) < plate.AbsolutePosition.Y + plate.AbsoluteSize.Y
				T.check(plate and U8.shown(plate) and inside and name:FindFirstChildOfClass("UIStroke") == nil and name.TextStrokeTransparency >= 0.99 and note:FindFirstChildOfClass("UIStroke") == nil
					and plate:FindFirstChild("Lip") and hex(plate.Lip.BackgroundColor3) == hex(HL.RarityColor("Epic")),
					tag .. ": the name and the note stand on their navy nameplate (no outline, no stroke), its lip the rarity's colour", plate and "" or "no Plate")
				U92b.close()
			end)
		end
		LKC.flushErrors("hatch_pixel_art")
	end)

	------------------------------------------------------------------------------------------------
	-- U9-9 (finding 15; BUILD_PLAN U9 family 9 "toasts, tutorial and NPC talk"): NotifyController's toasts and match result
	-- card, TutorialController's card / bubble / menu pointer, NpcController's dialog and MouseLock's "press L" hint on the
	-- Signboard kit (the owner's look bar of 2026-11-17: one pixel size per screen, whole-pixel icons and edges, every bar
	-- in the block language, no glow, no rounded corner, no gradient)
	function U99.gui(name)
		return U8.pg():FindFirstChild(name)
	end
	-- the four toast kinds, as dump_gui's toasts scenario sends them; -> { [kind] = the Toast card }
	U99.TOASTS = { { "Welcome back to Nimbus Climb!", "info" }, { "Checkpoint 2/4 reached!", "good" }, { "Not enough cloud tokens", "bad" },
		{ "+25 cloud tokens", "token" } }
	function U99.toasts()
		for _, t in ipairs(U99.TOASTS) do
			LKC.toClient("Notify", t[1], t[2], 5)
			LKC.advance(0.15)
		end
		LKC.advance(0.9)
		local out = {}
		local gui = U99.gui("NimbusNotify")
		for _, d in ipairs(gui and gui:GetDescendants() or {}) do
			if d.Name == "Toast" and d:IsA("GuiObject") and U8.shown(d) then
				local icon = d:FindFirstChild("Icon")
				local kind = icon and icon:GetAttribute("Kind")
				if kind then
					out[kind] = d
				end
			end
		end
		return out
	end
	function U99.clearToasts()
		LKC.advance(6)
	end
	-- the match result card (dump_gui's results / results:loss payloads) -> the ResultCard root
	function U99.results(won)
		local Config = LoadingH.shared("Config")
		local lp = game:GetService("Players").LocalPlayer
		lp:SetAttribute(Config.Attr.InMatch, true)
		LKC.toClient("MatchState", LKC.matchState())
		LKC.advance(0.5)
		if won then
			LKC.toClient("MatchResult", {
				Won = true, Reason = "victory", Seconds = 187, MatchTokens = 11, Bonus = 10, DifficultyId = "Easy", DifficultyName = "Easy",
				Stars = 1, TotalTokens = 24,
				Members = { { Name = lp.Name, MatchTokens = 11, Finished = true, Downed = false }, { Name = "Buddy", MatchTokens = 6, Finished = true, Downed = false } },
			})
		else
			LKC.toClient("MatchResult", {
				Won = false, Reason = "timeout", Seconds = 300, MatchTokens = 4, Bonus = 0, DifficultyId = "Medium", DifficultyName = "Medium",
				Stars = 2, TotalTokens = 4,
				Members = { { Name = lp.Name, MatchTokens = 4, Finished = false, Downed = false }, { Name = "Buddy", MatchTokens = 2, Finished = false, Downed = true },
					{ Name = "Cirrus", MatchTokens = 1, Finished = false, Downed = true }, { Name = "Nimbo", MatchTokens = 3, Finished = false, Downed = false } },
			})
		end
		LKC.advance(1.5)
		local gui = U99.gui("NimbusNotify")
		local holder = gui and gui:FindFirstChild("ResultHolder", true)
		local card = nil
		for _, d in ipairs(holder and holder:GetDescendants() or {}) do
			if d.Name == "ResultCard" and U8.shown(d) then
				card = d
			end
		end
		return card
	end
	function U99.closeResults()
		local Config = LoadingH.shared("Config")
		LKC.toClient("MatchState", nil)
		game:GetService("Players").LocalPlayer:SetAttribute(Config.Attr.InMatch, false)
		LKC.advance(1)
	end
	-- dump_gui's TutorialState payload for step `index`
	function U99.tutorialPayload(index)
		local Steps = LoadingH.shared("TutorialSteps")
		local Config = LoadingH.shared("Config")
		local list = Steps.Steps
		index = math.max(1, math.min(#list, index))
		local step = list[index]
		local cfg = Config.Tutorial or {}
		local text = tostring(step.Text or "")
		text = (text:gsub("{GiftTokens}", tostring(cfg.GiftTokens or 0)))
		text = (text:gsub("{FinishTokens}", tostring((cfg.FinishReward or {}).Tokens or 0)))
		text = (text:gsub("{RaidMinutes}", "20"))
		return { Step = index, Total = #list, Id = step.Id, Title = step.Title, Text = text, Target = step.Target, Chapter = step.Chapter or 1,
			CompleteOn = step.CompleteOn, Hint = step.Hint, Button = step.Button, Gift = step.Gift == true, Done = false, Completed = false,
			Skipped = false, Reward = 0 }
	end
	-- the tutorial on step `index`; open: the card tapped open when the screen folded it -> gui, the TutorialPanel root
	function U99.tutorial(index, open)
		-- each call starts from Nimbus' own choice: a card an earlier call opened stays open by design (manual
		-- "expanded"), so it is folded first (manual "collapsed"), and the step's new words after a finished tutorial
		-- reset that
		local g0 = U99.gui("NimbusTutorial")
		local fold, main0 = g0 and g0:FindFirstChild("Fold", true), g0 and g0:FindFirstChild("Main", true)
		if fold and main0 and U8.shown(main0) then
			Mock.Click(fold)
			LKC.advance(0.5)
		end
		U99.tutorialOff()
		LKC.toClient("TutorialState", U99.tutorialPayload(index))
		LKC.advance(3)
		local gui = U99.gui("NimbusTutorial")
		local root = gui and gui:FindFirstChild("TutorialPanel")
		local main = root and root:FindFirstChild("Main", true)
		local toggle = root and root:FindFirstChild("Toggle", true)
		if open and main and not main.Visible and toggle then
			Mock.Click(toggle)
			LKC.advance(1)
		end
		return gui, root
	end
	function U99.tutorialOff()
		local n = #LoadingH.shared("TutorialSteps").Steps
		LKC.toClient("TutorialState", { Step = n, Total = n, Id = "done", Text = "", Done = true, Completed = false, Skipped = true, Reward = 0 })
		LKC.advance(1)
	end
	-- the NPCs (NpcService on a ring round the lobby origin, as smoke_audio and dump_gui stand them) and the dialog of NPC
	-- `index` opened in front of it -> the NpcDialog root
	function U99.npc(index)
		local ND = LoadingH.shared("NpcDialog")
		local Config = LoadingH.shared("Config")
		local NC = U7.client("Controllers/NpcController")
		local inst = Mock.GetPath(ROOTS.server .. "/Services/NpcService")
		local okNs, NS = false, nil
		if inst then
			okNs, NS = pcall(require, inst)
		end
		if not (ND and NC and okNs and type(NS) == "table") then
			return nil
		end
		local origin = (Config.Lobby and Config.Lobby.Origin) or Vector3.new(0, 10, 0)
		local spots = {}
		for i = 1, #ND.Npcs do
			local a = (i - 1) * math.pi * 2 / #ND.Npcs
			local pos = origin + Vector3.new(math.cos(a) * 30, 0, math.sin(a) * 30)
			spots[i] = CFrame.lookAt(pos, Vector3.new(origin.X, pos.Y, origin.Z))
		end
		if not game:GetService("Workspace"):FindFirstChild("NimbusNpcs") then
			NS.Init({ NpcSpots = spots })
			LKC.advance(2)
		end
		index = index or 1
		Mock.Teleport(game:GetService("Players").LocalPlayer, spots[index].Position + spots[index].LookVector * 7 + Vector3.new(0, 3, 0))
		LKC.advance(0.5)
		NC.Open(ND.Npcs[index].Id)
		LKC.advance(4)
		local gui = U99.gui("NimbusNpcDialog")
		return gui and gui:FindFirstChild("NpcDialog")
	end
	function U99.npcClose()
		local NC = U7.client("Controllers/NpcController")
		if NC then
			pcall(NC.Close)
		end
		LKC.advance(0.8)
	end
	function U99.npcGone()
		local holder = game:GetService("Workspace"):FindFirstChild("NimbusNpcs")
		if holder then
			holder:Destroy()
		end
		Mock.Teleport(game:GetService("Players").LocalPlayer, Vector3.new(0, 20, 0))
		LKC.advance(0.5)
	end
	-- the "press L" hint on a desktop (MouseLock locked once, its session hint reset) -> the Hint label, a restore()
	function U99.mouseHint()
		local UIS = game:GetService("UserInputService")
		local ML = U7.client("MouseLock")
		if not (ML and type(ML._St) == "table") then
			return nil, function() end
		end
		local old = { UIS.TouchEnabled, UIS.KeyboardEnabled, UIS.MouseEnabled, ML.IsEnabled() }
		UIS.TouchEnabled, UIS.KeyboardEnabled, UIS.MouseEnabled = false, true, true
		ML.Start()
		ML.SetEnabled(true)
		ML._St.Hinted = false
		ML.Hold("u99:hint")
		ML.Release("u99:hint")
		LKC.advance(0.8)
		local gui = U99.gui(ML.HINT_GUI)
		local function restore()
			ML.Hold("u99:hint") -- the hint goes at once on a hold
			ML.Release("u99:hint")
			ML._St.Hinted = true
			ML.SetEnabled(old[4])
			UIS.TouchEnabled, UIS.KeyboardEnabled, UIS.MouseEnabled = old[1], old[2], old[3]
			UIS.MouseBehavior = Enum.MouseBehavior.Default
			UIS.MouseIconEnabled = true
			LKC.advance(0.3)
		end
		return gui and gui:FindFirstChild("Hint"), restore
	end
	-- every view of the family, one after another: look(root, name) after each (the walks of kitb_no_neon_glow and
	-- kitb_no_emoji_ui); desktop: the "press L" hint too
	function U99.walkFamily(desktop, look)
		U99.toasts()
		look(U99.gui("NimbusNotify"), "Toasts")
		U99.clearToasts()
		for _, won in ipairs({ true, false }) do
			look(U99.results(won), won and "Result card (won)" or "Result card (lost)")
			U99.closeResults()
		end
		local gui = U99.tutorial(5, true)
		look(gui, "Tutorial card")
		look(U99.gui("NimbusTutorialPointer"), "Tutorial pointer")
		local fold = gui and gui:FindFirstChild("Fold", true)
		if fold and U8.shown(fold) then
			Mock.Click(fold)
			LKC.advance(1)
		end
		look(gui, "Tutorial bubble")
		U99.tutorialOff()
		look(U99.npc(1), "NPC dialog")
		U99.npcClose()
		U99.npcGone()
		if desktop then
			local hint, restore = U99.mouseHint()
			look(hint and hint.Parent, "Mouse hint")
			restore()
		end
	end
	-- Roblox's jump button and thumbstick (6 px round them) in a gui of `area` (trove_fits_phone's zones)
	function U99.zones(area, portrait)
		local J = 70
		return {
			{ Name = "jump", X = area.X - (1.5 * J + 10) - 6, R = area.X - (0.5 * J + 10) + 6, Y = area.Y - 20 - J - 6, B = area.Y - 20 + 6 },
			{ Name = "thumbstick", X = 0, R = 110 + 6, Y = area.Y - (portrait and 150 or 96) - 6, B = area.Y },
		}
	end
	-- the shown MobileControls buttons (RUN / DASH) as rects in the space of `gui` (an inset gui or not); Ring = the rect
	-- with the button's stroke round it
	function U99.mobile(gui)
		local out = {}
		local mobile = U99.gui("MobileControls")
		if not (mobile and mobile.Enabled) then
			return out
		end
		local inset = Mock.TopInset or 0
		local dy = (mobile.IgnoreGuiInset and 0 or inset) - (gui.IgnoreGuiInset and 0 or inset)
		for _, d in ipairs(mobile:GetDescendants()) do
			if d:IsA("GuiButton") and U8.shown(d) and d.AbsoluteSize.X > 0 then
				local r = U8.rect(d)
				local stroke = d:FindFirstChildOfClass("UIStroke")
				local s = stroke and stroke.Enabled ~= false and stroke.Thickness or 0
				out[#out + 1] = { Name = d.Name, X = r.X, R = r.R, Y = r.Y + dy, B = r.B + dy,
					Ring = { X = r.X - s, R = r.R + s, Y = r.Y + dy - s, B = r.B + dy + s } }
			end
		end
		return out
	end
	-- (U9-9 review) the phones of the family's fit checks: the common landscape phone, the short ones (where the result card,
	-- the toasts and the NPC dialog run out of room first), a big one and a portrait one
	U99.PHONES = { { 844, 390 }, { 800, 360 }, { 740, 360 }, { 667, 375 }, { 640, 360 }, { 932, 430 }, { 390, 844 } }
	-- U8.at on a touch phone with the game's real RUN / DASH (MovementController builds them there: the client world boots as a
	-- desktop, so it has none of its own), laid out for the size and measured by the HUD; they go again after fn
	function U99.atPhone(w, h, label, fn)
		U8.at(w, h, true, label, function(tag)
			local MC = U7.client("Controllers/MovementController")
			local mobile = MC and MC._TouchButtons and MC._TouchButtons(true)
			LKC.advance(1.2) -- the HUD's layout poll: the vitals card steps round the buttons
			local names = {}
			for _, b in ipairs(mobile and U99.mobile(mobile) or {}) do
				names[b.Name] = true
			end
			T.check(names.RunButton and names.DashButton, tag .. ": the game's RUN and DASH are on the screen (MovementController's MobileControls)")
			local ok, err = pcall(fn, tag)
			if MC and MC._TouchButtons then
				MC._TouchButtons(false)
			end
			if not ok then
				error(err, 0)
			end
		end)
	end
	-- the shown filled blocks of the HUD's top-right stack (token pill, gift) `r` lies over (names), in the space of `gui`
	function U99.overTopRight(gui, r)
		local hits = {}
		local hud = U99.gui("NimbusHud")
		local stack = hud and hud:FindFirstChild("TopRight")
		if not stack then
			return hits
		end
		local inset = Mock.TopInset or 0
		local dy = (hud.IgnoreGuiInset and 0 or inset) - (gui.IgnoreGuiInset and 0 or inset)
		for _, d in ipairs(stack:GetDescendants()) do
			if d:IsA("GuiObject") and U8.shown(d) and d.BackgroundTransparency < 1 and d.AbsoluteSize.X > 0 then
				local b = U8.rect(d)
				b = { X = b.X, R = b.R, Y = b.Y + dy, B = b.B + dy }
				if U8.overlap(r, b) then
					hits[#hits + 1] = d.Name .. " " .. U8.show(b)
				end
			end
		end
		return hits
	end
	-- the zones and touch buttons `r` lies over (names), for a touch screen. under: { [button name] = true } for a button
	-- that may lie wholly under `r` with its stroke (the U9-4 rule: wholly under or wholly clear, never a sliver)
	function U99.overTouch(gui, r, portrait, under)
		local hits = {}
		for _, z in ipairs(U99.zones(gui.AbsoluteSize, portrait)) do
			if U8.overlap(r, z) then
				hits[#hits + 1] = z.Name .. " " .. U8.show(z)
			end
		end
		for _, b in ipairs(U99.mobile(gui)) do
			if under and under[b.Name] then
				local o = b.Ring
				local inside = o.X >= r.X - 0.5 and o.R <= r.R + 0.5 and o.Y >= r.Y - 0.5 and o.B <= r.B + 0.5
				if not inside and U8.overlap(r, o) then
					hits[#hits + 1] = b.Name .. " partly under " .. U8.show(o)
				end
			elseif U8.overlap(r, b) then
				hits[#hits + 1] = b.Name .. " " .. U8.show(b)
			end
		end
		return hits
	end
	-- the shown texts under `root` outside `box` (a rect) or under 14 screen px
	function U99.texts(root, box)
		local out, small = {}, {}
		for _, d in ipairs(root:GetDescendants()) do
			if (d:IsA("TextLabel") or d:IsA("TextButton")) and U8.shown(d) and d.Text ~= "" then
				local r = U8.rect(d)
				if r.X < box.X - 0.5 or r.R > box.R + 0.5 or r.Y < box.Y - 0.5 or r.B > box.B + 0.5 then
					out[#out + 1] = d.Name .. " " .. U8.show(r)
				end
				-- a TextScaled label ignores TextSize: its floor is its UITextSizeConstraint's MinTextSize
				local size = d.TextSize
				if d.TextScaled then
					local limit = d:FindFirstChildOfClass("UITextSizeConstraint")
					size = limit and limit.MinTextSize or math.floor(d.AbsoluteSize.Y / math.max(0.01, U8.scaleOf(d)))
				end
				if size * U8.scaleOf(d) < 14 - 0.01 then
					small[#small + 1] = fmt("%s %.1f px", d.Name, size * U8.scaleOf(d))
				end
			end
		end
		return out, small
	end
	-- the screen px of one icon cell under `root`: a 2 px design cell at the scale above it, rounded (PixelCrisp)
	-- (U9-9 look) a 2 px cell never drops to 1 px: one pixel size per screen (PixelCrisp.Px)
	function U99.cell(obj)
		return math.max(2, math.floor(2 * U8.scaleOf(obj) + 0.5))
	end
	-- U94.pixelCells measured by height: a PixelIcon.Lead box of two or more icons is wider than 9 cells (its icons and
	-- their gaps) but always 9 cells tall, so its cell is its height / 9
	function U99.pixelCells(root, allowed)
		local seen, odd = {}, {}
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("Frame") and d:GetAttribute("PixelIcon") and U8.shown(d) and d.AbsoluteSize.Y > 0 then
				local c = d.AbsoluteSize.Y / 9
				local key = fmt("%.2f", c)
				seen[key] = true
				local ok = false
				for _, a in ipairs(allowed) do
					ok = ok or math.abs(c - a) < 0.01
				end
				if not ok then
					odd[#odd + 1] = fmt("%s %s (%s px cells)", d.Parent and d.Parent.Name or "?", tostring(d:GetAttribute("PixelIcon")), key)
				end
			end
		end
		local list = {}
		for k in pairs(seen) do
			list[#list + 1] = k
		end
		table.sort(list)
		return list, odd
	end
	-- (U9-9 look) the shown blocks under `root` whose edges, or a wood edge's thickness, are off the whole-pixel grid (the
	-- owner's look bar: whole pixels, one pixel size per screen). (U9-9 look 2) A block is any shown frame with a face (an
	-- opaque fill: the card, the stone in its wood frame, a well, a tag, a plank, the sky in a portrait), a SignEdge, a lip,
	-- a pixel icon or a name in `names`, and all four of its edges are checked (X, Y, R, B: a block's right and bottom
	-- edges drew soft while its top-left was whole); the result card's confetti (flying pieces) aside
	function U99.offGrid(root, names)
		local out = {}
		local function frac(v)
			return math.abs(v - math.floor(v + 0.5)) > 0.02
		end
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("GuiObject") and U8.shown(d) and d.AbsoluteSize.X > 0 and d.Name ~= "Confetti" then
				local named = names and names[d.Name]
				local block = d.BackgroundTransparency < 1 or d:FindFirstChild("SignEdge") ~= nil or d.Name == "Lip" or d:GetAttribute("PixelIcon") ~= nil or named
				if block then
					local r = U8.rect(d)
					if frac(r.X) or frac(r.Y) or frac(r.R) or frac(r.B) then
						out[#out + 1] = (d.Parent and d.Parent.Name or "?") .. "." .. d.Name .. " " .. fmt("%.2f,%.2f..%.2f,%.2f", r.X, r.Y, r.R, r.B)
					end
				end
			elseif d:IsA("UIStroke") and d.Name == "SignEdge" and d.Parent and d.Parent:IsA("GuiObject") and U8.shown(d.Parent) then
				local px = d.Thickness * U8.scaleOf(d.Parent)
				if frac(px) then
					out[#out + 1] = fmt("%s edge %.2f px", d.Parent.Name, px)
				end
			end
		end
		return out
	end
	-- the shown UIStrokes named SignEdge under `root` that are not mitred
	function U99.roundEdges(root)
		local out = {}
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("UIStroke") and d.Name == "SignEdge" and d.Parent and d.Parent:IsA("GuiObject") and U8.shown(d.Parent) and d.LineJoinMode ~= Enum.LineJoinMode.Miter then
				out[#out + 1] = d.Parent.Name
			end
		end
		return out
	end

	-- the toasts as stone tags: the tile face in a wood edge, the stone lip flush along the bottom, the kind's chip in its
	-- role colour (info sky, good grass, bad red, token gold, each with its lip) holding its pixel icon on whole screen
	-- px, brown words; the reward's sparkle at the icon's pixel size; nothing round, glossy or glowing; every text reads
	S.toasts_signboard_skin = guarded("toasts_signboard_skin", function()
		local Sign = LoadingH.shared("Theme").Sign
		local NC = U7.client("Controllers/NotifyController")
		if not T.check(NC and type(NC.KindChip) == "table", "toast skin: NotifyController and its KindChip load") then
			return
		end
		local ICONS = { info = "bulb", good = "check", bad = "x", token = "token" }
		U8.at(1920, 1080, false, "toast skin", function(tag)
			local cards = U99.toasts()
			local stack = U99.gui("NimbusNotify"):FindFirstChild("ToastStack", true)
			local bad = {}
			for kind, look in pairs(NC.KindChip) do
				local card = cards[kind]
				if not card then
					bad[#bad + 1] = kind .. ": no toast"
				else
					local edge, lip, chip = card:FindFirstChild("SignEdge"), card:FindFirstChild("Lip"), card:FindFirstChild("Icon")
					if not (sameColor(card.BackgroundColor3, Sign.Tile) and card.BackgroundTransparency == 0 and edge and sameColor(edge.Color, Sign.Wood)
						and lip and sameColor(lip.BackgroundColor3, Sign.StoneLip) and lip.BackgroundTransparency == 0) then
						bad[#bad + 1] = kind .. ": the card is not a stone tag (tile, wood edge, stone lip)"
					end
					local cedge, clip = chip and chip:FindFirstChild("SignEdge"), chip and chip:FindFirstChild("Lip")
					if not (chip and sameColor(chip.BackgroundColor3, look.Face) and chip.BackgroundTransparency == 0 and cedge and clip and sameColor(clip.BackgroundColor3, look.Lip)) then
						bad[#bad + 1] = kind .. ": the chip is not its role's block (" .. hex(chip and chip.BackgroundColor3) .. ")"
					end
					local icon = nil
					for _, d in ipairs(chip and chip:GetDescendants() or {}) do
						if d:IsA("Frame") and d:GetAttribute("PixelIcon") == ICONS[kind] then
							icon = d
						end
					end
					if not icon then
						bad[#bad + 1] = kind .. ": no pixel " .. ICONS[kind] .. " on the chip"
					end
					local text = card:FindFirstChild("Text")
					if not (text and sameColor(text.TextColor3, Sign.Text) and text.TextTransparency == 0) then
						bad[#bad + 1] = kind .. ": the words are not brown"
					end
					if kind == "token" and not (chip and chip:FindFirstChild("Sparkle")) then
						bad[#bad + 1] = "token: no sparkle on the reward's chip"
					end
				end
			end
			T.check(#bad == 0, tag .. ": each toast is a stone tag with its role's chip, pixel icon and brown words", table.concat(bad, "; "))
			T.check(#U94.roundOrGloss(stack) == 0, tag .. ": no UICorner or UIGradient on a toast", table.concat(U94.roundOrGloss(stack), ", "))
			T.check(#U99.roundEdges(stack) == 0, tag .. ": every wood edge is mitred (square corners)", table.concat(U99.roundEdges(stack), ", "))
			T.check(#U94.floatingLips(stack) == 0, tag .. ": every lip lies flush along its block's bottom", table.concat(U94.floatingLips(stack), "; "))
			local cells, odd = U99.pixelCells(stack, { U99.cell(stack) })
			T.check(#odd == 0, tag .. ": one pixel size: every toast icon (the sparkle too) on " .. U99.cell(stack) .. " px cells", table.concat(odd, "; ") .. " | " .. table.concat(cells, ", "))
			local grid = U99.offGrid(stack, { Toast = true })
			T.check(#grid == 0, tag .. ": every toast, chip, lip, icon and wood edge on whole screen px", table.concat(grid, "; "))
			local low = U94.contrast("NimbusNotify")
			T.check(#low == 0, tag .. ": every toast text reads on its fill", table.concat(low, "; "))
			U99.clearToasts()
		end)
		LKC.flushErrors("toasts_signboard_skin")
	end)

	-- the toasts on the phones (U99.PHONES, with the game's real RUN / DASH): every shown toast inside the screen and its words
	-- inside it (>= 14 px), none over Roblox's thumbstick or jump button or the game's RUN / DASH
	S.toasts_fit_phone = guarded("toasts_fit_phone", function()
		for _, s in ipairs(U99.PHONES) do
			U99.atPhone(s[1], s[2], "toast phone", function(tag)
				local cards = U99.toasts()
				local n = 0
				for kind, card in pairs(cards) do
					n = n + 1
					local gui = card:FindFirstAncestorWhichIsA("LayerCollector")
					local r = U8.rect(card)
					T.check(r.X >= -0.5 and r.Y >= -0.5 and r.R <= gui.AbsoluteSize.X + 0.5 and r.B <= gui.AbsoluteSize.Y + 0.5, tag .. ": the " .. kind .. " toast lies inside the screen", U8.show(r))
					local hits = U99.overTouch(gui, r, s[2] > s[1])
					T.check(#hits == 0, tag .. ": the " .. kind .. " toast lies over no thumb zone or touch button", table.concat(hits, "; ") .. " | " .. U8.show(r))
					local out, small = U99.texts(card, r)
					T.check(#out == 0 and #small == 0, tag .. ": the " .. kind .. " toast's words inside it, >= 14 px", table.concat(out, "; ") .. " " .. table.concat(small, ", "))
					-- (U9-9 look) at the phone's scale too: the card, its chip, lips, icon and edges on whole screen px
					local grid = U99.offGrid(card, {})
					if not (math.abs(r.X - math.floor(r.X + 0.5)) <= 0.02 and math.abs(r.Y - math.floor(r.Y + 0.5)) <= 0.02) then
						grid[#grid + 1] = "Toast " .. U8.show(r)
					end
					T.check(#grid == 0, tag .. ": the " .. kind .. " toast on whole screen px", table.concat(grid, "; "))
				end
				T.check(n >= 1, tag .. ": at least the newest toast shows", tostring(n))
				U99.clearToasts()
			end)
		end
		LKC.flushErrors("toasts_fit_phone")
	end)

	-- the match result card on the Signboard skin: the wood frame and stone body, the fixed awning 20 px wider than the card,
	-- the banner a block (VICTORY! gold, DEFEAT stone) with a plain Section headline in brown and the red close block on its
	-- right end, each stat a stone block in its wood edge, the player's own line on the selected face, nothing round or
	-- glossy, every text readable, one pixel size; on every screen size the card and its awning inside the screen and clear
	-- of the HUD's currency strip, on the phones (U99.PHONES, with the game's real RUN / DASH) clear of the thumbstick, the
	-- jump button and RUN, the game's DASH wholly under the card or wholly clear of it (the U9-4 rule, its taps pass through
	-- the card); a landscape phone takes the compact rows, or the mini card (no team, no difficulty line) where those do not
	-- fit
	S.results_card_kitb = guarded("results_card_kitb", function()
		local Sign = LoadingH.shared("Theme").Sign
		local sizes = { { 1920, 1080, false }, { 1280, 720, false } }
		for _, s in ipairs(U99.PHONES) do
			sizes[#sizes + 1] = { s[1], s[2], true }
		end
		for _, s in ipairs(sizes) do
			local at = s[3] and function(w, h, _, label, fn)
				U99.atPhone(w, h, label, fn)
			end or U8.at
			at(s[1], s[2], s[3], "result card", function(tag)
				for _, won in ipairs({ true, false }) do
					local what = tag .. (won and " (won)" or " (lost, four players)")
					local card = U99.results(won)
					if T.check(card ~= nil and card:GetAttribute("Skin") == "Signboard", what .. ": the card wears the Signboard skin") then
						local body, roof = card:FindFirstChild("Body"), card:FindFirstChild("Roof")
						local stone = body and body:FindFirstChild("Stone")
						T.check(body and sameColor(body.BackgroundColor3, Sign.Wood) and stone and sameColor(stone.BackgroundColor3, Sign.Stone) and stone:FindFirstChild("Lip") ~= nil,
							what .. ": the wood frame round the stone body and its lip")
						T.check(roof ~= nil and U8.shown(roof) and roof.Size.X.Offset == card.Size.X.Offset + 20, what .. ": the awning is a fixed piece 20 px wider than the card",
							roof and tostring(roof.Size) or "no roof")
						local banner = card:FindFirstChild("Banner", true)
						local headline = banner and banner:FindFirstChild("Headline")
						T.check(banner and sameColor(banner.BackgroundColor3, won and Sign.Gold or Sign.Tile) and banner:FindFirstChild("SignEdge") ~= nil
							and headline and headline:GetAttribute("TitleLook") == "Section" and sameColor(headline.TextColor3, Sign.Text),
							what .. ": the banner block (" .. (won and "gold" or "stone") .. ") with a plain Section headline in brown", banner and hex(banner.BackgroundColor3) or "no banner")
						local close = card:FindFirstChild("Close", true)
						T.check(close and close:GetAttribute("SignLook") == "Danger" and U8.shown(close), what .. ": the close is the red block")
						local rows, plain = 0, true
						for _, name in ipairs({ "RowTime", "RowTokens", "RowWin bonus" }) do
							local row = card:FindFirstChild(name, true)
							if row then
								rows = rows + 1
								plain = plain and row:FindFirstChild("SignEdge") ~= nil and row:FindFirstChild("Lip") ~= nil and sameColor(row.BackgroundColor3, Sign.Tile)
							end
						end
						-- the compact and mini cards leave an empty win bonus out (the lost match has none)
						local tier = card:GetAttribute("Rows")
						-- (U9-9 look) the mini card shows a win bonus in the Tokens row ("11  +10", MergeBonus)
						-- (P2 fix A) Micro: where even the mini card with its reason line is taller than its room (a lost match on a
						-- 360 px tall landscape phone, under the strip once the F0 awning stands 20 px over the card), the Tokens row only
						local small = tier == "Mini" or tier == "Micro"
						local want = tier == "Micro" and 1 or ((tier == "Mini" or (tier ~= "Full" and not won)) and 2 or 3)
						T.check(rows == want and plain, what .. ": the " .. want .. " stats are stone blocks in their wood edge", rows .. " rows (" .. tostring(tier) .. ")")
						if tier == "Compact" and not won then
							local m1, m3 = card:FindFirstChild("Member1", true), card:FindFirstChild("Member3", true)
							T.check(m1 and m3 and math.abs(U8.rect(m1).Y - U8.rect(m3).Y) > 1 and card:FindFirstChild("Member2", true)
								and math.abs(U8.rect(m1).Y - U8.rect(card:FindFirstChild("Member2", true)).Y) < 0.5,
								what .. ": the compact card lays four players in two columns")
						end
						local mine = nil
						for _, d in ipairs(card:GetDescendants()) do
							if d:GetAttribute("Mine") == true then
								mine = d
							end
						end
						if small then
							-- (U9-9 review) the mini card: the result, the reason, the stats and the countdown only
							T.check(mine == nil and card:FindFirstChild("Member1", true) == nil and card:FindFirstChild("Difficulty", true) == nil,
								what .. ": the mini card shows no team and no difficulty line")
						else
							T.check(mine ~= nil and sameColor(mine.BackgroundColor3, Sign.Selected), what .. ": the player's own line is on the selected face")
						end
						T.check(#U94.roundOrGloss(card) == 0, what .. ": nothing round or glossy", table.concat(U94.roundOrGloss(card), ", "))
						T.check(#U99.roundEdges(card) == 0, what .. ": every wood edge is mitred", table.concat(U99.roundEdges(card), ", "))
						local cells, odd = U99.pixelCells(card, { U99.cell(card) })
						T.check(#odd == 0, what .. ": one pixel size: the stars, coins and ticks on " .. U99.cell(card) .. " px cells", table.concat(odd, "; ") .. " | " .. table.concat(cells, ", "))
						-- the icons sit apart line to line (a member line taller than its icons) and the difficulty's colour bar
						-- under its letters, not through them
						local cramped = {}
						for _, d in ipairs(card:GetDescendants()) do
							if d.Name:match("^Member%d+$") and U8.shown(d) then
								for _, f in ipairs(d:GetDescendants()) do
									if f:IsA("Frame") and f:GetAttribute("PixelIcon") and U8.shown(f) and f.AbsoluteSize.Y > d.AbsoluteSize.Y - 2 then
										cramped[#cramped + 1] = fmt("%s %s %.1f px in a %.1f px line", d.Name, tostring(f:GetAttribute("PixelIcon")), f.AbsoluteSize.Y, d.AbsoluteSize.Y)
									end
								end
							end
						end
						T.check(#cramped == 0, what .. ": each member line is taller than its icons (they never touch line to line)", table.concat(cramped, "; "))
						-- (U9-9 look) the difficulty a role chip (its colour on the face, a darker lip, a wood edge, the word and its
						-- stars inside), centred under the banner with a gap; no loose colour bar
						local chip, banner2 = card:FindFirstChild("DiffChip", true), card:FindFirstChild("Banner", true)
						if not small then
							local inner = chip and chip.Parent
							local ok = chip and U8.shown(chip) and chip:FindFirstChild("SignEdge") ~= nil and chip:FindFirstChild("Lip") ~= nil
								and chip:FindFirstChild("Difficulty") ~= nil and card:FindFirstChild("DiffBar", true) == nil
							local cr = chip and U8.rect(chip)
							local ir = inner and U8.rect(inner)
							local br = banner2 and U8.rect(banner2)
							T.check(ok and math.abs((cr.X + cr.R) / 2 - (ir.X + ir.R) / 2) <= 1 and cr.Y >= br.B + 3,
								what .. ": the difficulty is a role chip centred under the banner (no colour bar)",
								cr and br and (U8.show(cr) .. " under " .. U8.show(br)) or "missing")
						end
						-- (U9-9 look) one grammar with the run's other end cards: the outcome on the stone body's lip (green won, red
						-- lost) and two dark nails at its top corners
						local stoneLip = stone and stone:FindFirstChild("Lip")
						T.check(stoneLip and sameColor(stoneLip.BackgroundColor3, won and Sign.GrassLip or Sign.RedLip) and card:FindFirstChild("NailL", true) and card:FindFirstChild("NailR", true),
							what .. ": the outcome on the body's lip (" .. (won and "green" or "red") .. ") and two nails", stoneLip and hex(stoneLip.BackgroundColor3) or "no lip")
						-- (U9-9 look) a stat block is taller than its coin: the icon inside the face with a pixel clear above it and
						-- above the lip; and the close block no taller than the banner's face
						local tight = {}
						for _, name in ipairs({ "RowTime", "RowTokens", "RowWin bonus" }) do
							local row = card:FindFirstChild(name, true)
							local lip = row and row:FindFirstChild("Lip")
							for _, f in ipairs(row and row:GetDescendants() or {}) do
								if f:IsA("Frame") and f:GetAttribute("PixelIcon") and U8.shown(f) and lip then
									local fr, rr = U8.rect(f), U8.rect(row)
									if fr.Y < rr.Y + 1 - 0.01 or fr.B > U8.rect(lip).Y - 1 + 0.01 then
										tight[#tight + 1] = fmt("%s %s %s in %s", name, tostring(f:GetAttribute("PixelIcon")), U8.show(fr), U8.show(rr))
									end
								end
							end
						end
						T.check(#tight == 0, what .. ": each stat block holds its coin inside its face", table.concat(tight, "; "))
						local closeB = card:FindFirstChild("Close", true)
						if closeB and banner2 then
							local bl = banner2:FindFirstChild("Lip")
							local cb, bb = U8.rect(closeB), U8.rect(banner2)
							T.check(cb.Y >= bb.Y - 0.5 and cb.B <= (bl and U8.rect(bl).Y or bb.B) + 0.5, what .. ": the close block inside the banner's face", U8.show(cb) .. " in " .. U8.show(bb))
							-- (U9-9 look 2) the X the pitch's pixel icon (ic("x")) on the card's cell, nothing in the block turned (the
							-- four rotated bars drew a smooth anti-aliased X)
							local mark = closeB:FindFirstChild("CloseMark")
							local icon, turned = nil, {}
							for _, d in ipairs(closeB:GetDescendants()) do
								if d:IsA("GuiObject") and d:GetAttribute("PixelIcon") == "x" then
									icon = d
								end
								if d:IsA("GuiObject") and d.Rotation ~= 0 then
									turned[#turned + 1] = d.Name
								end
							end
							T.check(mark and icon and icon:IsDescendantOf(mark) and #turned == 0, what .. ": the close mark is the pixel x, nothing turned", table.concat(turned, ", "))
							if s[3] then
								-- (P2 fix A look review r1, major 6: the close was 24 x 24 at 390x844) a thumb's 44 screen px each way: the
								-- block itself or its clear hit pad (HitFor = "Close") over it
								local pad = closeB:FindFirstChild("CloseHit")
								local pr = pad and U8.shown(pad) and pad:GetAttribute("HitFor") == "Close" and U8.rect(pad)
								local area = (cb.R - cb.X >= 43.5 and cb.B - cb.Y >= 43.5) and cb
									or (pr and pr.R - pr.X >= 43.5 and pr.B - pr.Y >= 43.5 and pr.X <= cb.X + 0.5 and pr.R >= cb.R - 0.5 and pr.Y <= cb.Y + 0.5 and pr.B >= cb.B - 0.5 and pr)
								T.check(area, what .. ": the close is a thumb's 44 px (the block or its hit pad)", U8.show(cb) .. (pr and (" pad " .. U8.show(pr)) or " no pad"))
							end
						end
						-- (U9-9 look 2) the coins in the Shop's deep gold (one currency, one colour), not the brown ink
						local Theme = LoadingH.shared("Theme")
						local coinName = Theme.Currency.Tokens.Icon
						local brown, coins = {}, 0
						for _, d in ipairs(card:GetDescendants()) do
							if d:IsA("Frame") and d:GetAttribute("PixelIcon") == coinName and U8.shown(d) then
								coins = coins + 1
								for _, f in ipairs(d:GetDescendants()) do
									if f:IsA("Frame") and f.BackgroundTransparency < 0.5 and not sameColor(f.BackgroundColor3, Sign.GoldLip) then
										brown[#brown + 1] = hex(f.BackgroundColor3)
										break
									end
								end
							end
						end
						T.check(coins >= 1 and #brown == 0, what .. ": the coins in the deep gold", coins .. " coins " .. table.concat(brown, ", "))
						-- (U9-9 look 2) the countdown's line above the body's lip (the mini card's stood on it, its "y" in the lip)
						local footer, sLip = card:FindFirstChild("Footer", true), stone and stone:FindFirstChild("Lip")
						if footer and sLip and U8.shown(footer) then
							T.check(U8.rect(footer).B <= U8.rect(sLip).Y + 0.01, what .. ": the countdown's line above the body's lip", U8.show(U8.rect(footer)) .. " / lip " .. fmt("%.1f", U8.rect(sLip).Y))
						end
						-- (U9-9 look 2) the mini card's win bonus a gold chip (the Selected face and its lip) in the Tokens row's face,
						-- left of the total with a clear gap; the total its own number
						if small and won then
							local chip = card:FindFirstChild("BonusChip", true)
							local row = card:FindFirstChild("RowTokens", true)
							local value = row and row:FindFirstChild("Value")
							local chipLip, rowLip = chip and chip:FindFirstChild("Lip"), row and row:FindFirstChild("Lip")
							if T.check(chip and U8.shown(chip) and sameColor(chip.BackgroundColor3, Sign.Gold) and chipLip and sameColor(chipLip.BackgroundColor3, Sign.GoldLip)
								and tostring(chip:FindFirstChild("Bonus") and chip.Bonus.Text):match("^%+%d+$") and value and tostring(value.Text):match("^%d+$"),
								what .. ": the win bonus a gold chip ('+N'), the total its own number", value and value.Text or "") then
								local c, rr, coin = U8.rect(chip), U8.rect(row), value:FindFirstChild("TrailIcon")
								-- (the digits end the value's 5 px icon gap before its coin, PixelIcon.Lead)
								local digits = coin and (U8.rect(coin).X - 5 * U8.scaleOf(value) - value.TextBounds.X) or U8.rect(value).R
								T.check(c.Y >= rr.Y + 1 - 0.01 and c.B <= U8.rect(rowLip).Y - 1 + 0.01 and c.R <= digits - 3 + 0.01,
									what .. ": the chip inside the row's face, 3 px or more left of the digits", U8.show(c) .. fmt(" | row %s, digits at %.1f", U8.show(rr), digits))
							end
						end
						-- (U9-9 look) the blocks on whole screen px: the banner, the chip, the stat rows, the nails, and every
						-- wood edge a whole px thick
						local off = {}
						for _, d in ipairs(card:GetDescendants()) do
							if d:IsA("GuiObject") and U8.shown(d) and (d.Name == "Banner" or d.Name == "DiffChip" or d.Name:match("^Row") or d.Name:match("^Nail")) then
								local r = U8.rect(d)
								if math.abs(r.X - math.floor(r.X + 0.5)) > 0.01 or math.abs(r.Y - math.floor(r.Y + 0.5)) > 0.01 then
									off[#off + 1] = d.Name .. " " .. U8.show(r)
								end
							elseif d:IsA("UIStroke") and d.Name == "SignEdge" and d.Parent and U8.shown(d.Parent) then
								local px = d.Thickness * U8.scaleOf(d.Parent)
								if math.abs(px - math.floor(px + 0.5)) > 0.01 then
									off[#off + 1] = fmt("%s edge %.2f px", d.Parent.Name, px)
								end
							end
						end
						T.check(#off == 0, what .. ": its blocks and wood edges on whole screen px", table.concat(off, "; "))
						-- (U9-9 look 2) all four edges of every block with a face (the stone in its wood frame drew 4.8 px wide, the
						-- awning 14.4 px high), lip and icon
						local grid = U99.offGrid(card, {})
						T.check(#grid == 0, what .. ": every block, lip and icon on whole screen px (all four edges)", table.concat(grid, "; "))
						local low = U94.contrast("NimbusNotify")
						T.check(#low == 0, what .. ": every text reads on its fill", table.concat(low, "; "))
						local gui = card:FindFirstAncestorWhichIsA("LayerCollector")
						local r = U8.rect(card)
						if roof and U8.shown(roof) then
							local rr = U8.rect(roof)
							r = { X = math.min(r.X, rr.X), Y = math.min(r.Y, rr.Y), R = math.max(r.R, rr.R), B = math.max(r.B, rr.B) }
						end
						T.check(r.X >= -0.5 and r.Y >= -0.5 and r.R <= gui.AbsoluteSize.X + 0.5 and r.B <= gui.AbsoluteSize.Y + 0.5, what .. ": the card and its awning lie inside the screen", U8.show(r))
						local out, small = U99.texts(card, U8.rect(card))
						T.check(#out == 0 and #small == 0, what .. ": every text inside the card, >= 14 px", table.concat(out, "; ") .. " " .. table.concat(small, ", "))
						-- (U9-9 review) the card and its awning clear of the HUD's currency strip (a match shows the token strip)
						local strip = U99.overTopRight(gui, r)
						T.check(#strip == 0, what .. ": the card and its awning clear of the HUD's currency strip", table.concat(strip, "; ") .. " | " .. U8.show(r))
						if s[3] then
							local hits = U99.overTouch(gui, r, s[2] > s[1], { DashButton = true })
							T.check(#hits == 0, what .. ": the card lies over no thumb zone, jump button or RUN, and DASH wholly under it or wholly clear",
								table.concat(hits, "; ") .. " | " .. U8.show(U8.rect(card)))
						end
						if s[3] and s[1] > s[2] then
							T.check(tier == "Compact" or small, what .. ": a landscape phone takes the compact rows or the mini / micro card", tostring(tier))
							-- (P2 fix A) the lost mini card (its reason line 25 design px) cannot stand between the strip and the jump
							-- button on a 360 px tall phone: the micro card keeps the result, the reason, the tokens and the countdown
							if s[2] <= 360 and not won then
								local reasonL = card:FindFirstChild("Reason", true)
								T.check(tier == "Micro" and reasonL and U8.shown(reasonL) and card:FindFirstChild("RowTime", true) == nil and card:FindFirstChild("RowTokens", true) ~= nil,
									what .. ": a 360 px tall phone's lost card is the micro card (the reason and the tokens kept, no Time row)", tostring(tier))
							end
						elseif s[1] == 1920 then
							T.check(tier == "Full", what .. ": the full rows on a PC", tostring(tier))
						end
						-- (U9-9 review, look) the HUD's vitals card steps aside while the card lies over a part of it (the mini
						-- card's corner over its right end on a 360 px tall phone), as for the Trove panel
						local hud = U7.client("Controllers/HudController")
						local layout = hud and hud.GetLayout and hud.GetLayout()
						local slot = layout and layout.VitalsSlot
						if slot then
							local c = U8.rect(card)
							local over = math.min(c.R, slot.X + slot.W) - math.max(c.X, slot.X) > 4 and math.min(c.B, slot.Y + slot.H) - math.max(c.Y, slot.Y) > 4
							T.check(not over or layout.Vitals == nil, what .. ": the vitals card steps aside while the card lies over it",
								fmt("card %s, vitals %d,%d %dx%d shown %s", U8.show(c), slot.X, slot.Y, slot.W, slot.H, tostring(layout.Vitals ~= nil)))
						end
					end
					U99.closeResults()
					local hud = U7.client("Controllers/HudController")
					local after = hud and hud.GetLayout and hud.GetLayout()
					T.check(not (after and after.VitalsSlot) or after.Vitals ~= nil, tag .. ": the vitals card is back once the card closes")
				end
			end)
		end
		LKC.flushErrors("results_card_kitb")
	end)

	-- (Pitch 2 battle lane) a one-line text's drawn width (screen px) at the face's real width, its padding included
	local P2 = {}
	function P2.textW(o)
		local Theme = LoadingH.shared("Theme")
		local text = tostring(o.Text):gsub("<[^>]->", "")
		local role = o:GetAttribute("FontRole")
		if role and Theme.CapsRoles[role] then
			text = Theme.Caps(text)
		end
		local w = SmokeCommon.RealWidth(text, o.TextSize, Theme.FontOf(o), true) or Theme.MeasureLabel(o).X
		local pad = o:FindFirstChildOfClass("UIPadding")
		return (w + (pad and (pad.PaddingLeft.Offset + pad.PaddingRight.Offset) or 0)) * U8.scaleOf(o)
	end
	-- r inside box (1 px slack)
	function P2.inside(r, box)
		return r.X >= box.X - 1 and r.R <= box.R + 1 and r.Y >= box.Y - 1 and r.B <= box.B + 1
	end
	-- every shown one-line text under root that its box cuts: "name 'text' w in W"
	function P2.tight(root)
		local out = {}
		for _, d in ipairs(root:GetDescendants()) do
			if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and U8.shown(d) and not d.TextWrapped and not d.TextScaled and d.AbsoluteSize.X > 0 then
				local w = P2.textW(d)
				if w + 1 > d.AbsoluteSize.X + 0.01 then
					out[#out + 1] = fmt("%s %q %.0f in %.0f", d.Name, d.Text, w, d.AbsoluteSize.X)
				end
			end
		end
		return out
	end

	-- (Pitch 2 item 06, option A "One strip", .superpowers/slop-audit/round3/build/PITCH2/A_battle_hud/06_boss_bar_optA.png)
	-- a boss raid's top card at the four grid sizes is ONE stone card: row 1 the RAID tag, the boss's name, the timer and
	-- (a fighter) Leave inside the card; under it the HP as kit blocks (20; 14 on a phone) with the number "27.6K / 50K"
	-- in the SAME sunk track behind a 2 px divider (no box of its own), and the state pills inside the card on every size
	-- (the phone too, none dropped; a narrow card wraps them into rows). The boss head portrait reads its image id from
	-- Config.BossHeads (a TextureIds key): with no id (today) no portrait and the track starts at the card's inner left;
	-- with one, a 74 px pixelated portrait two rows tall left of the track. Worst case: a 20-character name and 1.01B
	-- fit, every one-line text whole
	S.battle_topcard_one_card = guarded("battle_topcard_one_card", function()
		local Theme = LoadingH.shared("Theme")
		local Config = LoadingH.shared("Config")
		local Sign = Theme.Sign
		if not T.check(_G.P5BattleH ~= nil and Config.BossHeads ~= nil, "top card: (setup) the battle driver is loaded and Config.BossHeads exists") then
			return
		end
		local BC = U7.client("Controllers/BattleController")
		local restore = U8.measureReal()
		local function view(tag, worst)
			local gui = U8.pg():FindFirstChild("NimbusBattle")
			local Hd, B = BC._Hud, BC._St.battle
			local top = gui and gui:FindFirstChild("TopCard", true)
			local card = top and top:FindFirstChild("ModeCard")
			if not T.check(B and B.boss and card and U8.shown(card), tag .. ": the raid's top card shows") then
				return
			end
			if worst then
				B.boss.name = "Twentycharacterboss1"
				B.boss.maxHp, B.boss.hp = 1.01e9, 1.009e9
				Hd.Rebuild()
				LKC.advance(0.3)
			end
			local k = U8.scaleOf(card)
			local cr = U8.rect(card)
			T.check(sameColor(card.BackgroundColor3, Sign.Stone) and card:FindFirstChild("SignEdge") ~= nil and card:FindFirstChild("Lip") ~= nil,
				tag .. ": one stone card in its wood edge with its lip", hex(card.BackgroundColor3))
			-- one card: every shown part of the top card lies inside it (the card's own finish, F0's bevel lines on its edge
			-- and its hard shadow, sits on and past the edge by design)
			local function finish(d)
				local cur = d
				while cur and cur ~= top do
					if cur.Name:match("^Finish") then
						return true
					end
					cur = cur.Parent
				end
				return false
			end
			local out = {}
			for _, d in ipairs(top:GetDescendants()) do
				if d:IsA("GuiObject") and U8.shown(d) and d.AbsoluteSize.X > 0 and not finish(d) and (d.BackgroundTransparency < 1 or ((d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "")) then
					if not P2.inside(U8.rect(d), cr) then
						out[#out + 1] = d.Name .. " " .. U8.show(U8.rect(d))
					end
				end
			end
			T.check(#out == 0, tag .. ": every part of the top card inside the one card", table.concat(out, "; ", 1, math.min(#out, 6)) .. " | card " .. U8.show(cr))
			-- row 1: the RAID tag, the boss's name, the timer and Leave, all inside the card's top row
			local rowB = cr.Y + 60 * k
			local tagL = card:FindFirstChild("ModeTag", true)
			local name = top:FindFirstChild("BossName", true)
			local leave = gui.Root:FindFirstChild("LeaveButton")
			-- (a card under 400 design px, a tall phone's right column, which the pitch did not draw: the tag steps aside so
			-- the boss's name keeps its room)
			local narrow = card.AbsoluteSize.X / k < 400
			-- (look review round 1, minor: the 390x844 card dropped RAID altogether) a narrow card says RAID too: the first pill
			local raidPill = top:FindFirstChild("RaidPill", true)
			T.check(tagL and ((U8.shown(tagL) and tagL.Text == "RAID" and U8.rect(tagL).B <= rowB)
				or (narrow and not U8.shown(tagL) and raidPill and U8.shown(raidPill) and raidPill.Text == "RAID" and P2.inside(U8.rect(raidPill), cr))),
				tag .. ": the RAID tag in row 1 (a narrow card: the RAID pill)", tagL and tagL.Text or "missing")
			T.check(name and U8.shown(name) and (name.Text == B.boss.name or (name.Text:sub(-3) == "..." and B.boss.name:find(name.Text:sub(1, -4), 1, true) == 1)) and U8.rect(name).B <= rowB,
				tag .. ": the boss's name in row 1", name and name.Text or "missing")
			T.check(Hd.timer and U8.shown(Hd.timer) and P2.inside(U8.rect(Hd.timer), cr) and U8.rect(Hd.timer).B <= rowB, tag .. ": the timer in row 1, inside the card")
			T.check(leave and U8.shown(leave) and P2.inside(U8.rect(leave), cr) and U8.rect(leave).B <= rowB,
				tag .. ": Leave inside the card's row 1 (was a plank of its own at the bottom right)", leave and U8.show(U8.rect(leave)) or "missing")
			if Hd.m.Touch and leave then
				-- a thumb's 44 px: the plank itself or its clear hit pad (HitFor) over it
				local lr = U8.rect(leave)
				local hit = leave:FindFirstChild("LeaveHit")
				local hr = hit and U8.shown(hit) and hit:GetAttribute("HitFor") == "LeaveButton" and U8.rect(hit)
				T.check((lr.R - lr.X >= 43.5 and lr.B - lr.Y >= 43.5) or (hr and hr.R - hr.X >= 43.5 and hr.B - hr.Y >= 43.5 and hr.X <= lr.X + 0.5 and hr.R >= lr.R - 0.5 and hr.Y <= lr.Y + 0.5 and hr.B >= lr.B - 0.5),
					tag .. ": Leave is a 44 px thumb target on a touch screen (its hit pad)", hr and U8.show(hr) or U8.show(lr))
			end
			-- the HP: kit blocks and the number in ONE sunk track behind a 2 px divider
			local hp = top:FindFirstChild("BossBar") and top.BossBar:FindFirstChild("Hp")
			local blocks = hp and hp:FindFirstChild("Blocks")
			local num = hp and hp:FindFirstChild("Text")
			local div = hp and hp:FindFirstChild("Divider")
			if T.check(hp and blocks and num and div and U8.shown(num), tag .. ": the HP track holds the blocks, the divider and the number") then
				local hr, br, nr, dr = U8.rect(hp), U8.rect(blocks), U8.rect(num), U8.rect(div)
				T.check(P2.inside(br, hr) and P2.inside(nr, hr) and br.R <= dr.X + 0.5 and dr.R <= nr.X + 0.5 and math.abs(dr.R - dr.X - 2 * k) < 0.6,
					tag .. ": the number in the track behind the 2 px divider, right of the blocks", fmt("blocks %s | div %s | num %s in %s", U8.show(br), U8.show(dr), U8.show(nr), U8.show(hr)))
				T.check(num.Text:match("^%d[%d%.]*[KMB]? / %d[%d%.]*[KMB]?$") ~= nil and (not worst or num.Text:match(" / 1%.01B$") ~= nil), tag .. ": the number reads 'HP / max' (short numbers)", num.Text)
				-- 20 blocks (14 on a phone, the pitch's); a narrower track (a tall phone's right column, not drawn in the pitch)
				-- fewer, never thin slivers: each block at least 12 design px wide
				local n, thin = 0, 0
				for _, c in ipairs(blocks:GetChildren()) do
					if c.Name:match("^Block%d+$") then
						n = n + 1
						thin = thin + ((c.AbsoluteSize.X / k < 11.5) and 1 or 0)
					end
				end
				local want = Hd.m.Compact and 14 or 20
				T.check((n == want or (n < want and n >= 6 and card.AbsoluteSize.X / k < 400)) and thin == 0,
					tag .. ": the HP is " .. want .. " chunky blocks (a narrow card fewer, each >= 12 px)", fmt("%d blocks, %d thin", n, thin))
				-- no image id today. (keys lane, look review fixA r1: the PC strip with no portrait "reads as a generic bar"; the
				-- lane's brief: keep the reserved slot / its fallback) a PC keeps the head's 74 px slot, the sunk well with the
				-- gold pixel crown and no image, the track right of it; a phone keeps the spec's no-portrait fallback, the track
				-- at the card's inner left (its narrower strip needs the room)
				local portrait = top:FindFirstChild("Portrait", true)
				if Hd.m.Compact then
					T.check((portrait == nil or not U8.shown(portrait)) and hr.X - cr.X <= 14 * k, tag .. ": no boss head id on a phone: no portrait, the card still whole (the track at its left)",
						fmt("track from %.0f, card %.0f", hr.X, cr.X))
				else
					local crown = portrait and portrait:FindFirstChild("Crown")
					local img = portrait and portrait:FindFirstChild("Head")
					local pr = portrait and U8.rect(portrait)
					T.check(portrait and U8.shown(portrait) and crown and U8.shown(crown) and crown:GetAttribute("PixelIcon") == "crown" and not (img and U8.shown(img))
						and math.abs(portrait.AbsoluteSize.X / k - 74) < 0.6 and P2.inside(pr, cr) and hr.X >= pr.R,
						tag .. ": no boss head id on a PC: the head's 74 px slot keeps its place with the gold crown, the track right of it",
						pr and fmt("slot %s, track from %.0f", U8.show(pr), hr.X) or "no slot")
				end
			end
			-- the pills: the element and the players on every size, each inside the card, none on another
			local pills = top:FindFirstChild("Pills")
			local shownPills = {}
			for _, p in ipairs(pills and pills:GetChildren() or {}) do
				if p:IsA("GuiObject") and U8.shown(p) then
					shownPills[#shownPills + 1] = p
				end
			end
			local names = {}
			for _, p in ipairs(shownPills) do
				names[p.Name] = true
			end
			T.check(names.Element and names.Players, tag .. ": the element and the players pills show (the phone too)", (function()
				local t = {}
				for nm in pairs(names) do
					t[#t + 1] = nm
				end
				return table.concat(t, ", ")
			end)())
			local clash = {}
			for i, p in ipairs(shownPills) do
				if not P2.inside(U8.rect(p), cr) then
					clash[#clash + 1] = p.Name .. " outside"
				end
				for j = i + 1, #shownPills do
					if U8.overlap(U8.rect(p), U8.rect(shownPills[j])) then
						clash[#clash + 1] = p.Name .. " on " .. shownPills[j].Name
					end
				end
			end
			T.check(#clash == 0, tag .. ": the pills inside the card, apart (wrapped where the card is narrow)", table.concat(clash, "; "))
			local tight = P2.tight(top)
			T.check(#tight == 0, tag .. ": every one-line text of the card fits its box", table.concat(tight, "; "))
			if Hd.m.Compact and not Hd.m.Landscape then
				-- (P2 fix A, look: at 390 x 844 the card was a 196 px tower under the enemy list, the name cut to 'Storm...', the
				-- track 50 px) a portrait phone's boss card is the pitch's strip across the top (06_boss_bar_optA; the pitch's
				-- portrait scene draws it 470 wide at y 62 with the fighter card and the strips under it): the screen's width
				-- less its edges, the name whole, a track of 200 px or more, the fighter card and the HUD's strips under it
				local sw = gui.AbsoluteSize.X
				local edge = 12 * k
				local name2 = top:FindFirstChild("BossName", true)
				local hp2 = top:FindFirstChild("BossBar") and top.BossBar:FindFirstChild("Hp")
				local fc = gui.Root:FindFirstChild("Team")
				local fr = fc and U8.shown(fc) and U8.rect(fc)
				local over = U99.overTopRight(gui, cr)
				T.check(cr.R - cr.X >= sw - 2 * edge - 2 and cr.Y <= edge + 1 and name2 and name2.Text == B.boss.name and hp2 and U8.rect(hp2).R - U8.rect(hp2).X >= 200
					and fr and fr.Y >= cr.B and #over == 0,
					tag .. ": a portrait phone's boss card spans the top, the name whole, the fighter card and the strips under it",
					fmt("card %s of %d | name '%s' | track %.0f | team %s | strips %s", U8.show(cr), sw, name2 and name2.Text or "-", hp2 and (U8.rect(hp2).R - U8.rect(hp2).X) or 0,
						fr and U8.show(fr) or "-", table.concat(over, "; ")))
			end
		end
		for _, s in ipairs(U8.SIZES) do
			for _, worst in ipairs({ false, true }) do
				U8.at(s[1], s[2], s[3], "top card raid" .. (worst and " (20-char name, 1.01B)" or ""), function(tag)
					U96.open("battle:raid")
					view(tag, worst)
					U96.close()
				end)
			end
		end
		-- with an uploaded head (an id in TextureIds): the 74 px pixelated portrait, two rows tall, left of the track
		U8.at(1920, 1080, false, "top card portrait", function(tag)
			local Hd = BC._Hud
			local key = Config.BossHeads.storm_titan
			Hd.Textures = { [tostring(key)] = 1234567 }
			U96.open("battle:raid")
			local gui = U8.pg():FindFirstChild("NimbusBattle")
			local top = gui and gui:FindFirstChild("TopCard", true)
			local portrait = top and top:FindFirstChild("Portrait", true)
			local img = portrait and portrait:FindFirstChildWhichIsA("ImageLabel", true)
			local hp = top and top:FindFirstChild("BossBar") and top.BossBar:FindFirstChild("Hp")
			T.check(type(key) == "string" and portrait and U8.shown(portrait) and img and img.Image == "rbxassetid://1234567" and img.ResampleMode == Enum.ResamplerMode.Pixelated
				and math.abs(portrait.AbsoluteSize.X / U8.scaleOf(portrait) - 74) < 0.6 and hp and U8.rect(hp).X >= U8.rect(portrait).R,
				tag .. ": the boss head is a 74 px pixelated portrait left of the track", img and img.Image or "no portrait")
			Hd.Textures = nil
			U96.close()
		end)
		-- (P2 fix A, look) the portrait phone with the head: the strip keeps the name whole and a track of 200 px or more
		-- beside the 74 px head (the old right-column card cut it to a 50 px track)
		U8.at(390, 844, true, "top card portrait", function(tag)
			local Hd = BC._Hud
			Hd.Textures = { [tostring(Config.BossHeads.storm_titan)] = 1234567 }
			U96.open("battle:raid")
			local B = BC._St.battle
			local gui = U8.pg():FindFirstChild("NimbusBattle")
			local top = gui and gui:FindFirstChild("TopCard", true)
			local portrait = top and top:FindFirstChild("Portrait", true)
			local name = top and top:FindFirstChild("BossName", true)
			local hp = top and top:FindFirstChild("BossBar") and top.BossBar:FindFirstChild("Hp")
			T.check(portrait and U8.shown(portrait) and name and B and B.boss and name.Text == B.boss.name and hp and U8.rect(hp).R - U8.rect(hp).X >= 200 and P2.inside(U8.rect(hp), U8.rect(top)),
				tag .. ": with the head: the name whole, a track of 200 px or more", fmt("name '%s' | track %.0f", name and name.Text or "-", hp and (U8.rect(hp).R - U8.rect(hp).X) or 0))
			Hd.Textures = nil
			U96.close()
		end)
		restore()
		LKC.flushErrors("battle_topcard_one_card")
	end)

	-- (Pitch 2 item 02, option B "Count-up list", the owner's pick, .superpowers/slop-audit/round3/build/PITCH2/A_battle_hud/
	-- 02_result_card_optB.png) every battle end is ONE template: a head band in the result's colour (VICTORY green, THE
	-- BOSS WON red, RUN OVER / a dungeon violet) with its pixel icon and word; the mode - reason line (Body.Reason); stat rows,
	-- each a label, its value right-aligned and a green tick block; equal reward chips (the number big, its icon 18 px, the
	-- word under it on a wide screen); OK the card's whole width (Body.OkButton), its lip in 5 parts = the auto-close
	-- timer. At the four grid sizes, a raid won / lost, a ring run, a dungeon knock-out and the worst case (a 20-character
	-- boss name, 1.01B tokens and XP) all lay out with nothing out of the card, every one-line text whole, off the centre
	S.result_card_template_b = guarded("result_card_template_b", function()
		local Theme = LoadingH.shared("Theme")
		local Sign = Theme.Sign
		if not T.check(_G.P5BattleH ~= nil, "result card B: (setup) the battle driver is loaded") then
			return
		end
		local BC = U7.client("Controllers/BattleController")
		local restore = U8.measureReal()
		local VARIANTS = {
			{ "raid won", "battle:raid", { Mode = "Raid", Outcome = "Win", Won = true, Reason = "BossDown",
				Rewards = { Tokens = 640, Xp = 180, LevelUps = 3, Tier = "Gold", Share = 0.41 } }, "BOSS DEFEATED!", Sign.Grass },
			{ "raid lost", "battle:raid", { Mode = "Raid", Outcome = "Loss", Won = false, Reason = "Timeout",
				Rewards = { Tokens = 420, Xp = 180, LevelUps = 2, Tier = "Bronze", Share = 0.34 } }, "THE BOSS WON", Sign.Red },
			{ "ring run", "battle:ring", { Mode = "Ring", Outcome = "Left", Won = false, Reason = "Forfeit", Round = 8,
				Rewards = { Won = false, Final = true, Round = 8, Cash = 0, Xp = 0, LevelUps = 2, Run = { Wins = 8, Cash = 2571, Xp = 806, Tokens = 0, Round = 8, Start = 1, Best = 12 } } },
				"RUN OVER", Sign.Violet },
			{ "dungeon", "battle:dungeon", { Mode = "Dungeon", Outcome = "Loss", Won = false, Reason = "Wipe",
				Rewards = { Dungeon = true, Tokens = 260, Xp = 120, Extra = { Floor = 3, Room = 2 } } }, "KNOCKED OUT", Sign.Violet },
			{ "worst", "battle:raid", { Mode = "Raid", Outcome = "Win", Won = true, Reason = "BossDown",
				Rewards = { Tokens = 1.01e9, Xp = 1.01e9, LevelUps = 12, Tier = "Helper", Share = 1 } }, "BOSS DEFEATED!", Sign.Grass, true },
		}
		local function finish(d)
			local cur = d
			while cur do
				if cur.Name:match("^Finish") then
					return true
				end
				cur = cur.Parent
			end
			return false
		end
		local seenParts = {}
		-- (look review round 1) a phone's OK is a thumb's 44 screen px tall: the plank itself or its clear hit pad (HitFor)
		local function okTouch(ok)
			local hTall = ok and ok.AbsoluteSize.Y or 0
			for _, c in ipairs(ok and ok:GetChildren() or {}) do
				if c:IsA("GuiButton") and c:GetAttribute("HitFor") == "OkButton" and U8.shown(c) then
					hTall = math.max(hTall, c.AbsoluteSize.Y)
				end
			end
			return hTall
		end
		-- (look review round 1, majors) a phone's card keeps off the game's DASH and RUN (wholly: DASH was hidden under the
		-- card at 844x390), Roblox's jump button and thumbstick and the top-right stack; a landscape phone's card is the
		-- pitch's top middle (02_result_card_optB_phone.png: 222..622 of 844, so over the screen's centre point: the fight
		-- is over, and the old "off the centre" right-edge spot is what put it on DASH / RUN) with 8 px or more to the edge
		local function phoneClear(tag, card, w, h)
			local gui = card:FindFirstAncestorWhichIsA("ScreenGui")
			local cr = U8.rect(card)
			local portrait = h > w
			local hits = U99.overTouch(gui, cr, portrait, nil)
			T.check(#hits == 0, tag .. ": the card keeps off DASH, RUN, the jump button and the thumbstick", table.concat(hits, "; ") .. " | card " .. U8.show(cr))
			local tr = U99.overTopRight(gui, cr)
			T.check(#tr == 0, tag .. ": the card keeps off the top-right stack", table.concat(tr, "; "))
			local scr = U8.srect and U8.srect(card) or cr
			T.check(scr.X >= 8 - 0.5 and scr.R <= w - 8 + 0.5, tag .. ": 8 px or more from the screen's sides", U8.show(scr))
			if not portrait then
				T.check(math.abs((cr.X + cr.R) / 2 - w / 2) <= w * 0.12, tag .. ": a landscape phone's card is the pitch's top middle", U8.show(cr))
			end
		end
		local battleW = {} -- (P2 fix A) the battle result card's width per size ("WxH")
		for _, s in ipairs(U8.SIZES) do
			local at = s[3] and function(w, h, _, label, fn)
				U99.atPhone(w, h, label, fn)
			end or U8.at
			for _, v in ipairs(VARIANTS) do
				at(s[1], s[2], s[3], "result card B " .. v[1], function(tag)
					U96.open(v[2])
					local d = U96.d
					local B = BC._St.battle
					if not T.check(d and B, tag .. ": (setup) the fight is up") then
						U96.close()
						return
					end
					if v[6] and B.boss then
						B.boss.name = "Twentycharacterboss1"
					end
					local payload = {}
					for k2, x in pairs(v[3]) do
						payload[k2] = x
					end
					payload.BattleId, payload.Spectator = d.id, false
					LKC.toClient("BattleState", "End", payload, d.id)
					LKC.advance(0.9)
					local gui = U8.pg():FindFirstChild("NimbusBattle")
					local card = gui and gui.Root:FindFirstChild("ResultCard")
					if not T.check(card and U8.shown(card), tag .. ": the result card shows") then
						U96.close()
						return
					end
					local body = card:FindFirstChild("Body")
					local k = U8.scaleOf(card)
					local cr = U8.rect(card)
					battleW[s[1] .. "x" .. s[2]] = cr.R - cr.X -- (P2 fix A) the dungeon's End card below matches it on a portrait phone
					-- the template's parts, the same in every variant
					local head = body and body:FindFirstChild("Head")
					local title = head and head:FindFirstChild("Title")
					local parts = {}
					for _, n in ipairs({ "Head", "Reason", "Stats", "Chips", "OkButton" }) do
						local p = body and body:FindFirstChild(n)
						parts[#parts + 1] = (p and U8.shown(p)) and n or ("-" .. n)
					end
					local key = table.concat(parts, ",")
					seenParts[key] = true
					T.check(key == "Head,Reason,Stats,Chips,OkButton", tag .. ": one template: the head, the reason, the stats, the chips, OK", key)
					T.check(head and sameColor(head.BackgroundColor3, v[5]) and title and title.Text == v[4] and head:FindFirstChild("Icon") ~= nil and U8.shown(head.Icon),
						tag .. ": the head band in the result's colour with its icon and word", head and (hex(head.BackgroundColor3) .. " " .. (title and title.Text or "?")) or "no head")
					-- stat rows: label, value right-aligned before a green tick block with its check
					local stats = body and body:FindFirstChild("Stats")
					local rows, badRow = 0, {}
					for _, row in ipairs(stats and stats:GetChildren() or {}) do
						if row.Name:match("^Stat_") and U8.shown(row) then
							rows = rows + 1
							local lab, val, tick = row:FindFirstChild("Label"), row:FindFirstChild("Value"), row:FindFirstChild("Tick")
							if not (lab and val and tick and U8.shown(tick) and sameColor(tick.BackgroundColor3, Sign.Grass) and tick:FindFirstChild("Check")
								and val.TextXAlignment == Enum.TextXAlignment.Right and U8.rect(val).R <= U8.rect(tick).X + 0.5 and U8.rect(lab).R <= U8.rect(val).X + 1) then
								badRow[#badRow + 1] = row.Name
							end
						end
					end
					T.check(rows >= 2 and #badRow == 0, tag .. ": stat rows: label, the value right-aligned, a green tick each", fmt("%d rows; bad: %s", rows, table.concat(badRow, ", ")))
					-- (P2 fix A look review r1, minor: the ring's 3 stats in 2 columns at 844x390 left an empty cell) every stat
					-- line is filled across the stats' width: an odd last stat spans the line
					if stats and U8.shown(stats) then
						local sr, lines = U8.rect(stats), {}
						for _, row in ipairs(stats:GetChildren()) do
							if row.Name:match("^Stat_") and U8.shown(row) then
								local r = U8.rect(row)
								local key = math.floor(r.Y + 0.5)
								lines[key] = lines[key] or { X = math.huge, R = -math.huge }
								lines[key].X = math.min(lines[key].X, r.X)
								lines[key].R = math.max(lines[key].R, r.R)
							end
						end
						local holes = {}
						for y, l in pairs(lines) do
							if l.X > sr.X + 1 or l.R < sr.R - 1 then
								holes[#holes + 1] = fmt("y %d: %.0f..%.0f of %.0f..%.0f", y, l.X, l.R, sr.X, sr.R)
							end
						end
						T.check(#holes == 0, tag .. ": every stat line filled across the card (no empty cell)", table.concat(holes, "; "))
					end
					-- reward chips: equal widths, the number on each (the word under it on a wide screen)
					local chips = body and body:FindFirstChild("Chips")
					local widths, badChip = {}, {}
					for _, c in ipairs(chips and chips:GetChildren() or {}) do
						if c.Name:match("^Chip_") and U8.shown(c) then
							widths[#widths + 1] = c.AbsoluteSize.X
							local num = c:FindFirstChild("Number")
							if not (num and U8.shown(num) and num.Text:match("^[%+%-]?%$?%d") and P2.inside(U8.rect(num), U8.rect(c))) then
								badChip[#badChip + 1] = c.Name
							end
						end
					end
					local eq = #widths >= 1
					for _, w in ipairs(widths) do
						eq = eq and math.abs(w - widths[1]) <= 1
					end
					T.check(eq and #badChip == 0, tag .. ": equal reward chips, the number on each", fmt("%d chips; bad: %s", #widths, table.concat(badChip, ", ")))
					-- OK: the card's whole inside width, green, its lip in 5 parts (the timer)
					local ok = body and body:FindFirstChild("OkButton")
					local lip = ok and ok:FindFirstChild("Lip")
					local segs = 0
					for _, c in ipairs(lip and lip:GetChildren() or {}) do
						segs = segs + (c.Name:match("^Seg%d$") and 1 or 0)
					end
					T.check(ok and sameColor(ok.BackgroundColor3, Sign.Grass) and ok.AbsoluteSize.X >= cr.R - cr.X - 2 * 14 * k and segs == 5,
						tag .. ": OK spans the card, green, its lip the 5-part timer", ok and fmt("%.0f of %.0f, %d parts", ok.AbsoluteSize.X, cr.R - cr.X, segs) or "no OK")
					-- nothing out of the card; every one-line text whole; off the screen centre
					local out = {}
					for _, dd in ipairs(card:GetDescendants()) do
						if dd:IsA("GuiObject") and U8.shown(dd) and dd.AbsoluteSize.X > 0 and not finish(dd) and (dd.BackgroundTransparency < 1 or ((dd:IsA("TextLabel") or dd:IsA("TextButton")) and dd.Text ~= "")) then
							if not P2.inside(U8.rect(dd), cr) then
								out[#out + 1] = dd.Name .. " " .. U8.show(U8.rect(dd))
							end
						end
					end
					T.check(#out == 0, tag .. ": nothing sticks out of the card", table.concat(out, "; ", 1, math.min(#out, 6)) .. " | card " .. U8.show(cr))
					local tight = P2.tight(card)
					T.check(#tight == 0, tag .. ": every one-line text of the card fits its box", table.concat(tight, "; "))
					local cx, cy = s[1] / 2, s[2] / 2
					if s[3] then
						T.check(okTouch(ok) >= 44 - 0.5, tag .. ": OK is a thumb's 44 px tall (the plank or its hit pad)", fmt("%.1f px", okTouch(ok)))
						T.check(cr.X >= -0.5 and cr.R <= s[1] + 0.5 and cr.B <= s[2] + 0.5, tag .. ": on the screen", U8.show(cr))
						phoneClear(tag, card, s[1], s[2])
					else
						T.check(not (cr.X <= cx and cx <= cr.R and cr.Y <= cy and cy <= cr.B) and cr.X >= -0.5 and cr.R <= s[1] + 0.5 and cr.B <= s[2] + 0.5,
							tag .. ": on the screen, off its centre", U8.show(cr))
					end
					U96.close()
				end)
			end
			-- (look review round 1, major) the dungeon's End card (DungeonController, NimbusDungeonRun.EndCard) is the SAME
			-- template (the pitch draws "RUN OVER (dungeon)" on it): the head band (a cleared floor green, a lost run violet), the
			-- reason line (a landscape phone may drop it for room), stat rows with ticks, equal chips, the notes (the first clear,
			-- the unlock) and the full-width green OK with its 5-part timer lip
			local DUNGEON = {
				{ "dungeon cleared", { Floor = 3, Name = "Flooded Vaults", Cleared = true, Reason = "Cleared", Room = 4,
					Totals = { Cash = 1630, Tokens = 170, Xp = 360, Gems = 0 }, FirstClear = { Tokens = 900, Gems = 5 }, Unlocked = 4, NewBest = 3 }, "FLOOR 3 CLEARED!", Sign.Grass },
				{ "dungeon run over", { Floor = 5, Name = "Ember Forge", Cleared = false, Reason = "Wipe", Room = 3,
					Totals = { Cash = 520, Tokens = 52, Xp = 160, Gems = 0 } }, "RUN OVER", Sign.Violet },
			}
			for _, dv in ipairs(DUNGEON) do
				at(s[1], s[2], s[3], "result card B " .. dv[1], function(tag)
					LKC.toClient("DungeonState", "End", dv[2])
					LKC.advance(0.8)
					local rg = U8.pg():FindFirstChild("NimbusDungeonRun")
					local card = rg and rg:FindFirstChild("EndCard")
					if not T.check(card and U8.shown(card), tag .. ": the End card shows") then
						return
					end
					local body = card:FindFirstChild("Body")
					local cr = U8.rect(card)
					local k = U8.scaleOf(card)
					local head = body and body:FindFirstChild("Head")
					local title = head and head:FindFirstChild("Title")
					local parts = {}
					for _, n in ipairs({ "Head", "Reason", "Stats", "Chips", "OkButton" }) do
						local p = body and body:FindFirstChild(n)
						if (p and U8.shown(p)) or not (n == "Reason" and s[3] and s[1] > s[2]) then
							parts[#parts + 1] = (p and U8.shown(p)) and n or ("-" .. n)
						end
					end
					local key = table.concat(parts, ",")
					T.check(key == "Head,Reason,Stats,Chips,OkButton" or (s[3] and s[1] > s[2] and key == "Head,Stats,Chips,OkButton"),
						tag .. ": the battle's template: the head, the reason, the stats, the chips, OK", key)
					T.check(head and sameColor(head.BackgroundColor3, dv[4]) and title and title.Text == dv[3] and head:FindFirstChild("Icon") ~= nil,
						tag .. ": the head band in the result's colour with its icon and word", head and (hex(head.BackgroundColor3) .. " " .. (title and title.Text or "?")) or "no head")
					local rows, badRow = 0, {}
					for _, row in ipairs(body and body:FindFirstChild("Stats") and body.Stats:GetChildren() or {}) do
						if row.Name:match("^Stat_") and U8.shown(row) then
							rows = rows + 1
							local tick = row:FindFirstChild("Tick")
							if not (tick and U8.shown(tick) and sameColor(tick.BackgroundColor3, Sign.Grass)) then
								badRow[#badRow + 1] = row.Name
							end
						end
					end
					T.check(rows >= 2 and #badRow == 0, tag .. ": stat rows, a green tick each", fmt("%d rows; bad: %s", rows, table.concat(badRow, ", ")))
					local widths = {}
					for _, c in ipairs(body and body:FindFirstChild("Chips") and body.Chips:GetChildren() or {}) do
						if c.Name:match("^Chip_") and U8.shown(c) then
							widths[#widths + 1] = c.AbsoluteSize.X
						end
					end
					local eq = #widths >= 3
					for _, w in ipairs(widths) do
						eq = eq and math.abs(w - widths[1]) <= 1
					end
					T.check(eq, tag .. ": the totals as equal reward chips", fmt("%d chips", #widths))
					if s[3] and s[2] > s[1] then
						-- (P2 fix A, look: at 390 x 844 the End card was 217.6 px wide beside the menu column, its third chip alone on a
						-- second row, its lines wrapped) a portrait phone's End card is the battle result card's width (one template,
						-- K.RESULT_W at the phone's 0.8: 352 px), its chips in one row, clear of the touch keys, the top-right stack and
						-- the screen's sides, the menu tiles stepping aside where it covers them (as for the battle's card)
						local rowsY, chipN = {}, 0
						for _, c in ipairs(body and body:FindFirstChild("Chips") and body.Chips:GetChildren() or {}) do
							if c.Name:match("^Chip_") and U8.shown(c) then
								chipN = chipN + 1
								rowsY[math.floor(U8.rect(c).Y + 0.5)] = true
							end
						end
						local nRows = 0
						for _ in pairs(rowsY) do
							nRows = nRows + 1
						end
						local want = battleW[s[1] .. "x" .. s[2]]
						T.check(want and math.abs((cr.R - cr.X) - want) <= 1 and chipN >= 3 and nRows == 1,
							tag .. ": the battle result card's width, its chips in one row", fmt("%.1f px wide (battle %s), %d chips in %d rows", cr.R - cr.X, tostring(want), chipN, nRows))
						phoneClear(tag, card, s[1], s[2])
						local menuGui = U8.pg():FindFirstChild("NimbusMenu")
						local under = {}
						for _, t in ipairs(menuGui and menuGui:GetDescendants() or {}) do
							if t:IsA("GuiButton") and U8.shown(t) and t.AbsoluteSize.X > 0 and U8.overlap(U8.rect(t), cr) then
								under[#under + 1] = t.Name
							end
						end
						T.check(#under == 0, tag .. ": the menu tiles step aside where the card covers them", table.concat(under, ", "))
					end
					local ok = body and body:FindFirstChild("OkButton")
					local segs = 0
					for _, c in ipairs(ok and ok:FindFirstChild("Lip") and ok.Lip:GetChildren() or {}) do
						segs = segs + (c.Name:match("^Seg%d$") and 1 or 0)
					end
					T.check(ok and sameColor(ok.BackgroundColor3, Sign.Grass) and ok.AbsoluteSize.X >= cr.R - cr.X - 2 * 14 * k and segs == 5,
						tag .. ": OK spans the card, green, its lip the 5-part timer", ok and fmt("%.0f of %.0f, %d parts", ok.AbsoluteSize.X, cr.R - cr.X, segs) or "no OK")
					if dv[2].FirstClear then
						local fc, un = body:FindFirstChild("FirstClear"), body:FindFirstChild("Unlocked")
						T.check(fc and U8.shown(fc) and fc.Text:find("+900", 1, true) and un and U8.shown(un) and un.Text:find("Floor 4 unlocked", 1, true),
							tag .. ": the first clear and the unlock as notes", (fc and fc.Text or "no FirstClear") .. " | " .. (un and un.Text or "no Unlocked"))
					end
					local out = {}
					for _, dd in ipairs(card:GetDescendants()) do
						if dd:IsA("GuiObject") and U8.shown(dd) and dd.AbsoluteSize.X > 0 and not finish(dd) and (dd.BackgroundTransparency < 1 or ((dd:IsA("TextLabel") or dd:IsA("TextButton")) and dd.Text ~= "")) then
							if not P2.inside(U8.rect(dd), cr) then
								out[#out + 1] = dd.Name .. " " .. U8.show(U8.rect(dd))
							end
						end
					end
					T.check(#out == 0, tag .. ": nothing sticks out of the card", table.concat(out, "; ", 1, math.min(#out, 6)) .. " | card " .. U8.show(cr))
					local tight = P2.tight(card)
					T.check(#tight == 0, tag .. ": every one-line text of the card fits its box", table.concat(tight, "; "))
					if s[3] then
						T.check(okTouch(ok) >= 44 - 0.5, tag .. ": OK is a thumb's 44 px tall (the plank or its hit pad)", fmt("%.1f px", okTouch(ok)))
					end
					if ok then
						Mock.Click(ok)
						LKC.advance(0.4)
					end
					T.check(not U8.shown(card), tag .. ": OK closes the End card")
				end)
			end
		end
		-- (look review round 1, minor) a duel that moved no trophies says so in a muted note, not a "+0" chip on a VICTORY, and
		-- a duel's card shows the trophy total as a stat row (Rewards.TrophiesTotal, sent by BattleService)
		do
			local Hd = BC._Hud
			local model = Hd and Hd.ResultModel({ Mode = "Duel", Fighter = true, lives = 3, renderT = 64, list = {} },
				{ Mode = "Duel", Outcome = "Win", Won = true, Reason = "KO", Rewards = { Tokens = 60, Xp = 50, Trophies = 0, TrophiesTotal = 240 } })
			local chipKeys, statKeys, noteText = {}, {}, {}
			for _, c in ipairs(model and model.chips or {}) do
				chipKeys[c[1]] = c[3]
			end
			for _, st in ipairs(model and model.stats or {}) do
				statKeys[st[1]] = st[4]
			end
			for _, n in ipairs(model and model.notes or {}) do
				noteText[#noteText + 1] = n[1] .. (n[2] and " (muted)" or "")
			end
			T.check(model and chipKeys.Trophies == nil and table.concat(noteText, "|"):find("[Tt]roph.-%(muted%)") ~= nil,
				"result card B duel: no '+0 Trophies' chip on a VICTORY; a muted note says no trophies moved", table.concat(noteText, " | "))
			T.check(model and statKeys.Trophies == "240", "result card B duel: the trophy total as a stat row", tostring(statKeys.Trophies))
		end
		restore()
		LKC.flushErrors("result_card_template_b")
	end)

	-- (Pitch 2 item 08, option C "Name tab + stamp", .superpowers/slop-audit/round3/build/PITCH2/A_battle_hud/08_vitals_optC.png)
	-- at the four grid sizes the vitals card keeps its bottom-centre spot and gains a wood tab tucked behind its top edge (the
	-- tab above the card, its foot under the card's top, drawn behind it) with the player's stamp (the display name's first
	-- letter on a 30 px block in one of the 5 kit colours by UserId % 5), the display name and the trophies tag (the pixel
	-- trophy, Theme.Short of Battle.Trophies); the body is the HP track (its blocks and the number inside ONE sunk track, a
	-- divider between them) and the stamina group (the bolt, the stamina blocks and, on a desktop, the dash key inside one
	-- sunk well); no level anywhere on the card. Worst case: a 20-character name and 1.23M trophies fit the tab, the tab fits
	-- the card, every one-line text fits its box
	S.vitals_name_tab = guarded("vitals_name_tab", function()
		local Theme = LoadingH.shared("Theme")
		local Sign = Theme.Sign
		local lp = game:GetService("Players").LocalPlayer
		local STAMPS = { Sign.Sky, Sign.Grass, Sign.Gold, Sign.Red, Sign.Violet }
		local restore = U8.measureReal()
		local oldName = lp.DisplayName
		for _, s in ipairs(U8.SIZES) do
			for _, case in ipairs({ { "SkyClimber", 240, "240" }, { "AVeryLongClimberName", 1234567, "1.23M" } }) do
				U8.at(s[1], s[2], s[3], "vitals name tab (" .. case[1] .. ")", function(tag)
					lp.DisplayName = case[1]
					U8.feed(nil, nil, nil, nil, { Battle = { Trophies = case[2], TrialBest = 0, TrialCleared = {}, Raids = 0, RaidBestDamage = 0, PvPWins = 0, PvPLosses = 0, EventPets = {} } })
					LKC.advance(1)
					local hud = U8.pg():FindFirstChild("NimbusHud")
					local vitals = hud and hud:FindFirstChild("Vitals", true)
					if not T.check(vitals ~= nil and U8.shown(vitals), tag .. ": the vitals card shows") then
						return
					end
					local card = vitals:FindFirstChild("Card", true)
					local tab = vitals:FindFirstChild("NameTab", true)
					if not T.check(card ~= nil and tab ~= nil and U8.shown(tab), tag .. ": the card has its name tab") then
						return
					end
					local cr, tr, vr = U8.rect(card), U8.rect(tab), U8.rect(vitals)
					T.check(tr.Y < cr.Y - 8 and tr.B > cr.Y and tab.ZIndex < card.ZIndex and sameColor(tab.BackgroundColor3, Sign.Wood),
						tag .. ": a wood tab above the card, its foot tucked behind the card's top edge", U8.show(tr) .. " / card " .. U8.show(cr))
					T.check(P2.inside(tr, vr) and P2.inside(cr, vr) and tr.X >= cr.X and tr.R <= cr.R, tag .. ": the tab and the card inside the vitals slot, the tab within the card's width",
						U8.show(tr) .. " / " .. U8.show(cr) .. " in " .. U8.show(vr))
					local stamp = tab:FindFirstChild("Stamp", true)
					local letter = stamp and stamp:FindFirstChild("Letter")
					local want = STAMPS[(lp.UserId % 5) + 1]
					T.check(stamp and letter and letter.Text == case[1]:sub(1, 1):upper() and sameColor(stamp.BackgroundColor3, want)
						and math.abs(stamp.AbsoluteSize.X / U8.scaleOf(stamp) - 30) < 0.6,
						tag .. ": the stamp is the name's first letter on a 30 px block in the kit colour of UserId % 5",
						stamp and fmt("%s on %s (%d)", letter and letter.Text or "-", hex(stamp.BackgroundColor3), lp.UserId % 5) or "no stamp")
					local name = tab:FindFirstChild("PlayerName", true)
					T.check(name and U8.shown(name) and (name.Text == case[1] or (name.Text:sub(-3) == "..." and case[1]:find(name.Text:sub(1, -4), 1, true) == 1)),
						tag .. ": the tab names the player (DisplayName)", name and name.Text or "missing")
					local trophies = tab:FindFirstChild("Trophies", true)
					local tv = trophies and trophies:FindFirstChild("Value")
					local icon = nil
					for _, d in ipairs(trophies and trophies:GetDescendants() or {}) do
						if d:GetAttribute("PixelIcon") == "trophy" then
							icon = d
						end
					end
					T.check(tv and tv.Text == case[3] and icon ~= nil and U8.shown(icon), tag .. ": the trophies tag: the pixel trophy and Theme.Short(Battle.Trophies)",
						tv and tv.Text or "missing")
					local parts = {}
					for _, p in ipairs({ stamp, name, trophies }) do
						if p and not P2.inside(U8.rect(p), tr) then
							parts[#parts + 1] = p.Name .. " " .. U8.show(U8.rect(p))
						end
					end
					T.check(#parts == 0, tag .. ": the stamp, the name and the trophies inside the tab", table.concat(parts, "; ") .. " | tab " .. U8.show(tr))
					-- the HP track: the blocks and the number in one sunk track, a divider between them
					local track = vitals:FindFirstChild("HpTrack", true)
					local blocks, num = vitals:FindFirstChild("HealthBar", true), vitals:FindFirstChild("HealthNumber", true)
					local divider = track and track:FindFirstChild("Divider", true)
					if T.check(track and blocks and num and divider and U8.shown(track), tag .. ": the HP track with its blocks, divider and number") then
						local kr, br, nr, dr = U8.rect(track), U8.rect(blocks), U8.rect(num), U8.rect(divider)
						T.check(P2.inside(br, kr) and P2.inside(nr, kr) and br.R <= dr.X + 0.5 and dr.R <= nr.X + 0.5 and P2.inside(kr, cr),
							tag .. ": the number in the HP track behind the divider, right of the blocks (the track inside the card)",
							fmt("blocks %s | divider %s | number %s in %s", U8.show(br), U8.show(dr), U8.show(nr), U8.show(kr)))
						T.check(num.Text:match("^%d") ~= nil, tag .. ": the number shows the HP", num.Text)
					end
					-- the stamina group: the bolt, the blocks and (desktop) the dash key in one sunk well
					local group = vitals:FindFirstChild("StaminaGroup", true)
					local st, key = vitals:FindFirstChild("StaminaBar", true), vitals:FindFirstChild("DashKey", true)
					if T.check(group and st and U8.shown(group), tag .. ": the stamina group shows") then
						local gr = U8.rect(group)
						local bolt = nil
						for _, d in ipairs(group:GetDescendants()) do
							if d:GetAttribute("PixelIcon") == "bolt" and U8.shown(d) then
								bolt = d
							end
						end
						T.check(P2.inside(U8.rect(st), gr) and bolt ~= nil and P2.inside(U8.rect(bolt), gr) and P2.inside(gr, cr),
							tag .. ": the bolt and the stamina blocks inside the group (inside the card)", U8.show(U8.rect(st)) .. " in " .. U8.show(gr))
						if not s[3] then
							T.check(key and U8.shown(key) and P2.inside(U8.rect(key), gr) and U8.rect(key).X >= U8.rect(st).R, tag .. ": the dash key ends the stamina group",
								key and U8.show(U8.rect(key)) or "no key")
						end
						-- (look review round 1, minor: the right half of a phone's well was empty) the dash's state in words after
						-- the blocks on every size (the phone mock-up's "Dash ready"; the shorter set where the longest will not fit)
						local words = group:FindFirstChild("DashState")
						T.check(words and U8.shown(words) and words.Text ~= "" and P2.inside(U8.rect(words), gr) and U8.rect(words).X >= U8.rect(st).R,
							tag .. ": the dash's state in words after the stamina blocks", words and (words.Text .. " " .. U8.show(U8.rect(words)) .. " in " .. U8.show(gr) .. ", blocks " .. U8.show(U8.rect(st))) or "no DashState")
					end
					-- no level on the card (the game has no player level; Battle.Trophies is the tag)
					local level = {}
					for _, d in ipairs(vitals:GetDescendants()) do
						if (d:IsA("TextLabel") or d:IsA("TextButton")) and U8.shown(d) and (d.Text:match("^Lv") or d.Text:lower():find("level", 1, true)) then
							level[#level + 1] = d.Name .. " " .. d.Text
						end
					end
					T.check(#level == 0, tag .. ": no level shown on the card", table.concat(level, ", "))
					local tight = P2.tight(vitals)
					T.check(#tight == 0, tag .. ": every one-line text fits its box", table.concat(tight, "; "))
				end)
			end
		end
		lp.DisplayName = oldName
		U8.feed()
		restore()
		LKC.flushErrors("vitals_name_tab")
	end)

	-- the tutorial card on the Signboard kit (1920x1080, step 5 of a menu target): the wood frame round the stone body and its
	-- lip, no shadow / puffs / gloss / gradient; the portrait a square sky well in a wood frame with its ground lip and a
	-- pixel cloud; GuideName a plain Section title and the step title brown; the counter a stone tag and the fold a stone
	-- block with the pixel minus; the pips kit B blocks (done grass, the current gold, the rest the sunk well); the text well
	-- a pale tile in a wood edge; Next the one green plank; nothing round, every edge mitred, one pixel size, every text
	-- reads; folded: the "!" badge a gold block
	S.tutorial_signboard_skin = guarded("tutorial_signboard_skin", function()
		local Sign = LoadingH.shared("Theme").Sign
		U8.at(1920, 1080, false, "tutorial skin", function(tag)
			local gui, root = U99.tutorial(5, true)
			local main = root and root:FindFirstChild("Main", true)
			if not T.check(main ~= nil and U8.shown(main), tag .. ": the tutorial card is open") then
				U99.tutorialOff()
				return
			end
			local card = main:FindFirstChild("Card")
			local stone = card and card:FindFirstChild("Stone")
			T.check(card and sameColor(card.BackgroundColor3, Sign.Wood) and stone and sameColor(stone.BackgroundColor3, Sign.Stone) and stone:FindFirstChild("Lip") ~= nil,
				tag .. ": the wood frame round the stone body and its lip")
			local gone = {}
			for _, name in ipairs({ "Shadow", "PuffRings", "Puffs", "Gloss", "Rim", "Glow", "Disc", "CloudBank" }) do
				if root:FindFirstChild(name, true) then
					gone[#gone + 1] = name
				end
			end
			T.check(#gone == 0, tag .. ": no shadow, puffs, gloss, rim or round disc left", table.concat(gone, ", "))
			local portrait = root:FindFirstChild("Portrait", true)
			local sky = portrait and portrait:FindFirstChild("Sky", true)
			local cloud = sky and sky:FindFirstChild("Cloud")
			T.check(portrait and sky and sameColor(sky.BackgroundColor3, Sign.Sky) and portrait:FindFirstChild("Ground") ~= nil and cloud ~= nil
				and portrait:FindFirstChild("Toggle") ~= nil and portrait:FindFirstChild("Nimbus") ~= nil,
				tag .. ": the portrait is a sky well in a wood frame (its ground lip, a pixel cloud, Nimbus' viewport, the tap target)")
			local name, step = root:FindFirstChild("GuideName", true), root:FindFirstChild("StepTitle", true)
			-- (U9-9 look 2) the speaker's name on the NPC dialog's plank (one header language for the two speaker cards): a
			-- navy plank in a gold-lip edge, its navy lip, two brass rivets, the name a plain Section title in gold, riding the
			-- card's top edge; the step title brown on the stone
			local plank = name and name.Parent
			local rivets = 0
			for _, n in ipairs({ "RivetL", "RivetR" }) do
				local rv = plank and plank:FindFirstChild(n)
				if rv and U8.shown(rv) and sameColor(rv.BackgroundColor3, Sign.Brass) then
					rivets = rivets + 1
				end
			end
			local plankEdge, plankLip = plank and plank:FindFirstChild("SignEdge"), plank and plank:FindFirstChild("Lip")
			T.check(name and name:GetAttribute("TitleLook") == "Section" and sameColor(name.TextColor3, Sign.Gold) and plank and plank.Name == "NameTab"
				and sameColor(plank.BackgroundColor3, Sign.Navy) and plankEdge and sameColor(plankEdge.Color, Sign.GoldLip) and plankLip and sameColor(plankLip.BackgroundColor3, Sign.NavyLip)
				and rivets == 2 and step and sameColor(step.TextColor3, Sign.Text),
				tag .. ": the name a plain Section title in gold on the NPC's navy plank (gold-lip edge, navy lip, two rivets), the step title brown")
			local cardR = card and U8.rect(card)
			local pr = plank and U8.rect(plank)
			T.check(pr and cardR and pr.Y < cardR.Y - 0.5 and pr.B > cardR.Y + 0.5, tag .. ": the name plank rides the card's top edge",
				pr and cardR and (U8.show(pr) .. " / card top " .. fmt("%.1f", cardR.Y)) or "")
			-- (U9-9 look) the counter tag lies clear of the name (it lay 12 px over it); (U9-9 look 2) the plank and its gold
			-- edge clear of the counter tag and the fold block (their wood edges too)
			local clash = {}
			for _, n in ipairs({ "Counter", "Fold" }) do
				local b = root:FindFirstChild(n, true)
				if b and U8.shown(b) and pr then
					local e1, e2 = 3 * U8.scaleOf(plank), 2 * U8.scaleOf(b)
					local br = U8.rect(b)
					if U8.overlap({ X = pr.X - e1, R = pr.R + e1, Y = pr.Y - e1, B = pr.B + e1 }, { X = br.X - e2, R = br.R + e2, Y = br.Y - e2, B = br.B + e2 }) then
						clash[#clash + 1] = n .. " " .. U8.show(br)
					end
				end
			end
			T.check(#clash == 0, tag .. ": the name plank clear of the counter tag and the fold", table.concat(clash, "; "))
			local counter, fold = root:FindFirstChild("Counter", true), root:FindFirstChild("Fold", true)
			local minus = false
			for _, d in ipairs(fold and fold:GetDescendants() or {}) do
				minus = minus or (d:IsA("Frame") and d:GetAttribute("PixelIcon") == "minus")
			end
			T.check(counter and sameColor(counter.BackgroundColor3, Sign.Tile) and counter:FindFirstChild("SignEdge") ~= nil and fold and fold:FindFirstChild("SignEdge") ~= nil and minus,
				tag .. ": the counter a stone tag, the fold a stone block with the pixel minus")
			-- (U9-9 look) the progress is ONE SignKit block row (the kit's block-bar language), a block per step here (1080p:
			-- each gets 10 px or more), no pips and no thin bar left; its blocks whole screen px
			local row = root:FindFirstChild("BlockRow", true)
			local states, wrong = {}, {}
			local per = row and row:GetAttribute("PerBlock") or 1
			for i = 1, (row and row:GetAttribute("Count") or 0) do
				local b = row:FindFirstChild("Block" .. i)
				local face = b and b:FindFirstChild("Face")
				local now = math.ceil(5 / per)
				local want = i < now and "Done" or (i == now and "Current" or "Open")
				local colour = ({ Done = Sign.Grass, Current = Sign.Gold, Open = Sign.Well })[want]
				states[#states + 1] = b and b:GetAttribute("State")
				if not (b and face and b:GetAttribute("State") == want and sameColor(face.BackgroundColor3, colour) and sameColor(b.BackgroundColor3, Sign.Wood)) then
					wrong[#wrong + 1] = "Block" .. i .. " " .. tostring(b and b:GetAttribute("State"))
				end
				local r = b and U8.rect(b)
				if r and (math.abs(r.X - math.floor(r.X + 0.5)) > 0.01 or math.abs(r.Y - math.floor(r.Y + 0.5)) > 0.01 or math.abs(r.R - r.X - math.floor(r.R - r.X + 0.5)) > 0.01) then
					wrong[#wrong + 1] = "Block" .. i .. " off the pixel grid " .. U8.show(r)
				end
			end
			-- (kit-b gate U9 r4: 21 thin blocks beside "Step 1/21" repeated the counter as noise) more than 8 steps show as
			-- chapters of 3 (21 steps: 7 blocks), each block 10 screen px or more
			local steps = row and row:GetAttribute("Steps") or 0
			local narrow = {}
			for i = 1, #states do
				local b = row:FindFirstChild("Block" .. i)
				if b and b.AbsoluteSize.X < 10 then
					narrow[#narrow + 1] = "Block" .. i .. " " .. b.AbsoluteSize.X
				end
			end
			T.check(row ~= nil and row:GetAttribute("SignKit") == "BlockRow" and (steps <= 8 or per == 3) and #states == math.ceil(steps / per) and #states <= 8 and #wrong == 0 and #narrow == 0,
				tag .. ": the progress is one SignKit block row, chapters of 3 over 8 steps (done grass, the current gold, the rest the sunk well), each 10 px or more, on whole px",
				table.concat(wrong, ", ") .. table.concat(narrow, ", ") .. " | per " .. tostring(per) .. " of " .. tostring(steps))
			local old = {}
			for _, name in ipairs({ "Pips", "PipBar", "Pip1" }) do
				if root:FindFirstChild(name, true) then
					old[#old + 1] = name
				end
			end
			T.check(#old == 0, tag .. ": no pips and no thin progress bar left (one look for the progress)", table.concat(old, ", "))
			local well = main:FindFirstChild("Well")
			T.check(well and sameColor(well.BackgroundColor3, Sign.Tile) and well:FindFirstChild("SignEdge") ~= nil, tag .. ": the text well is a pale tile in a wood edge")
			local nextB = root:FindFirstChild("Next", true)
			T.check(nextB == nil or not U8.shown(nextB) or (nextB:GetAttribute("Skin") == "Sign" and U8.green(U8.faceOf(nextB))), tag .. ": Next (when shown) is the green plank")
			T.check(#U94.roundOrGloss(root) == 0, tag .. ": nothing round or glossy on the card", table.concat(U94.roundOrGloss(root), ", "))
			T.check(#U99.roundEdges(root) == 0, tag .. ": every wood edge is mitred", table.concat(U99.roundEdges(root), ", "))
			T.check(#U94.floatingLips(root) == 0, tag .. ": every lip lies flush", table.concat(U94.floatingLips(root), "; "))
			local cells, odd = U99.pixelCells(root, { U99.cell(main) })
			T.check(#odd == 0, tag .. ": one pixel size: the card's icons on " .. U99.cell(main) .. " px cells", table.concat(odd, "; ") .. " | " .. table.concat(cells, ", "))
			local low = U94.contrast("NimbusTutorial")
			T.check(#low == 0, tag .. ": every text of the card reads on its fill", table.concat(low, "; "))
			-- a step that waits for Next (step 1): the green plank shown
			U99.tutorial(1, true)
			nextB = root:FindFirstChild("Next", true)
			T.check(nextB and U8.shown(nextB) and nextB:GetAttribute("Skin") == "Sign" and U8.green(U8.faceOf(nextB)), tag .. ": step 1's Next is the green plank")
			-- folded: (Pitch 2 item 03_tutorial_dock B: the bubble's "!" badge and its whole-px hop gave way to the quest strip,
			-- tutorial_dock_b) the strip is a stone block in its wood edge with its lip, its "+" a stone tag in its edge and
			-- lip, its step cells the row's kit faces (grass, gold, the well), and nothing round on it
			local foldB = root:FindFirstChild("Fold", true)
			if foldB then
				Mock.Click(foldB)
				LKC.advance(1)
			end
			local strip = root:FindFirstChild("QuestStrip", true)
			local plus = strip and strip:FindFirstChild("QuestOpen")
			T.check(strip and U8.shown(strip) and sameColor(strip.BackgroundColor3, Sign.Stone) and strip:FindFirstChild("SignEdge") ~= nil and strip:FindFirstChild("Lip") ~= nil
				and plus ~= nil and sameColor(plus.BackgroundColor3, Sign.Tile) and plus:FindFirstChild("SignEdge") ~= nil and plus:FindFirstChild("Lip") ~= nil,
				tag .. ": folded, the quest strip is a stone block in its wood edge, its + a stone tag")
			local faces, odd = 0, {}
			for _, d in ipairs(strip and strip:GetDescendants() or {}) do
				if d:GetAttribute("Step") then
					faces = faces + 1
					if not (sameColor(d.BackgroundColor3, Sign.Grass) or sameColor(d.BackgroundColor3, Sign.Gold) or sameColor(d.BackgroundColor3, Sign.Well)) then
						odd[#odd + 1] = d:GetFullName()
					end
				end
			end
			T.check(faces > 0 and #odd == 0, tag .. ": the strip's step cells wear the row's kit faces", table.concat(odd, ", "))
			T.check(#U94.roundOrGloss(root) == 0, tag .. ": the strip is square too", table.concat(U94.roundOrGloss(root), ", "))
			U99.tutorialOff()
		end)
		LKC.flushErrors("tutorial_signboard_skin")
	end)

	-- the tutorial on the phones (U99.PHONES, with the game's real RUN / DASH; step 1 and step 5): the bubble and the card the
	-- player opens each inside the screen, over no thumb zone and no RUN / DASH, their words inside them and >= 14 px
	S.tutorial_fits_phone = guarded("tutorial_fits_phone", function()
		for _, s in ipairs(U99.PHONES) do
			U99.atPhone(s[1], s[2], "tutorial phone", function(tag)
				for _, step in ipairs({ 1, 5 }) do
					for _, open in ipairs({ false, true }) do
						local what = fmt("%s step %d %s", tag, step, open and "opened" or "as shown")
						local gui, root = U99.tutorial(step, open)
						if T.check(root ~= nil and U8.shown(root), what .. ": the tutorial shows") then
							local main = root:FindFirstChild("Main", true)
							-- (Pitch 2 item 03_tutorial_dock B: folded, the guide is the quest strip; the portrait chip alone where
							-- the strip has no room)
							local strip = root:FindFirstChild("QuestStrip", true)
							local folded = (strip and U8.shown(strip)) and strip or root:FindFirstChild("Portrait", true)
							local part = (main and U8.shown(main)) and root or folded
							local r = U8.rect(part)
							if part == root then
								-- (U9-9 look 2) the opened card with the portrait and the name plank riding its top edge
								for _, n in ipairs({ "NameTab", "Portrait" }) do
									local p = root:FindFirstChild(n, true)
									if p and U8.shown(p) then
										local pr = U8.rect(p)
										local e = n == "NameTab" and 3 * U8.scaleOf(p) or 0
										r = { X = math.min(r.X, pr.X - e), Y = math.min(r.Y, pr.Y - e), R = math.max(r.R, pr.R + e), B = math.max(r.B, pr.B) }
									end
								end
							else
								-- the folded guide: the quest strip with the portrait chip on it (or the chip alone)
								for _, d in ipairs(part:GetDescendants()) do
									if d:IsA("GuiObject") and U8.shown(d) and d.AbsoluteSize.X > 0 then
										local dr = U8.rect(d)
										r = { X = math.min(r.X, dr.X), Y = math.min(r.Y, dr.Y), R = math.max(r.R, dr.R), B = math.max(r.B, dr.B) }
									end
								end
							end
							T.check(r.X >= -0.5 and r.Y >= -0.5 and r.R <= gui.AbsoluteSize.X + 0.5 and r.B <= gui.AbsoluteSize.Y + 0.5, what .. ": inside the screen", U8.show(r))
							local hits = U99.overTouch(gui, r, s[2] > s[1])
							if #hits == 1 and hits[1]:match("^thumbstick ") and s[2] <= 375 and part == root then
								-- (U9-9 review) known since before U9-9 (the old card did the same): on a 360 / 375 px tall phone
								-- nothing fits the opened card, so TutorialController's last resort shrinks it to 0.7 and it
								-- still reaches into the thumbstick's zone. Whether the touch controls step aside there (as for
								-- the Trove) is the owner's call; a warning until then
								T.warn(what .. ": the opened card reaches into the thumbstick's zone (the 0.7 last resort)", hits[1] .. " | " .. U8.show(r))
							else
								T.check(#hits == 0, what .. ": over no thumb zone and no RUN / DASH", table.concat(hits, "; ") .. " | " .. U8.show(r))
							end
							if part ~= root and not open then
								-- (kit-b gate U9 r4: a portrait phone showed a lone tile with a "!" and no word; Pitch 2 03 B: the
								-- "Tap me!" tag gave way to the quest strip) the folded guide shows the step's title and a + block
								-- (>= 44 px) that opens the card, or the portrait chip alone (>= 44 px) where the strip has no room
								local plus = strip and strip:FindFirstChild("QuestOpen")
								local qt = strip and strip:FindFirstChild("QuestTitle")
								local ok = (part == strip and qt ~= nil and U8.shown(qt) and qt.Text ~= "" and plus ~= nil and U8.shown(plus) and plus.AbsoluteSize.X >= 44 - 0.5
									and plus.AbsoluteSize.Y >= 44 - 0.5) or (part ~= strip and part.AbsoluteSize.X >= 44 - 0.5 and part.AbsoluteSize.Y >= 44 - 0.5)
								T.check(ok, what .. ": the folded guide shows its step and a + to open it (or the portrait chip alone)", part and part.Name or "-")
							end
							if part ~= root then
								local top = U99.overTopRight(gui, r)
								T.check(#top == 0, what .. ": the folded guide and its badge clear of the top-right token pill and gift", table.concat(top, "; ") .. " | " .. U8.show(r))
								-- (U9-9 look 2) the folded guide every phone player sees on whole px: the portrait's frame, sky and
								-- ground, (Pitch 2 03 B) the quest strip, its + block and its step cells, all four edges
								local grid = U99.offGrid(part, {})
								if part == strip then
									for _, g in ipairs(U99.offGrid(root:FindFirstChild("Portrait", true), {})) do
										grid[#grid + 1] = g
									end
								end
								T.check(#grid == 0, what .. ": the folded guide's blocks on whole screen px (all four edges)", table.concat(grid, "; "))
							end
							local out, small = U99.texts(part, r)
							T.check(#out == 0 and #small == 0, what .. ": its words inside it, >= 14 px", table.concat(out, "; ") .. " " .. table.concat(small, ", "))
							if part == root then
								-- (U9-9 look) the name never cut ("NIMB..."): TextScaled under a size floor of 14 screen px; the
								-- objective wraps to a second line instead of "Tap the glowing Pet..."
								local name, hint = root:FindFirstChild("GuideName", true), root:FindFirstChild("Hint", true)
								local fit = name and name:FindFirstChildOfClass("UITextSizeConstraint")
								T.check(name and name.TextScaled and fit and fit.MinTextSize * U8.scaleOf(name) >= 14 - 0.01, what .. ": the name fits by the engine's own measure, >= 14 px",
									fit and fmt("min %d at %.2f", fit.MinTextSize, U8.scaleOf(name)) or "no size floor")
								T.check(not (hint and U8.shown(hint)) or (hint.TextWrapped and hint.TextTruncate == Enum.TextTruncate.None), what .. ": the objective wraps, never cut")
								-- (U9-9 look) its blocks, lips, icons and wood edges on whole screen px at the card's scale; (U9-9 look 2) all
								-- four edges of every block with a face or a wood edge (the card, the stone in its frame, the portrait's
								-- frame, sky and ground, the name plank, the tags, the well, the planks, the skip line)
								local grid = U99.offGrid(root, { Progress = true, Block1 = true })
								T.check(#grid == 0, what .. ": the card's blocks, lips, icons and wood edges on whole screen px (all four edges)", table.concat(grid, "; "))
								-- (U9-9 look) the opened card over a part of the vitals card: the vitals step aside (as for the
								-- result card and the Trove)
								local hud = U7.client("Controllers/HudController")
								local layout = hud and hud.GetLayout and hud.GetLayout()
								local slot = layout and layout.VitalsSlot
								if slot then
									local c = U8.rect(root)
									local over = math.min(c.R, slot.X + slot.W) - math.max(c.X, slot.X) > 4 and math.min(c.B, slot.Y + slot.H) - math.max(c.Y, slot.Y) > 4
									T.check(not over or layout.Vitals == nil, what .. ": the vitals card steps aside while the card lies over it",
										fmt("card %s, vitals %d,%d %dx%d shown %s", U8.show(c), slot.X, slot.Y, slot.W, slot.H, tostring(layout.Vitals ~= nil)))
								end
							end
						end
					end
				end
				U99.tutorialOff()
				local hud = U7.client("Controllers/HudController")
				local after = hud and hud.GetLayout and hud.GetLayout()
				T.check(not (after and after.VitalsSlot) or after.Vitals ~= nil, tag .. ": the vitals card is back once the tutorial goes")
			end)
		end
		LKC.flushErrors("tutorial_fits_phone")
	end)

	-- (Pitch 2 item 03_tutorial_dock, option B "Quest strip"; the owner's shot 03: folded, the guide was a lone sky tile with
	-- a "!" and a navy "Tap me!" tag, no step and no title) at the four grid sizes, step 3 folded: one stone strip holds
	-- Nimbus' portrait chip, the step's title (23 px on PC, >= 18 on a phone), "3/21", the steps as chapter blocks of 3
	-- cells (2 done, 1 current, the rest open) and a "+" block >= 44 screen px that opens the card. PC and a landscape
	-- phone: top-left under the top bar, clear of the menu column; a portrait phone: on the HUD stack, at the vitals card's
	-- left edge, 10 px over it (the spec's 29, 534-596, 317 x 62 at 390 x 844). Clear of the menu column, the wallet, the
	-- gift, the thumb zones and RUN / DASH. Meeting the arena's side stack, the strip folds to the portrait chip (>= 44 px)
	S.tutorial_dock_b = guarded("tutorial_dock_b", function()
		local function inside(a, b)
			return a.X >= b.X - 0.5 and a.R <= b.R + 0.5 and a.Y >= b.Y - 0.5 and a.B <= b.B + 0.5
		end
		local function over4(a, b)
			return math.min(a.R, b.R) - math.max(a.X, b.X) > 4 and math.min(a.B, b.B) - math.max(a.Y, b.Y) > 4
		end
		local payload = U99.tutorialPayload(3)
		local total = payload.Total
		for _, s in ipairs(U8.SIZES) do
			local run = s[3] and U99.atPhone or function(w, h, label, fn)
				U8.at(w, h, false, label, fn)
			end
			run(s[1], s[2], "tutorial dock", function(tag)
				local gui, root = U99.tutorial(3, false)
				local main = root and root:FindFirstChild("Main", true)
				local fold = root and root:FindFirstChild("Fold", true)
				if main and U8.shown(main) and fold then
					Mock.Click(fold)
					LKC.advance(1)
				end
				local strip = root and root:FindFirstChild("QuestStrip", true)
				if not T.check(strip ~= nil and U8.shown(strip) and not U8.shown(main), tag .. ": folded, the guide is the quest strip") then
					U99.tutorialOff()
					return
				end
				local sr = U8.rect(strip)
				local k = U8.scaleOf(strip)
				for _, gone in ipairs({ "Badge", "TapTag" }) do
					local o = root:FindFirstChild(gone, true)
					T.check(o == nil or not U8.shown(o), tag .. ": no " .. gone .. " on the folded guide")
				end
				-- its parts: the portrait chip at the left end, the title and its count, the steps, the "+" block
				local portrait = root:FindFirstChild("Portrait", true)
				local title, count = strip:FindFirstChild("QuestTitle"), strip:FindFirstChild("QuestCount")
				local steps, open = strip:FindFirstChild("QuestSteps"), strip:FindFirstChild("QuestOpen")
				local pr = portrait and U8.rect(portrait)
				T.check(pr ~= nil and U8.shown(portrait) and inside(pr, sr) and pr.X - sr.X <= 12 * k + 1, tag .. ": Nimbus' portrait chip at the strip's left end",
					(pr and U8.show(pr) or "-") .. " in " .. U8.show(sr))
				local titlePx = title and title.TextSize * U8.scaleOf(title) or 0
				local want = s[3] and 18 or (s[2] >= 1080 and 23 or 18)
				T.check(title ~= nil and U8.shown(title) and title.Text == payload.Title and inside(U8.rect(title), sr) and titlePx >= want - 0.5,
					tag .. ": the step's title in the strip, >= " .. want .. " px", fmt("'%s' %.1f px", title and title.Text or "-", titlePx))
				T.check(count ~= nil and U8.shown(count) and count.Text == "3/" .. total and inside(U8.rect(count), sr) and not U8.overlap(U8.rect(count), U8.rect(title)),
					tag .. ": its count 3/" .. total .. " beside the title", count and count.Text or "-")
				local cells, chapters, states = 0, 0, { Done = 0, Current = 0, Open = 0 }
				for _, d in ipairs(steps and steps:GetDescendants() or {}) do
					if d:GetAttribute("Step") and U8.shown(d) then
						cells = cells + 1
						local st = d:GetAttribute("State")
						states[st] = (states[st] or 0) + 1
					elseif d.Name:match("^Chapter%d+$") then
						chapters = chapters + 1
					end
				end
				T.check(steps ~= nil and inside(U8.rect(steps), sr) and cells == total and chapters == math.ceil(total / 3) and states.Done == 2 and states.Current == 1
					and states.Open == total - 3, tag .. ": the steps: one cell a step in chapter blocks of 3, 2 done, 1 current",
					fmt("%d cells, %d chapters, %d done %d current %d open", cells, chapters, states.Done, states.Current, states.Open))
				local orr = open and U8.rect(open)
				T.check(orr ~= nil and U8.shown(open) and inside(orr, sr) and orr.R - orr.X >= 44 - 0.5 and orr.B - orr.Y >= 44 - 0.5 and not U8.overlap(orr, U8.rect(count))
					and not U8.overlap(orr, U8.rect(steps)), tag .. ": the + block, >= 44 screen px, at the strip's right end", orr and U8.show(orr) or "-")
				-- where spec 03 B puts it
				local pg = U8.pg()
				local hud = pg:FindFirstChild("NimbusHud")
				-- (the strip's rects are in its gui's area, under Roblox's top bar; the spec measures the screen)
				local inset = gui.IgnoreGuiInset and 0 or game:GetService("GuiService"):GetGuiInset().Y
				local menuGui = pg:FindFirstChild("NimbusMenu")
				local column = menuGui and menuGui:FindFirstChild("MenuColumn", true)
				local cr = column and U8.shown(column) and U8.rect(column)
				if s[2] > s[1] then
					local vitals = hud and hud:FindFirstChild("BottomLeft") and hud.BottomLeft:FindFirstChild("Vitals")
					local vr = vitals and U8.shown(vitals) and U8.rect(vitals)
					T.check(vr and math.abs(sr.X - vr.X) <= 1 and math.abs(sr.B - (vr.Y - 10)) <= 1, tag .. ": on the HUD stack, at the vitals card's left edge, 10 px over it",
						U8.show(sr) .. " / vitals " .. (vr and U8.show(vr) or "-"))
					-- (P2 fix A: the test was stale, the dock is right) spec 03 B's rule: Vitals-wide from the card's left edge to the RUN /
					-- DASH column's right edge, 62 tall, 10 px over the vitals card. Its numbers (29, 534-596, 317 x 62) were measured
					-- over the pitch's base render, the vitals card before 08 C (29,606 240 x 80); 08 C (same wave) gave the card its
					-- name tab (32 design px over its top) and moved it to x 20 at 390 x 844, so the same rule now lands at 20,513-574,
					-- 322 x 61 (screen px). The rule is checked, not the old numbers
					local mc = pg:FindFirstChild("MobileControls")
					local run = mc and mc:FindFirstChild("RunButton", true)
					local rr = run and U8.shown(run) and U8.rect(run)
					local gi = game:GetService("GuiService"):GetGuiInset().Y
					local rdy = (mc and mc.IgnoreGuiInset and -gi or 0) - (gui.IgnoreGuiInset and -gi or 0)
					T.check(rr and math.abs(sr.R - rr.R) <= 1 and math.abs((sr.B - sr.Y) - 62) <= 2 and sr.B <= rr.Y + rdy - 8,
						tag .. ": spec 03 B's dock: from the vitals card's left edge to RUN's right edge, 62 tall, above RUN",
						U8.show(sr) .. fmt(" + %d inset", inset) .. " / RUN " .. (rr and U8.show(rr) or "-"))
				else
					-- (the card's edge margin under the top bar: 12 px, 20 on touch)
					T.check(sr.Y >= -0.5 and sr.Y <= (s[3] and 20 or 12) + 1 and (cr == nil or not over4(sr, cr)) and (cr ~= nil or sr.X <= 12 * k + 1),
						tag .. ": top-left under the top bar, clear of the menu column", U8.show(sr) .. " / column " .. (cr and U8.show(cr) or "-"))
				end
				-- clear of the HUD round it
				local hits = {}
				if cr and over4(sr, cr) then
					hits[#hits + 1] = "menu column " .. U8.show(cr)
				end
				for _, h in ipairs(U99.overTopRight(gui, sr)) do
					hits[#hits + 1] = h
				end
				local strips = hud and hud:FindFirstChild("Currency", true)
				if strips and U8.shown(strips) and over4(sr, U8.rect(strips)) then
					hits[#hits + 1] = "wallet " .. U8.show(U8.rect(strips))
				end
				if s[3] then
					for _, h in ipairs(U99.overTouch(gui, sr, s[2] > s[1])) do
						hits[#hits + 1] = h
					end
				end
				T.check(#hits == 0, tag .. ": clear of the menu column, the wallet, the gift, the thumb zones and RUN / DASH", table.concat(hits, "; ") .. " | " .. U8.show(sr))
				-- the + opens the card; folded again after
				Mock.Click(open)
				LKC.advance(1)
				T.check(main ~= nil and U8.shown(main) and not U8.shown(strip), tag .. ": the + block opens the card")
				if fold and U8.shown(main) then
					Mock.Click(fold)
					LKC.advance(1)
				end
				-- (the spec's caveat) the arena's side stack meeting the strip folds it to the portrait chip
				if s[2] > s[1] then
					-- (ArenaController's own NimbusArenaSide.SideStack where it lives, bottom-right 12 px in, grown upward by its
					-- cards: the mock does not run AutomaticSize, so it is given the height of a tall stack; then put back)
					local sideGui = pg:FindFirstChild("NimbusArenaSide")
					local stack = sideGui and sideGui:FindFirstChild("SideStack")
					if T.check(stack ~= nil, tag .. ": ArenaController's side stack exists") then
						local was = { stack.Size, stack.Visible, sideGui.Enabled }
						sideGui.Enabled = true
						stack.Visible = true
						stack.Size = UDim2.fromOffset(stack.Size.X.Offset, 400)
						local card = Instance.new("Frame")
						card.Name = "SmokeInvite"
						card.Visible = true
						card.Size = UDim2.new(1, 0, 0, 400)
						card.Parent = stack
						LKC.advance(1.2)
						local chip = root:FindFirstChild("Portrait", true)
						local chr = chip and U8.rect(chip)
						local str = U8.rect(stack)
						T.check(not U8.shown(strip) and chip ~= nil and U8.shown(chip) and chr.R - chr.X >= 44 - 0.5 and chr.B - chr.Y >= 44 - 0.5 and not U8.overlap(chr, str),
							tag .. ": meeting the arena's side stack, the strip folds to the portrait chip (>= 44 px, clear of the stack)",
							(chr and U8.show(chr) or "-") .. " / stack " .. U8.show(str) .. fmt(" | strip shown %s", tostring(U8.shown(strip))))
						card:Destroy()
						stack.Size, stack.Visible, sideGui.Enabled = was[1], was[2], was[3]
						LKC.advance(1.2)
					end
					T.check(U8.shown(strip), tag .. ": the strip is back when the side stack goes")
				end
				U99.tutorialOff()
			end)
		end
		LKC.flushErrors("tutorial_dock_b")
	end)

	-- the menu pointer (step 5, a menu target) on a PC and the phones: (U9-9 look 2) the pointed tile wears the kit's Selected
	-- look itself (the gold face and its lip, MenuController.SetPointed) and nothing of the pointer lies over another menu
	-- tile (a ring round the tile covered the next one: "ndex"); the tile's own look back once the step goes. The pixel
	-- arrow gold with a brown outline (no navy) on the screen's icon pixel (its 2 px cells: one pixel size), its box on
	-- whole px
	S.tutorial_pointer_kitb = guarded("tutorial_pointer_kitb", function()
		local Theme = LoadingH.shared("Theme")
		local Sign = Theme.Sign
		local KIT = { Sign.Text, Sign.GoldLight, Sign.Gold, Sign.GoldLip, Sign.Stone }
		for _, s in ipairs({ { 1920, 1080, false }, { 1280, 720, false }, { 844, 390, true }, { 640, 360, true }, { 390, 844, true } }) do
			U8.at(s[1], s[2], s[3], "tutorial pointer", function(tag)
				U99.tutorial(5, false)
				local pg = U99.gui("NimbusTutorialPointer")
				local arrow = pg and pg:FindFirstChild("Arrow")
				local menu = U99.gui("NimbusMenu")
				local tile = menu and menu:FindFirstChild("MenuButton_Pets", true)
				local lip = tile and tile:FindFirstChild("Lip")
				T.check(tile and U8.shown(tile) and sameColor(tile.BackgroundColor3, Sign.Gold) and lip and sameColor(lip.BackgroundColor3, Sign.GoldLip),
					tag .. ": the pointed Pets tile wears the Selected look (the gold face, its gold lip)", tile and hex(tile.BackgroundColor3) or "no tile")
				T.check(pg and pg:FindFirstChild("Ring", true) == nil and pg:FindFirstChild("Glow", true) == nil, tag .. ": no ring and no glow round the tile")
				-- nothing the pointer draws lies over another shown menu tile (with its wood edge)
				local over = {}
				for _, d in ipairs(menu and menu:GetDescendants() or {}) do
					if d:IsA("GuiObject") and d.Name:match("^MenuButton_") and d ~= tile and U8.shown(d) then
						local e = d:FindFirstChild("SignEdge")
						local t = (e and e.Thickness or 0) * U8.scaleOf(d)
						local b = U8.rect(d)
						b = { X = b.X - t, R = b.R + t, Y = b.Y - t, B = b.B + t }
						for _, p in ipairs(pg and pg:GetChildren() or {}) do
							if p:IsA("GuiObject") and U8.shown(p) and U8.overlap(U8.rect(p), b) then
								over[#over + 1] = p.Name .. " over " .. d.Name
							end
						end
					end
				end
				T.check(#over == 0, tag .. ": the pointer lies over no other menu tile", table.concat(over, "; "))
				if arrow and U8.shown(arrow) then
					local scale = arrow:FindFirstChildOfClass("UIScale")
					local k = Theme.ScreenFactor()
					local want = math.max(2, math.floor(2 * k + 0.5)) / 2
					T.check(scale and math.abs(scale.Scale - want) < 1e-6, tag .. fmt(": the arrow's scale %.3f = max(2, round(2k)) / 2 (k %.2f): its 2 px cells are the icon pixel", scale and scale.Scale or -1, k))
					local cells = {}
					for _, px in ipairs(arrow:GetChildren()) do
						if px:IsA("Frame") then
							cells[fmt("%.2f", px.AbsoluteSize.Y)] = true
						end
					end
					local one = math.max(2, math.floor(2 * k + 0.5)) -- the screen's icon pixel (PixelCrisp.Px of a 2 px cell)
					local odd = {}
					for c in pairs(cells) do
						if math.abs(tonumber(c) - one) > 0.01 then
							odd[#odd + 1] = c
						end
					end
					T.check(#odd == 0, tag .. ": one pixel size: the arrow's rows are the icons' " .. one .. " px cell", table.concat(odd, ", "))
					local odd = {}
					for _, px in ipairs(arrow:GetChildren()) do
						if px:IsA("Frame") then
							local ok = false
							for _, c in ipairs(KIT) do
								ok = ok or sameColor(px.BackgroundColor3, c)
							end
							if not ok then
								odd[#odd + 1] = px.Name .. " " .. hex(px.BackgroundColor3)
							end
						end
					end
					T.check(#odd == 0, tag .. ": the arrow is gold with a brown outline (kit colours only)", table.concat(odd, ", ", 1, math.min(#odd, 6)))
					local a = U8.rect(arrow)
					T.check(math.abs(a.X - math.floor(a.X + 0.5)) < 0.01 and math.abs(a.Y - math.floor(a.Y + 0.5)) < 0.01, tag .. ": the arrow's box starts on a whole screen px", fmt("%.2f, %.2f", a.X, a.Y))
				else
					T.info("*" .. tag .. ": no free side for the arrow, the gold tile alone marks the button")
				end
				U99.tutorialOff()
				LKC.advance(1.2)
				T.check(tile and not sameColor(tile.BackgroundColor3, Sign.Gold), tag .. ": the tile's own look back once the step goes", tile and hex(tile.BackgroundColor3) or "")
			end)
		end
		LKC.flushErrors("tutorial_pointer_kitb")
	end)

	-- the NPC dialog on the Signboard kit (1920x1080): the wood frame round the stone body and its lip; the name a plain
	-- Section title in gold on a navy plank; the portrait a sky well in its wood edge; the line's well a pale tile in a wood
	-- edge; the page dots square blocks (the current one gold); Next the one green plank, Close a stone plank (not red);
	-- nothing round or glossy, every edge mitred, one pixel size, every text reads
	S.npc_signboard_skin = guarded("npc_signboard_skin", function()
		local Sign = LoadingH.shared("Theme").Sign
		U8.at(1920, 1080, false, "npc skin", function(tag)
			local root = U99.npc(1)
			if not T.check(root ~= nil and U8.shown(root), tag .. ": the NPC dialog opens") then
				U99.npcGone()
				return
			end
			local card = root:FindFirstChild("Card", true)
			local stone = card and card:FindFirstChild("Stone")
			T.check(card and sameColor(card.BackgroundColor3, Sign.Wood) and stone and sameColor(stone.BackgroundColor3, Sign.Stone) and stone:FindFirstChild("Lip") ~= nil,
				tag .. ": the wood frame round the stone body and its lip")
			local tab = root:FindFirstChild("NameTab", true)
			local name = tab and tab:FindFirstChild("Name")
			T.check(tab and sameColor(tab.BackgroundColor3, Sign.Navy) and name and name:GetAttribute("TitleLook") == "Section" and sameColor(name.TextColor3, Sign.Gold),
				tag .. ": the name a plain Section title in gold on a navy plank")
			local portrait = root:FindFirstChild("Portrait", true)
			T.check(portrait and sameColor(portrait.BackgroundColor3, Sign.Sky) and portrait:FindFirstChild("SignEdge") ~= nil, tag .. ": the portrait is a sky well in its wood edge")
			local well = root:FindFirstChild("Well", true)
			T.check(well and sameColor(well.BackgroundColor3, Sign.Tile) and well:FindFirstChild("SignEdge") ~= nil, tag .. ": the line's well is a pale tile in a wood edge")
			local dots, current = 0, 0
			for _, d in ipairs(root:GetDescendants()) do
				if d.Name:match("^Dot%d+$") and U8.shown(d) then
					dots = dots + 1
					if d:GetAttribute("Current") == true and sameColor(d.BackgroundColor3, Sign.Gold) then
						current = current + 1
					end
				end
			end
			T.check(dots == 0 or current == 1, tag .. ": the page dots are blocks, the current one gold", dots .. " dots, " .. current .. " gold")
			local nextB, closeB = root:FindFirstChild("Button_Next", true), root:FindFirstChild("Button_Close", true)
			T.check(nextB and nextB:GetAttribute("Skin") == "Sign" and U8.green(U8.faceOf(nextB)), tag .. ": Next is the green plank")
			T.check(closeB and closeB:GetAttribute("Skin") == "Sign" and closeB:GetAttribute("SignLook") == "Stone", tag .. ": Close is a stone plank (the dialog's one action is Next)",
				closeB and tostring(closeB:GetAttribute("SignLook")) or "none")
			T.check(#U94.roundOrGloss(root) == 0, tag .. ": nothing round or glossy", table.concat(U94.roundOrGloss(root), ", "))
			T.check(#U99.roundEdges(root) == 0, tag .. ": every wood edge is mitred", table.concat(U99.roundEdges(root), ", "))
			local cells, odd = U99.pixelCells(root, { U99.cell(card) })
			T.check(#odd == 0, tag .. ": one pixel size: the dialog's icons on " .. U99.cell(card) .. " px cells", table.concat(odd, "; ") .. " | " .. table.concat(cells, ", "))
			local low = U94.contrast("NimbusNpcDialog")
			T.check(#low == 0, tag .. ": every text reads on its fill", table.concat(low, "; "))
			U99.npcClose()
			U99.npcGone()
		end)
		LKC.flushErrors("npc_signboard_skin")
	end)

	-- the game's top-bar pill (TopBarController's navy plank with its gold-lip edge round the Shop / Travel / Settings buttons,
	-- display order 21: it draws over every dialog) and its buttons, as rects in the space of `gui`
	function U99.topBar(gui)
		local out = {}
		local bar = U99.gui("NimbusTopBar")
		if not (bar and bar.Enabled) then
			return out
		end
		local inset = Mock.TopInset or 0
		local dy = (bar.IgnoreGuiInset and 0 or inset) - (gui.IgnoreGuiInset and 0 or inset)
		for _, d in ipairs(bar:GetDescendants()) do
			if d:IsA("GuiObject") and (d.Name == "Pill" or (d:IsA("GuiButton") and d.Name:match("^PillButton_"))) and U8.shown(d) and d.AbsoluteSize.X > 0 then
				local r = U8.rect(d)
				local stroke = d:FindFirstChildOfClass("UIStroke")
				local s = stroke and stroke.Thickness or 0
				out[#out + 1] = { Name = d.Name, X = r.X - s, R = r.R + s, Y = r.Y + dy - s, B = r.B + dy + s }
			end
		end
		return out
	end

	-- the NPC dialog on the phones (U99.PHONES, with the game's real RUN / DASH): the card inside the screen, the name plank
	-- inside it too or, on a 360 px tall phone where the card cannot fit under the top bar, in Roblox's top band but clear of
	-- the top bar's pill and its buttons (U9-9 review: the pill draws over the plank), over no thumb zone and no RUN / DASH,
	-- its words, Next and Close inside it, every text >= 14 px
	S.npc_fits_phone = guarded("npc_fits_phone", function()
		-- on every size the line keeps at least the old bubble's room above the page dots (design px from the line's top to
		-- the dots: 94 on the full card, 128 on the compact one): the stone well's frame, lip and footer must not eat it
		-- (the mock's text measure runs wide, so the room is checked, not the wrapped text); the short phones take the short
		-- card (U9-9 review), which keeps it too
		local sizes = { { 1920, 1080, false }, { 1280, 720, false } }
		for _, s in ipairs(U99.PHONES) do
			sizes[#sizes + 1] = { s[1], s[2], true }
		end
		for _, s in ipairs(sizes) do
			local at = s[3] and function(w, h, _, label, fn)
				U99.atPhone(w, h, label, fn)
			end or U8.at
			at(s[1], s[2], s[3], "npc line", function(tag)
				local root = U99.npc(1)
				local line, dots = root and root:FindFirstChild("Line", true), root and root:FindFirstChild("Dots", true)
				if T.check(line ~= nil and dots ~= nil, tag .. ": the dialog's line and page dots") then
					local room = (dots.AbsolutePosition.Y - line.AbsolutePosition.Y) / math.max(0.01, U8.scaleOf(line))
					local want = root.Size.X.Offset < 480 and 128 or 94
					T.check(room >= want - 0.5, tag .. fmt(": the line keeps %d design px above the page dots (%.1f)", want, room))
				end
				-- (U9-9 review) a 360 px tall phone takes the short card (the old 216 / 250 and a lower name plank), a PC the tall one
				local rows = root and root:GetAttribute("Rows")
				if s[2] <= 360 then
					T.check(rows == "Short", tag .. ": the short card on a 360 px tall phone", tostring(rows))
				elseif not s[3] then
					T.check(rows == "Tall", tag .. ": the tall card on a PC", tostring(rows))
				end
				U99.npcClose()
				U99.npcGone()
			end)
		end
		for _, s in ipairs(U99.PHONES) do
			U99.atPhone(s[1], s[2], "npc phone", function(tag)
				local root = U99.npc(1)
				if T.check(root ~= nil and U8.shown(root), tag .. ": the NPC dialog opens") then
					local gui = root:FindFirstAncestorWhichIsA("LayerCollector")
					local card = U8.rect(root)
					T.check(card.X >= -0.5 and card.Y >= -0.5 and card.R <= gui.AbsoluteSize.X + 0.5 and card.B <= gui.AbsoluteSize.Y + 0.5, tag .. ": the card inside the screen", U8.show(card))
					local r = card
					local tab = root:FindFirstChild("NameTab", true)
					if T.check(tab ~= nil and U8.shown(tab), tag .. ": the name plank shows") then
						local t = U8.rect(tab)
						local edge = tab:FindFirstChildOfClass("UIStroke")
						local e = (edge and edge.Thickness or 0) * U8.scaleOf(tab)
						local plank = { X = t.X - e, R = t.R + e, Y = t.Y - e, B = t.B + e }
						local bar = {}
						for _, b in ipairs(U99.topBar(gui)) do
							if U8.overlap(plank, b) then
								bar[#bar + 1] = b.Name .. " " .. U8.show(b)
							end
						end
						T.check(#bar == 0, tag .. ": the name plank and its edge clear of the top bar's pill and its buttons", table.concat(bar, "; ") .. " | plank " .. fmt("%.1f,%.1f..%.1f,%.1f", plank.X, plank.Y, plank.R, plank.B))
						local inset = gui.IgnoreGuiInset and 0 or (Mock.TopInset or 0)
						T.check(plank.Y >= -0.5 or (s[2] <= 360 and plank.Y + inset >= -0.5), tag .. ": the name plank inside the screen's gui area (a 360 px tall phone: inside the screen)",
							U8.show(plank))
						r = { X = math.min(r.X, t.X), Y = math.min(r.Y, t.Y), R = math.max(r.R, t.R), B = math.max(r.B, t.B) }
					end
					local hits = U99.overTouch(gui, r, s[2] > s[1])
					T.check(#hits == 0, tag .. ": over no thumb zone and no RUN / DASH", table.concat(hits, "; ") .. " | " .. U8.show(r))
					local out, small = U99.texts(root, r)
					T.check(#out == 0 and #small == 0, tag .. ": its words inside it, >= 14 px", table.concat(out, "; ") .. " " .. table.concat(small, ", "))
				end
				U99.npcClose()
				U99.npcGone()
			end)
		end
		-- (U9-9 look) a small PC window (640 x 360: the pill drew over the name plank's words) and a 720p one: the plank and its
		-- gold edge clear of the top bar's pill, the HUD's vitals card stepped aside while the card lies over it (back once it
		-- closes), and the card's blocks, lips, icons and wood edges on whole screen px
		for _, s in ipairs({ { 640, 360 }, { 1280, 720 }, { 1920, 1080 } }) do
			U8.at(s[1], s[2], false, "npc window", function(tag)
				local root = U99.npc(1)
				if T.check(root ~= nil and U8.shown(root), tag .. ": the NPC dialog opens") then
					local gui = root:FindFirstAncestorWhichIsA("LayerCollector")
					local tab = root:FindFirstChild("NameTab", true)
					if tab then
						local t = U8.rect(tab)
						local edge = tab:FindFirstChildOfClass("UIStroke")
						local e = (edge and edge.Thickness or 0) * U8.scaleOf(tab)
						local plank = { X = t.X - e, R = t.R + e, Y = t.Y - e, B = t.B + e }
						local bar = {}
						for _, b in ipairs(U99.topBar(gui)) do
							if U8.overlap(plank, b) then
								bar[#bar + 1] = b.Name .. " " .. U8.show(b)
							end
						end
						T.check(#bar == 0, tag .. ": the name plank and its edge clear of the top bar's pill", table.concat(bar, "; ") .. " | plank " .. U8.show(plank))
					end
					local hud = U7.client("Controllers/HudController")
					local layout = hud and hud.GetLayout and hud.GetLayout()
					local slot = layout and layout.VitalsSlot
					if slot then
						local c = U8.rect(root)
						local over = math.min(c.R, slot.X + slot.W) - math.max(c.X, slot.X) > 4 and math.min(c.B, slot.Y + slot.H) - math.max(c.Y, slot.Y) > 4
						T.check(not over or layout.Vitals == nil, tag .. ": the vitals card steps aside while the card lies over it",
							fmt("card %s, vitals %d,%d %dx%d shown %s", U8.show(c), slot.X, slot.Y, slot.W, slot.H, tostring(layout.Vitals ~= nil)))
					end
					local grid = U99.offGrid(root, { NameTab = true, Portrait = true, TitlePill = true, Tail = true, NpcDialog = true })
					T.check(#grid == 0, tag .. ": the card's blocks, lips, icons and wood edges on whole screen px (all four edges)", table.concat(grid, "; "))
					-- (U9-9 look 2) the line's well and the buttons under it apart: at least 4 screen px between their wood edges
					-- (the 640 x 360 card's 13 px design gap drew 0.7 px)
					local well = root:FindFirstChild("Well", true)
					local tight = {}
					for _, n in ipairs({ "Button_Next", "Button_Close" }) do
						local b = root:FindFirstChild(n, true)
						if well and b and U8.shown(b) then
							local we, be = well:FindFirstChild("SignEdge"), b:FindFirstChild("SignEdge")
							local gap = (U8.rect(b).Y - (be and be.Thickness or 0) * U8.scaleOf(b)) - (U8.rect(well).B + (we and we.Thickness or 0) * U8.scaleOf(well))
							if U8.rect(b).X < U8.rect(well).R and gap < 4 - 0.01 then
								tight[#tight + 1] = fmt("%s %.1f px", n, gap)
							end
						end
					end
					T.check(#tight == 0, tag .. ": the buttons at least 4 px under the line's well (edges counted)", table.concat(tight, "; "))
					if s[1] == 1280 then
						-- (U9-9 look 2) a 720p window docks the card in the low-left corner, clear of the vitals card (lifted, the
						-- menu rail pushed it 2 px from the vitals' corner, floating mid-left)
						local c = U8.rect(root)
						local clearV = not slot or c.R + 8 <= slot.X + 0.5 or c.B + 8 <= slot.Y + 0.5
						T.check(gui.AbsoluteSize.Y - c.B <= 40 and clearV, tag .. ": the card docks low-left, at least 8 px clear of the vitals card",
							U8.show(c) .. (slot and fmt(" | vitals %d,%d %dx%d", slot.X, slot.Y, slot.W, slot.H) or ""))
					end
				end
				U99.npcClose()
				U99.npcGone()
				local hud = U7.client("Controllers/HudController")
				local after = hud and hud.GetLayout and hud.GetLayout()
				T.check(not (after and after.VitalsSlot) or after.Vitals ~= nil, tag .. ": the vitals card is back once the dialog closes")
			end)
		end
		-- (U9-9 look 2) every NPC's name on its plank on the narrow cards (a 640 x 360 window, a portrait phone): each word
		-- whole at the plank's 20 px floor, a name too long for one line on two (the plank grows a row), never cut or
		-- squeezed under 20 px; and the compact card's left column (the portrait, its title tag and Close) on the portrait's
		-- line, Close and Next on one bottom line
		local ND = LoadingH.shared("NpcDialog")
		local Theme = LoadingH.shared("Theme")
		for _, s in ipairs({ { 640, 360, false }, { 390, 844, true } }) do
			local at = s[3] and function(w, h, _, label, fn)
				U99.atPhone(w, h, label, fn)
			end or U8.at
			at(s[1], s[2], s[3], "npc names", function(tag)
				for i = 1, #ND.Npcs do
					local root = U99.npc(i)
					local tab = root and root:FindFirstChild("NameTab", true)
					local name = tab and tab:FindFirstChild("Name")
					if T.check(name ~= nil and U8.shown(name), tag .. ": NPC " .. i .. "'s name plank shows") then
						local k = U8.scaleOf(name)
						local nr = U8.rect(name)
						local longest, words = 0, 0
						for word in tostring(name.Text):gmatch("%S+") do
							words = words + 1
							local okM, m = pcall(Theme.Measure, word, "Title", 20)
							longest = math.max(longest, (okM and typeof(m) == "Vector2") and m.X or 0)
						end
						local okW, whole = pcall(Theme.Measure, name.Text, "Title", 20)
						local oneLine = okW and typeof(whole) == "Vector2" and whole.X * k <= (nr.R - nr.X) + 0.5
						local lines = oneLine and 1 or 2
						T.check(longest * k <= (nr.R - nr.X) + 0.5 and (nr.B - nr.Y) >= lines * 20 * k * 0.9 - 0.5 and (lines == 1 or (words >= 2 and name.TextWrapped)),
							tag .. ": " .. name.Text .. " whole on its plank at 20 px or more (" .. lines .. " line" .. (lines == 1 and "" or "s") .. ")",
							fmt("words %.0f px, box %.1f x %.1f, k %.2f", longest * k, nr.R - nr.X, nr.B - nr.Y, k))
						if root:GetAttribute("Compact") == true then
							local nextB, closeB = root:FindFirstChild("Button_Next", true), root:FindFirstChild("Button_Close", true)
							local portrait = root:FindFirstChild("Portrait", true)
							local ok = nextB and closeB and portrait and U8.shown(closeB)
								and math.abs(U8.rect(nextB).B - U8.rect(closeB).B) <= 0.5 and math.abs(U8.rect(closeB).X - U8.rect(portrait).X) <= 0.5
							T.check(ok, tag .. ": NPC " .. i .. " compact: Close under the portrait's column, on Next's bottom line",
								ok and "" or (nextB and closeB and portrait) and (U8.show(U8.rect(closeB)) .. " / " .. U8.show(U8.rect(nextB)) .. " / " .. U8.show(U8.rect(portrait))) or "missing")
						end
					end
					U99.npcClose()
				end
				U99.npcGone()
			end)
		end
		LKC.flushErrors("npc_fits_phone")
	end)

	-- the "press L" hint (PC): still the TextLabel "Hint" holding the whole line (smoke_bug2_tutset reads it), now a stone
	-- plank: the opaque tile face, a 2 px mitred wood edge, the stone lip flush along its bottom, brown words after the pixel
	-- mouse at the kit's 2 px cell, no corner, the words reading on the tile
	S.mouselock_hint_plank = guarded("mouselock_hint_plank", function()
		local Sign = LoadingH.shared("Theme").Sign
		U8.at(1920, 1080, false, "mouse hint", function(tag)
			local hint, restore = U99.mouseHint()
			if T.check(hint ~= nil and hint:IsA("TextLabel") and tostring(hint.Text):find("press L", 1, true) ~= nil and hint.TextSize >= 14, tag .. ": the hint shows 'press L'") then
				local edge, lip = hint:FindFirstChild("SignEdge"), hint:FindFirstChild("Lip")
				T.check(hint.BackgroundTransparency == 0 and sameColor(hint.BackgroundColor3, Sign.Tile) and hint:FindFirstChildOfClass("UICorner") == nil,
					tag .. ": an opaque tile face, square", hex(hint.BackgroundColor3) .. " " .. tostring(hint.BackgroundTransparency))
				T.check(edge and sameColor(edge.Color, Sign.Wood) and edge.Thickness == 2 and edge.LineJoinMode == Enum.LineJoinMode.Miter, tag .. ": a 2 px mitred wood edge")
				T.check(lip and sameColor(lip.BackgroundColor3, Sign.StoneLip) and #U94.floatingLips(hint.Parent) == 0, tag .. ": the stone lip flush along its bottom", table.concat(U94.floatingLips(hint.Parent), "; "))
				local mouse = hint:FindFirstChild("LeadIcon")
				T.check(sameColor(hint.TextColor3, Sign.Text) and mouse and mouse:GetAttribute("PixelIcon") == "mouse" and mouse.AbsoluteSize.Y == 18,
					tag .. ": brown words after the pixel mouse (2 px cells)", mouse and tostring(mouse.AbsoluteSize) or "no icon")
				local low = U94.contrast(hint.Parent.Name)
				T.check(#low == 0, tag .. ": the words read on the tile", table.concat(low, "; "))
				local r, gr = U8.rect(hint), hint.Parent.AbsoluteSize
				T.check(r.X >= 0 and r.R <= gr.X and r.Y >= 0.645 * gr.Y - 0.5 and r.B <= gr.Y, tag .. ": inside the screen, below the middle band", U8.show(r))
				-- (U9-9 look) the plank on whole screen px: its left edge, top and width whole (it sat at x 714.38, 491.24 wide)
				local grid = U99.offGrid(hint.Parent, { Hint = true })
				if math.abs(r.R - r.X - math.floor(r.R - r.X + 0.5)) > 0.02 then
					grid[#grid + 1] = "width " .. fmt("%.2f", r.R - r.X)
				end
				T.check(#grid == 0, tag .. ": the plank, its lip, the mouse and the wood edge on whole screen px", table.concat(grid, "; ") .. fmt(" | %.2f,%.2f %.2f wide", r.X, r.Y, r.R - r.X))
			end
			restore()
		end)
		-- (U9-9 look 2) short desktop windows: the plank (its wood edge counted) 8 px or more above the HUD's vitals card, or,
		-- where the middle band leaves no room above it (960 x 540: the card covered the plank's lower 9 px), docked beside
		-- the card on its top line, 8 px or more right of it; below the middle band and inside the screen either way
		for _, s in ipairs({ { 960, 540 }, { 1024, 576 }, { 1280, 600 }, { 1280, 720 } }) do
			U8.at(s[1], s[2], false, "mouse hint", function(tag)
				local hint, restore = U99.mouseHint()
				local hud = U99.gui("NimbusHud")
				local top, left, right = hud and hud:GetAttribute("BottomCentreTop"), hud and hud:GetAttribute("BottomCentreLeft"), hud and hud:GetAttribute("BottomCentreRight")
				-- (P2 fix A) since vitals C the slot's top (BottomCentreTop) is the name tab's top, TAB_UP over the card's own top
				-- edge (BottomCentreCardTop): docked beside the card the plank stands on the card's top line, not the tab's (at
				-- 960 x 540 the tab's top line, 310, lay 1 px into the middle band)
				local cardTop = hud and hud:GetAttribute("BottomCentreCardTop")
				if T.check(hint ~= nil and U8.shown(hint) and type(top) == "number" and type(right) == "number" and type(cardTop) == "number" and cardTop > top,
					tag .. ": the hint and the vitals card show (the card's top under its name tab published)", tostring(cardTop)) then
					local r, gr = U8.rect(hint), hint.Parent.AbsoluteSize
					local e = 2 * U8.scaleOf(hint)
					local p = { X = r.X - e, R = r.R + e, Y = r.Y - e, B = r.B + e }
					local above = p.B + 8 <= top + 0.5
					local beside = p.X >= right + 8 - 0.5 and math.abs(r.Y - cardTop) <= 1
					local v = { X = left or 0, R = right, Y = top, B = gr.Y }
					T.check((above or beside) and not U8.overlap(p, v), tag .. ": the plank 8 px or more above the vitals card, or beside it on its top line",
						fmt("plank %.1f,%.1f..%.1f,%.1f | vitals top %.1f, %.1f..%.1f | docked %s", p.X, p.Y, p.R, p.B, top, left or -1, right, tostring(hint.Parent:GetAttribute("Docked"))))
					T.check(r.Y >= 0.645 * gr.Y - 0.5 and p.X >= -0.5 and p.R <= gr.X + 0.5 and p.B <= gr.Y + 0.5, tag .. ": below the middle band, inside the screen", U8.show(r))
					local grid = U99.offGrid(hint.Parent, { Hint = true })
					T.check(#grid == 0, tag .. ": the plank on whole screen px", table.concat(grid, "; "))
				end
				restore()
			end)
		end
		LKC.flushErrors("mouselock_hint_plank")
	end)

	----------------------------------------------------------------------
	-- Pitch 2 item 10 A "Workshop machines" (spec docs/superpowers/specs/2026-11-20-pitch2-build-design.md, plan Task 7;
	-- branch kitb-p2-icons): each roulette its own pixel capsule machine, cut from ONE uploaded sheet
	-- (build/upload_sheets/machines_a.png) once Config.MachineSheet.Id is set; until then today's drawn machine
	----------------------------------------------------------------------
	local MACHINES = { "Cloud", "Storm", "Sky", "Celestial", "Secret" }
	-- a fresh Eggs page (ShopEggs.Build) laid out at `mode` in a ScreenGui; fn(P) gets each roulette's Machine root
	-- (P2 icons review r1) `scale`: the page under a window Fit of that scale (1280 x 720: 0.8); away: the player away from
	-- the Storm Altar on an unrestricted account (the hero's Dim / altar state)
	local function machinesPage(mode, box, fn, scale, away)
		local SE = U7.client("UI/ShopEggs")
		local lp = game:GetService("Players").LocalPlayer
		local gui = Instance.new("ScreenGui")
		gui.Name = "SmokeMachines"
		local page = Instance.new("Frame")
		page.Name = "Page_Eggs"
		page.Size = UDim2.fromOffset(box.W, box.H)
		if scale then
			local fit = Instance.new("UIScale")
			fit.Name = "Fit"
			fit.Scale = scale
			fit.Parent = page
		end
		page.Parent = gui
		gui.Parent = lp:FindFirstChildOfClass("PlayerGui")
		local old = { lp:GetAttribute("PaidRandomItemsRestricted"), SE._AtAltar }
		if away then
			lp:SetAttribute("PaidRandomItemsRestricted", false)
			SE._AtAltar = false
		end
		local ok, err = pcall(function()
			SE.Build(page, nil)
			SE.Layout(page, box, mode)
			SE.Refresh(page)
			LKC.advance(0.1)
			local roots = {}
			for _, id in ipairs(MACHINES) do
				local card = page:FindFirstChild("ShopCard_" .. id, true)
				roots[id] = card and card:FindFirstChild("Machine", true)
			end
			fn(roots)
		end)
		lp:SetAttribute("PaidRandomItemsRestricted", old[1])
		SE._AtAltar = old[2]
		gui:Destroy()
		LKC.advance(0.1)
		return ok, err
	end

	-- Review Focus 2 (missing upload ids): with Config.MachineSheet.Id 0 (shipping, nothing uploaded) every roulette keeps
	-- today's drawn machine (ShopEggs H.machine: the base, the dome, the glass), no image, no stage, no error
	S.machines_fallback = guarded("machines_fallback", function()
		local Config = LoadingH.shared("Config")
		local ms = Config and Config.MachineSheet
		T.check(type(ms) == "table" and ms.Id == 0, "machines: Config.MachineSheet.Id ships 0 (nothing uploaded)", tostring(type(ms) == "table" and ms.Id))
		T.check(type(ms) == "table" and type(ms.Cells) == "table", "machines: Config.MachineSheet.Cells gives each roulette's cell in the sheet")
		-- (P2 icons look fin1, tools/check.mjs asset-id) the sheets' image URLs are made in Config.Art (no asset literal in
		-- ShopEggs / PixelIcon): an uploaded id gives its URL, 0 / junk gives none (the fallback stays)
		local img = Config and Config.Art and Config.Art.Image
		T.check(type(img) == "function" and img(5151515151) == "rbxassetid://5151515151" and img(0) == nil and img(-3) == nil
			and img(1.5) == nil and img("x") == nil and img(nil) == nil,
			"machines: Config.Art.Image(id) is a sheet's asset URL for a whole id above 0, nil for 0 or junk",
			type(img) == "function" and tostring(img(5151515151)) or tostring(img))
		for _, m in ipairs({ { "PC", { W = 1240, H = 834 } }, { "Phone", { W = 790, H = 300 } } }) do
			local ok, err = machinesPage(m[1], m[2], function(roots)
				local wrong = {}
				for _, id in ipairs(MACHINES) do
					local root = roots[id]
					local imgs = 0
					for _, d in ipairs(root and root:GetDescendants() or {}) do
						if d:IsA("ImageLabel") then
							imgs = imgs + 1
						end
					end
					if not (root and root:FindFirstChild("Dome") and root:FindFirstChild("Glass") and root:FindFirstChild("Base") and imgs == 0
						and root:FindFirstChild("Stage") == nil and root:GetAttribute("Sheet") == nil) then
						wrong[#wrong + 1] = id
					end
				end
				T.check(#wrong == 0, "machines (" .. m[1] .. "): with no sheet id every roulette keeps today's drawn machine (dome, glass, base), no image", table.concat(wrong, ", "))
			end)
			T.check(ok, "machines (" .. m[1] .. "): the page builds and lays out", tostring(err))
		end
		LKC.flushErrors("machines_fallback")
	end)

	-- with a sheet id (a fake one here) each roulette is ONE ImageLabel cut from the sheet: its own cell (the four 52 x 60
	-- drawings, the Secret's 60 x 68; each + its 1-cell drop shadow), ResampleMode Pixelated, a whole number of screen px a
	-- cell, inside its machine box, standing on its stage; today's frames are gone. The cells match the sheet's manifest
	S.machines_sheet = guarded("machines_sheet", function()
		local Config = LoadingH.shared("Config")
		local ms = Config and Config.MachineSheet
		if not T.check(type(ms) == "table" and type(ms.Cells) == "table", "machines: Config.MachineSheet exists") then
			return
		end
		local fh = io.open("build/upload_sheets/machines_a.json", "r")
		local json = fh and fh:read("*a") or ""
		if fh then
			fh:close()
		end
		local off = {}
		for _, id in ipairs(MACHINES) do
			local c = ms.Cells[id]
			local block = json:match('"' .. id .. '": (%b{})')
			local j = {}
			for _, k in ipairs({ "x", "y", "w", "h" }) do
				j[#j + 1] = block and tonumber(block:match('"' .. k .. '": (%d+)'))
			end
			if not (type(c) == "table" and c[1] == j[1] and c[2] == j[2] and c[3] == j[3] and c[4] == j[4]) then
				off[#off + 1] = id
			end
		end
		T.check(json ~= "" and #off == 0, "machines: every roulette's cell in Config is the one machines_a.json gives", table.concat(off, ", "))
		local sec = ms.Cells.Secret
		T.check(type(sec) == "table" and sec[3] == 61 and sec[4] == 69 and ms.Cells.Cloud and ms.Cells.Cloud[3] == 53 and ms.Cells.Cloud[4] == 61,
			"machines: the Secret's cell is its 60 x 68 drawing (+ the drop shadow: 61 x 69), the others 52 x 60 (53 x 61)")
		local png = io.open("build/upload_sheets/machines_a.png", "rb")
		local head = png and png:read(24) or ""
		if png then
			png:close()
		end
		local function u32(s, i)
			local a, b, c, d = s:byte(i, i + 3)
			return ((a or 0) * 256 + (b or 0)) * 65536 + (c or 0) * 256 + (d or 0)
		end
		local jw, jh = json:match('"size": %[%s*(%d+),%s*(%d+)%s*%]')
		T.check(head:sub(2, 4) == "PNG" and u32(head, 17) == tonumber(jw) and u32(head, 21) == tonumber(jh),
			"machines: machines_a.png is there, the size its manifest gives", fmt("%s x %s", tostring(jw), tostring(jh)))
		local saved = ms.Id
		ms.Id = 5151515151
		-- (P2 icons review r1, majors 1 - 3) the four screens' real Eggs pages (render_gui dumps): 1920 x 1080 (REF), 1280 x 720
		-- (TIGHT, under the window's 0.8 Fit), 844 x 390 and 390 x 844. Option A's numbers: 3 px cells on PC, 2 px on a phone
		-- and at 1280 (one cell size a screen); the phones show the new machines too (they kept today's: the page showed the
		-- sheet only when every box fit, and no phone box did); the player away from the altar (the Dim's state)
		local function absRect(o)
			return { o.AbsolutePosition.X, o.AbsolutePosition.Y, o.AbsoluteSize.X, o.AbsoluteSize.Y }
		end
		local function meets(a, b2)
			return a[1] < b2[1] + b2[3] - 0.5 and b2[1] < a[1] + a[3] - 0.5 and a[2] < b2[2] + b2[4] - 0.5 and b2[2] < a[2] + a[4] - 0.5
		end
		for _, m in ipairs({ { "PC", { W = 1240, H = 834 }, nil, 3, "PC" }, { "PC 0.8", { W = 1144, H = 683 }, 0.8, 2, "PC" },
			{ "Phone", { W = 692, H = 280 }, nil, 2, "Phone" }, { "Portrait", { W = 350, H = 552 }, nil, 2, "Portrait" } }) do
			local scale, want = m[3] or 1, m[4]
			local ok, err = machinesPage(m[5], m[2], function(roots)
				local wrong, offsets, shown = {}, {}, 0
				for _, id in ipairs(MACHINES) do
					local root = roots[id]
					local art = root and root:FindFirstChild("Art")
					local drawn = root and root:FindFirstChild("Drawn")
					local c = ms.Cells[id]
					local why = ""
					if not (root and root:GetAttribute("Sheet") == true and root:GetAttribute("SheetShown") == true) then
						why = "no sheet machine shown"
					elseif not (art and art:IsA("ImageLabel") and art.Visible) then
						why = "no ImageLabel"
					elseif art.Image ~= "rbxassetid://5151515151" then
						why = "image " .. tostring(art.Image)
					elseif art.ImageRectOffset ~= Vector2.new(c[1], c[2]) or art.ImageRectSize ~= Vector2.new(c[3], c[4]) then
						why = "rect " .. tostring(art.ImageRectOffset) .. " " .. tostring(art.ImageRectSize)
					elseif art.ResampleMode ~= Enum.ResamplerMode.Pixelated then
						why = "not Pixelated"
					else
						local cw = art.Size.X.Offset / c[3]
						local sc = cw * scale
						local rw, rh = root.Size.X.Offset, root.Size.Y.Offset
						local ax, ay = art.Position.X.Offset, art.Position.Y.Offset
						if math.abs(sc - want) > 1e-4 or math.abs(art.Size.Y.Offset - cw * c[4]) > 1e-4 then
							why = fmt("cells %.2f screen px, want %d", sc, want)
						elseif ax < -1e-6 or ay < -1e-6 or ax + art.Size.X.Offset > rw + 1e-4 or ay + art.Size.Y.Offset > rh + 1e-4 then
							why = fmt("art %.1f,%.1f %.1fx%.1f outside its %.1fx%.1f box", ax, ay, art.Size.X.Offset, art.Size.Y.Offset, rw, rh)
						elseif root:FindFirstChild("Dome") or not (drawn and not drawn.Visible) then
							why = "today's drawn machine still shows"
						elseif not (root:FindFirstChild("Stage") and root.Stage.Visible) then
							why = "no stage"
						else
							shown = shown + 1
						end
					end
					-- nothing of the card under the machine's box
					local card = root and root.Parent
					if why == "" and card then
						local mine = absRect(root)
						for _, name in ipairs({ "NamePlate", "Odds", "Spin", "Spin3", "SpinGems", "Hint", "Title", "OddsLine", "PityChip", "AltarChip", "SpinHolder" }) do
							local o = card:FindFirstChild(name)
							if o and o:IsA("GuiObject") and o.Visible and o.AbsoluteSize.X > 0 and meets(mine, absRect(o)) then
								why = "its box meets " .. name
								break
							end
						end
					end
					if why ~= "" then
						wrong[#wrong + 1] = id .. ": " .. why
					end
					offsets[tostring(c and c[1]) .. "," .. tostring(c and c[2])] = true
				end
				local n = 0
				for _ in pairs(offsets) do
					n = n + 1
				end
				T.check(#wrong == 0 and shown == 5, "machines (" .. m[1] .. "): every roulette shows its own sheet cell, one Pixelated ImageLabel at " .. want
					.. " screen px a cell, inside its box on its stage, clear of the card's rows", table.concat(wrong, "; "))
				T.check(n == 5, "machines (" .. m[1] .. "): five roulettes, five different cells (each its own machine)", tostring(n))
				-- (kit-b wave-2 merge: icons item 10 A x world item 13 A minor 5) the landscape phone's away / match line
				-- ("Home first, then the arrow" / "Finish the match first") with the vault drawn: the world lane placed it full
				-- width at y 116, the band the vault now fills, so it moves to the odds column beside the vault (under the
				-- odds, over the altar chip). That column is 72 x 32 on this 692 x 280 page, too small for its 4 wrapped rows,
				-- so here it HIDES rather than overlap the vault or clip (an open layout call for the owner, logged in the merge
				-- report). The check: when it shows, it is inside the card, over the chip, its rows fit; it never shows clipped.
				-- Today's drawn machine (MachineSheet.Id 0, what ships) keeps the full-width line: travel_shows_way checks it.
				if m[1] == "Phone" then
					local hc = roots.Secret and roots.Secret.Parent
					local hint = hc and hc:FindFirstChild("Hint")
					local TX = U7.client("UI/ShopEggs").Metrics.TEXT
					if hint and TX and (hint.Text == TX.HeroHintLobbyShort or hint.Text == TX.HeroHintLocked) then
						local hr, cr = absRect(hint), absRect(hc)
						local ach = hc:FindFirstChild("AltarChip")
						local need = SmokeCommon.RealWidth(hint.Text, hint.TextSize, hint.Font) or hint.TextBounds.X
						local rows = math.ceil(need / math.max(1, hint.Size.X.Offset))
						local roomy = rows * hint.TextSize <= hint.Size.Y.Offset + 2
						local fits = hint.Visible and hr[1] >= cr[1] - 0.5 and hr[1] + hr[3] <= cr[1] + cr[3] + 0.5
							and not (ach and ach.Visible and meets(hr, absRect(ach)))
							and roomy and hint.TextSize >= 14
						T.check(fits or (not hint.Visible and not roomy), "machines (Phone): the away line, beside the vault, shows only where it fits (inside the card, over the altar chip, its rows whole); never clipped",
							fmt("visible %s, %d rows of %d in %.0fx%.0f at %.0f,%.0f", tostring(hint.Visible), rows, hint.TextSize,
								hint.Size.X.Offset, hint.Size.Y.Offset, hint.Position.X.Offset, hint.Position.Y.Offset))
					else
						T.check(false, "machines (Phone): the away line shows beside the vault (the card is away from the lobby)",
							hint and hint.Text or "no Hint")
					end
				end
				-- the hero: ONE bright vault (the mock-up's): the big egg goes, no Dim over it though away from the altar, no
				-- box drawn round it (its stage is the card's own navy)
				local hero = roots.Secret
				local hb = hero and hero.Parent
				local egg = hb and hb:FindFirstChild("HeroEgg")
				local dim = hb and hb:FindFirstChild("Dim")
				local chip = hb and hb:FindFirstChild("AltarChip")
				T.check(chip ~= nil and chip.Visible, "machines (" .. m[1] .. "): the hero shows the away state (the altar chip)")
				T.check(egg ~= nil and not egg.Visible and dim ~= nil and not dim.Visible,
					"machines (" .. m[1] .. "): the vault is the hero's one art: no big egg beside it, no Dim over it",
					fmt("egg %s, dim %s", tostring(egg and egg.Visible), tostring(dim and dim.Visible)))
				local stage = hero and hero:FindFirstChild("Stage")
				local face = stage and stage:FindFirstChild("Face")
				T.check(stage ~= nil and stage.BackgroundTransparency >= 0.99 and face ~= nil and face.BackgroundTransparency >= 0.99,
					"machines (" .. m[1] .. "): the vault stands on the card's navy (no stage box round it)")
				if m[5] == "Portrait" and hb then
					-- (P2 icons review r1, minor: an empty navy band of about 30 px under "Travel from the lobby", beside the
					-- vault, over the Travel bar) the mock-up's column (10_optA_phone): the two odds one over the other, the
					-- altar chip and the hint run down the vault's height, the bar 20 px or less under the hint; nothing meets
					local rows, hint, bar = {}, hb:FindFirstChild("Hint"), hb:FindFirstChild("SpinHolder")
					local oddsLine = hb:FindFirstChild("OddsLine")
					for _, r in ipairs(oddsLine and oddsLine:GetChildren() or {}) do
						if r:IsA("Frame") and r.Name:match("^Odds_") and r.Visible then
							rows[#rows + 1] = absRect(r)
						end
					end
					local stacked = #rows == 2 and math.abs(rows[1][1] - rows[2][1]) <= 1 and rows[2][2] >= rows[1][2] + rows[1][4] - 0.5
					local h, b = hint and absRect(hint), bar and absRect(bar)
					local gap = (h and b) and (b[2] - (h[2] + h[4])) or 999
					local clear = h and chip and not meets(h, absRect(chip)) and rows[2] and not meets(absRect(chip), rows[2])
					T.check(stacked and gap <= 20 and gap >= 0 and clear, "machines (Portrait): the hero's odds stacked, the altar chip and the hint run down beside the vault, the bar 20 px or less under the hint",
						fmt("rows %d stacked %s, hint-to-bar %.0f px, clear %s", #rows, tostring(stacked), gap, tostring(clear)))
				end
				if m[5] == "PC" then
					-- the cards: the stage spans the name plate's width, the odds are egg chips, the hint 12 px further up
					local chips, lifted, span = {}, {}, {}
					for _, id in ipairs({ "Cloud", "Storm", "Sky", "Celestial" }) do
						local root = roots[id]
						local card = root and root.Parent
						local plate = card and card:FindFirstChild("NamePlate")
						if not (plate and math.abs(root.AbsoluteSize.X - plate.AbsoluteSize.X) <= 1 and math.abs(root.AbsolutePosition.X - plate.AbsolutePosition.X) <= 1) then
							span[#span + 1] = id
						end
						local odds = card and card:FindFirstChild("Odds")
						local rows = 0
						for _, row in ipairs(odds and odds:GetChildren() or {}) do
							if row:IsA("Frame") and row.Name:match("^Odds_") then
								rows = rows + 1
								local word = row:FindFirstChild("Word")
								if row.BackgroundTransparency > 0.5 or (word and word.Visible) or not row:FindFirstChild("Egg") then
									chips[#chips + 1] = id .. "." .. row.Name
								end
							end
						end
						if rows == 0 then
							chips[#chips + 1] = id .. ": no odds"
						end
						local hint = card and card:FindFirstChild("Hint")
						local cardRoot = card and card.Parent
						local foot = cardRoot and cardRoot.AbsolutePosition.Y + cardRoot.AbsoluteSize.Y
						if not (hint and foot and hint.AbsolutePosition.Y + hint.AbsoluteSize.Y <= foot - 20 * scale + 0.5) then
							lifted[#lifted + 1] = id
						end
					end
					T.check(#span == 0, "machines (" .. m[1] .. "): each card's stage spans its name plate's width", table.concat(span, ", "))
					T.check(#chips == 0, "machines (" .. m[1] .. "): each card's odds are egg chips (a stone block, the egg, the percent)", table.concat(chips, ", "))
					T.check(#lifted == 0, "machines (" .. m[1] .. "): the 'Gems: same odds' line ends 20 px over the card's foot (its lip 12 px clear)", table.concat(lifted, ", "))
				end
				if m[1] == "PC" then
					-- today's drawn machine under a sheet one (shown when a smaller window can't fit the sheet) keeps its
					-- 200 x 230 shape at the plan's art size, standing at the foot of the box, never stretched to the stage
					local root = roots.Cloud
					local drawn = root and root:FindFirstChild("Drawn")
					T.check(drawn ~= nil and drawn.Size.X.Scale == 0 and drawn.Size.Y.Scale == 0
						and math.abs(drawn.Size.Y.Offset - math.floor(drawn.Size.X.Offset * 1.15 + 0.5)) <= 1 and drawn.Size.Y.Offset <= root.Size.Y.Offset,
						"machines (PC): the fallback drawing keeps its own shape in the wider stage", drawn and tostring(drawn.Size) or "no Drawn")
				end
			end, m[3], true)
			T.check(ok, "machines (" .. m[1] .. "): the page builds and lays out with a sheet id", tostring(err))
		end
		ms.Id = saved
		LKC.flushErrors("machines_sheet")
	end)

	-- (P2 icons look fin1, major: on the portrait phone, 390 x 844 with the machines sheet, the Secret hero's hint beside
	-- the vault was a 188 x 20 box at 15 px, one line, cut: "Travel flies you to the St..." in the lobby, "Secret rolls
	-- happen at th..." on a restricted account; the gate's default render is the away state, so nobody saw it) every hero
	-- hint state on every screen, with the machines sheet and without: restricted, still checking, held by a match, away
	-- from the lobby, in the lobby away from the altar, at the altar. The hint reads the state's line; where it shows, it
	-- reads in full: at the text floor or more (14 screen px on a PC, 15 on a phone, as client_shop_secret_lock), its rows
	-- (word-wrapped when the label wraps, else one) inside its box, inside the card,
	-- clear of the chip, the lock line, the odds and the button. On a PC and in portrait it always shows (the landscape
	-- phone may hide it where no row fits: the kit-b wave-2 merge's call, machines_sheet). Widths: Builder Sans Bold's real
	-- advances x 1.02 (the Body face, Nunito ExtraBold, measures about 1.015 x Builder in render_gui's real font). The
	-- 320-wide page is a 360 x 640 phone's
	S.machines_hero_hints = guarded("machines_hero_hints", function()
		local Config = LoadingH.shared("Config")
		local Theme = LoadingH.shared("Theme")
		local ms = Config and Config.MachineSheet
		local SE = U7.client("UI/ShopEggs")
		local TX = SE and SE.Metrics and SE.Metrics.TEXT
		if not T.check(type(ms) == "table" and TX ~= nil, "hero hints: Config.MachineSheet and ShopEggs.Metrics.TEXT exist") then
			return
		end
		local lp = game:GetService("Players").LocalPlayer
		local RealWidth = SmokeCommon.RealWidth
		local function absRect(o)
			return { o.AbsolutePosition.X, o.AbsolutePosition.Y, o.AbsoluteSize.X, o.AbsoluteSize.Y }
		end
		local function meets(a, b2)
			return a[1] < b2[1] + b2[3] - 0.5 and b2[1] < a[1] + a[3] - 0.5 and a[2] < b2[2] + b2[4] - 0.5 and b2[2] < a[2] + a[4] - 0.5
		end
		local function shown(o, top)
			while o and o ~= top do
				if o:IsA("GuiObject") and not o.Visible then
					return false
				end
				o = o.Parent
			end
			return true
		end
		-- the rows a label's text takes at its size in its box (greedy word wrap when it wraps), and its widest row
		local function rowsOf(hint)
			local size, font = hint.TextSize, Theme.FontOf(hint)
			local function w(s)
				return (RealWidth(s, size, font, true) or Theme.MeasureLabel(hint, s, size).X) * 1.02
			end
			local room = hint.Size.X.Offset
			if not hint.TextWrapped then
				return 1, w(hint.Text)
			end
			local rows, line, widest = 0, nil, 0
			for word in hint.Text:gmatch("%S+") do
				local try = line and (line .. " " .. word) or word
				if line and w(try) > room then
					rows, line = rows + 1, word
				else
					line = try
				end
				widest = math.max(widest, w(line))
			end
			return rows + (line and 1 or 0), widest
		end
		-- the screen rect a label's text covers: its rows' height centred in the box, its widest row placed by its X alignment
		local function textRect(o)
			local r = absRect(o)
			local k = o.AbsoluteSize.X / math.max(1, o.Size.X.Offset)
			local rows, wide = rowsOf(o)
			local tw, th = math.min(r[3], wide * k), rows * o.TextSize * k
			local x = r[1] + (r[3] - tw) / 2
			if o.TextXAlignment == Enum.TextXAlignment.Left then
				x = r[1]
			elseif o.TextXAlignment == Enum.TextXAlignment.Right then
				x = r[1] + r[3] - tw
			end
			return { x, r[2] + (r[4] - th) / 2, tw, th }
		end
		local STATES = {
			{ "restricted", TX.HeroHint, true, nil, nil, false },
			{ "checking", TX.HeroHint, nil, nil, nil, false },
			{ "held by a match", TX.HeroHintLocked, false, false, false, true },
			{ "away from the lobby", "away", false, false, false, false },
			{ "in the lobby", TX.HeroHintTravel, false, false, true, false },
			{ "at the altar", TX.HeroHintHere, false, true, true, false },
		}
		local SCREENS = { { "PC", { W = 1240, H = 834 }, nil, "PC" }, { "PC 0.8", { W = 1144, H = 683 }, 0.8, "PC" },
			{ "Phone", { W = 692, H = 280 }, nil, "Phone" }, { "Portrait", { W = 350, H = 552 }, nil, "Portrait" },
			{ "Portrait 360", { W = 320, H = 552 }, nil, "Portrait" } }
		local saved = ms.Id
		for _, sheetId in ipairs({ 5151515151, 0 }) do
			ms.Id = sheetId
			local look = sheetId > 0 and "sheet" or "drawn"
			for _, m in ipairs(SCREENS) do
				local ok, err = machinesPage(m[4], m[2], function(roots)
					local hero = roots.Secret and roots.Secret.Parent
					local hint = hero and hero:FindFirstChild("Hint")
					local page = hero and hero:FindFirstAncestor("Page_Eggs")
					if not T.check(hint ~= nil and page ~= nil, "hero hints (" .. m[1] .. ", " .. look .. "): the Secret hero has its Hint") then
						return
					end
					local old = { lp:GetAttribute("PaidRandomItemsRestricted"), lp:GetAttribute("InMatch"), SE._AtAltar, SE._InLobby }
					local wrong = {}
					for _, st in ipairs(STATES) do
						lp:SetAttribute("PaidRandomItemsRestricted", st[3])
						lp:SetAttribute("InMatch", st[6] or nil)
						SE._AtAltar = st[4]
						SE._InLobby = st[5]
						SE.Refresh(page)
						LKC.advance(0.05)
						local want = st[2]
						if want == "away" then
							want = (m[4] == "PC") and TX.HeroHintLobby or TX.HeroHintLobbyShort
						end
						local why = ""
						if hint.Text ~= want then
							why = fmt("reads '%s', want '%s'", hint.Text, tostring(want))
						elseif not shown(hint, page) then
							if m[4] ~= "Phone" then
								why = "hidden"
							end
						else
							local rows, widest = rowsOf(hint)
							local bw, bh = hint.Size.X.Offset, hint.Size.Y.Offset
							local hr, cr = absRect(hint), absRect(hero)
							local px, floor = hint.TextSize * (m[3] or 1), (m[4] == "PC") and 14 or 15
							if px < floor - 1e-6 then
								why = fmt("%.1f screen px (floor %d)", px, floor)
							elseif widest > bw + 0.5 or rows * hint.TextSize > bh + 1 then
								why = fmt("%d row(s) of %d px, widest %.1f, in a %.0f x %.0f box (wrapped %s)", rows, hint.TextSize, widest, bw, bh, tostring(hint.TextWrapped))
							elseif hr[1] < cr[1] - 0.5 or hr[1] + hr[3] > cr[1] + cr[3] + 0.5 or hr[2] < cr[2] - 0.5 or hr[2] + hr[4] > cr[2] + cr[4] + 0.5 then
								why = "outside the card"
							else
								for _, name in ipairs({ "AltarChip", "Lock", "OddsLine", "PityChip", "SpinHolder" }) do
									local o = hero:FindFirstChild(name)
									if o and o:IsA("GuiObject") and shown(o, page) and o.AbsoluteSize.X > 0 then
										local orect, mine = absRect(o), hr
										if name == "Lock" then
											-- the lock line is bare text (no plank), left-aligned, its rows centred in a box
											-- taller than them, and so is the hint: on a PC the two BOXES cross while the
											-- lock's text stops ~15 px left of the hint's (seen in the 1920 / 1280 renders),
											-- so the two TEXTS are what must stay apart
											orect, mine = textRect(o), textRect(hint)
										end
										if meets(mine, orect) then
											why = "meets " .. name
											break
										end
									end
								end
							end
						end
						if why ~= "" then
							wrong[#wrong + 1] = st[1] .. ": " .. why
						end
					end
					lp:SetAttribute("PaidRandomItemsRestricted", old[1])
					lp:SetAttribute("InMatch", old[2])
					SE._AtAltar, SE._InLobby = old[3], old[4]
					T.check(#wrong == 0, "hero hints (" .. m[1] .. ", " .. look .. "): every state's hint reads its line in full (rows inside its box, at the text floor or more, clear of the chip, lock, odds and button)",
						table.concat(wrong, "; "))
				end, m[3], false)
				T.check(ok, "hero hints (" .. m[1] .. ", " .. look .. "): the page builds and lays out", tostring(err))
			end
		end
		ms.Id = saved
		LKC.flushErrors("machines_hero_hints")
	end)

	-- (P2 icons review r1, major 1: under the 3 px pixel machines the odds chips drew today's smooth vector EggArt; minor:
	-- at 1280 the chips were cramped, "60%" 0.4 px from the wood and the egg 1.6 px from it) with the machines sheet each
	-- card's odds chip holds a hand-pixelled egg, the mock-up's (10_optA: make_item10.odds_egg): "PixelEgg", the rarity's
	-- "egg_<rarity>" drawn at the screen's one cell size (3 screen px at 1920, 2 at 1280 and on a phone) and cut from the
	-- machines sheet's egg row (Config.MachineSheet.Eggs, the cells machines_a.json gives) as one Pixelated ImageLabel; the
	-- EggArt egg hidden. The egg (its drop shadow too) and the percent both inside the chip's face, apart, the percent's
	-- text 2 px or more clear of the chip's sides. Without an egg cell (a sheet with no egg row) the same egg draws as the
	-- 9 x 9 PixelIcon glyph in Frames
	S.machines_egg_chips = guarded("machines_egg_chips", function()
		local Config = LoadingH.shared("Config")
		local Theme = LoadingH.shared("Theme")
		local ms = Config and Config.MachineSheet
		if not T.check(type(ms) == "table" and type(ms.Eggs) == "table", "egg chips: Config.MachineSheet.Eggs gives each rarity's egg cell in the sheet") then
			return
		end
		local fh = io.open("build/upload_sheets/machines_a.json", "r")
		local json = fh and fh:read("*a") or ""
		if fh then
			fh:close()
		end
		local eggsJson = json:match('"eggs": (%b{})') or ""
		local off = {}
		for _, r in ipairs({ "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Secret" }) do
			local c = ms.Eggs[r]
			local block = eggsJson:match('"' .. r .. '": (%b{})')
			local j = {}
			for _, k in ipairs({ "x", "y", "w", "h" }) do
				j[#j + 1] = block and tonumber(block:match('"' .. k .. '": (%d+)'))
			end
			if not (type(c) == "table" and c[1] == j[1] and c[2] == j[2] and c[3] == j[3] and c[4] == j[4] and c[3] == 10 and c[4] == 10) then
				off[#off + 1] = r
			end
		end
		T.check(eggsJson ~= "" and #off == 0, "egg chips: each rarity's 10 x 10 egg cell (9 x 9 + the drop shadow) in Config is the one machines_a.json gives",
			table.concat(off, ", "))
		local saved = ms.Id
		ms.Id = 5151515151
		-- (P2 icons look fin1) the page lays its chips out with the real faces' widths, as TextService gives them in the game
		-- (ShopEggs.Metrics.MEASURE, the hook render_gui uses too): with the mock's flat 0.5 em a 36 px phone chip put "60%"
		-- over its egg here while the game put it beside the egg, cut to "..."
		local SEm = U7.client("UI/ShopEggs").Metrics
		local savedMeasure = SEm.MEASURE
		SEm.MEASURE = function(text, size, font)
			return SmokeCommon.RealWidth(text, size, font)
		end
		-- the drawn box of an icon (its Frames or its ImageLabel) in its row's design px
		local function drawn(icon)
			local x0, y0, x1, y1 = math.huge, math.huge, -math.huge, -math.huge
			for _, d in ipairs(icon:GetChildren()) do
				if d:IsA("GuiObject") and d.Visible then
					local x, y = icon.Position.X.Offset + d.Position.X.Offset, icon.Position.Y.Offset + d.Position.Y.Offset
					x0, y0 = math.min(x0, x), math.min(y0, y)
					x1, y1 = math.max(x1, x + d.Size.X.Offset), math.max(y1, y + d.Size.Y.Offset)
				end
			end
			return x0, y0, x1, y1
		end
		local function chipsOf(roots, fn)
			for _, id in ipairs({ "Cloud", "Storm", "Sky", "Celestial" }) do
				local root = roots[id]
				local odds = root and root.Parent and root.Parent:FindFirstChild("Odds")
				for _, row in ipairs(odds and odds:GetChildren() or {}) do
					if row:IsA("Frame") and row.Name:match("^Odds_") then
						fn(id, row, row.Name:sub(6))
					end
				end
			end
		end
		for _, m in ipairs({ { "PC", { W = 1240, H = 834 }, nil, 3, "PC" }, { "PC 0.8", { W = 1144, H = 683 }, 0.8, 2, "PC" },
			{ "Phone", { W = 692, H = 280 }, nil, 2, "Phone" }, { "Portrait", { W = 350, H = 552 }, nil, 2, "Portrait" } }) do
			local want = m[4]
			local ok, err = machinesPage(m[5], m[2], function(roots)
				local wrong, cramped, n = {}, {}, 0
				chipsOf(roots, function(id, row, r)
					n = n + 1
					local tag = id .. "." .. r
					local egg, pix, pct = row:FindFirstChild("Egg"), row:FindFirstChild("PixelEgg"), row:FindFirstChild("Pct")
					local art = pix and pix:FindFirstChild("Art")
					local c = ms.Eggs[r]
					local why = ""
					if egg and egg.Visible then
						why = "the vector EggArt egg still shows"
					elseif not (pix and pix.Visible and pix:GetAttribute("PixelIcon") == "egg_" .. r:lower()) then
						why = "no pixel egg egg_" .. r:lower()
					elseif not (art and art:IsA("ImageLabel") and art.Image == "rbxassetid://5151515151") then
						why = "not cut from the machines sheet"
					elseif art.ImageRectOffset ~= Vector2.new(c[1], c[2]) or art.ImageRectSize ~= Vector2.new(c[3], c[4]) then
						why = "rect " .. tostring(art.ImageRectOffset) .. " " .. tostring(art.ImageRectSize)
					elseif art.ResampleMode ~= Enum.ResamplerMode.Pixelated then
						why = "not Pixelated"
					elseif pix:GetAttribute("CellPx") ~= want then
						why = fmt("%s screen px a cell, want %d", tostring(pix:GetAttribute("CellPx")), want)
					end
					if why ~= "" then
						wrong[#wrong + 1] = tag .. ": " .. why
						return
					end
					-- the egg and the percent inside the chip's face (over its 3 px lip), apart, the text 2 px clear of the sides
					local cw, chh = row.Size.X.Offset, row.Size.Y.Offset
					local ex0, ey0, ex1, ey1 = drawn(pix)
					-- (P2 icons look fin1: the mock's flat 0.5 em measure let a 36 px phone chip pass while the real
					-- FredokaOne "60%" (30 px) went to the side and cut to "...") the wider of the mock's and the real face's
					local tw = math.max(Theme.Measure(pct.Text, Theme.FontOf(pct), pct.TextSize, 10000).X,
						SmokeCommon.RealWidth(pct.Text, pct.TextSize, Theme.FontOf(pct), true) or 0)
					local px, pw = pct.Position.X.Offset, pct.Size.X.Offset
					local tx0 = pct.TextXAlignment == Enum.TextXAlignment.Center and px + (pw - tw) / 2
						or (pct.TextXAlignment == Enum.TextXAlignment.Right and px + pw - tw or px)
					local ty0 = pct.Position.Y.Offset + (pct.Size.Y.Offset - pct.TextSize) / 2
					local tx1, ty1 = tx0 + tw, ty0 + pct.TextSize
					local apart = ex1 <= tx0 + 0.01 or tx1 <= ex0 + 0.01 or ey1 <= ty0 + 0.01 or ty1 <= ey0 + 0.01
					-- (the egg a screen px or more under the chip's top: at 1280 it first sat on the wood)
					if not (ex0 >= 2 - 0.01 and ey0 >= 1 / (m[3] or 1) - 0.01 and ex1 <= cw - 2 + 0.01 and ey1 <= chh - 3 + 0.01) then
						cramped[#cramped + 1] = fmt("%s: egg %.1f,%.1f..%.1f,%.1f in a %dx%d chip", tag, ex0, ey0, ex1, ey1, cw, chh)
					elseif not (tx0 >= 2 - 0.01 and tx1 <= cw - 2 + 0.01 and ty0 >= -0.01 and ty1 <= chh - 3 + 0.01 and pct.Visible) then
						cramped[#cramped + 1] = fmt("%s: '%s' %.1f..%.1f (%.1f wide) in a %d px chip", tag, pct.Text, tx0, tx1, tw, cw)
					elseif not apart then
						cramped[#cramped + 1] = fmt("%s: egg %.1f,%.1f..%.1f,%.1f meets '%s' %.1f,%.1f..%.1f,%.1f", tag, ex0, ey0, ex1, ey1, pct.Text, tx0, ty0, tx1, ty1)
					end
				end)
				T.check(n >= 16 and #wrong == 0, "egg chips (" .. m[1] .. "): every odds chip holds its rarity's pixel egg cut from the machines sheet at "
					.. want .. " screen px a cell (the vector egg hidden)", fmt("%d chips | ", n) .. table.concat(wrong, "; ", 1, math.min(#wrong, 6)))
				T.check(n >= 16 and #cramped == 0, "egg chips (" .. m[1] .. "): the egg and the percent inside each chip's face, apart, the text 2 px clear of the wood",
					table.concat(cramped, "; ", 1, math.min(#cramped, 6)))
				-- (P2 icons look fin0, major 1: at 1280 the percents went 18 -> 17, 13.6 screen px, under render_gui's 14 px
				-- readability floor) every percent 14 screen px or more. (minor: the chips sat fused to the Spin plank, 1 px of
				-- cream at 1920, the borders overlapping at 1280 and 844 x 390; the mock-up 10_optA has about 6 px) the chips'
				-- wood edge 3 screen px or more over the Spin plank's (5 at 1920, the mock-up's gap), both UIStrokes counted
				local scale = m[3] or 1
				local small, fused = {}, {}
				local function strokeOf(o)
					local st = o and o:FindFirstChildOfClass("UIStroke")
					return st and st.Enabled ~= false and st.Thickness or 0
				end
				chipsOf(roots, function(id, row, r)
					local pct = row:FindFirstChild("Pct")
					if pct and pct.Visible and pct.TextSize * scale < 14 - 1e-6 then
						small[#small + 1] = fmt("%s.%s %.1f px", id, r, pct.TextSize * scale)
					end
				end)
				local need = m[1] == "PC" and 5 or 3
				for _, id in ipairs({ "Cloud", "Storm", "Sky", "Celestial" }) do
					local body = roots[id] and roots[id].Parent
					local odds, spin = body and body:FindFirstChild("Odds"), body and body:FindFirstChild("Spin")
					local low, ts = -math.huge, 0
					for _, row in ipairs(odds and odds:GetChildren() or {}) do
						if row:IsA("Frame") and row.Name:match("^Odds_") and row.Visible then
							low = math.max(low, row.AbsolutePosition.Y + row.AbsoluteSize.Y)
							ts = math.max(ts, strokeOf(row))
						end
					end
					if spin and low > -math.huge then
						local gap = (spin.AbsolutePosition.Y - strokeOf(spin) * scale) - (low + ts * scale)
						if gap < need - 0.01 then
							fused[#fused + 1] = fmt("%s %.1f px", id, gap)
						end
					end
				end
				T.check(n >= 16 and #small == 0, "egg chips (" .. m[1] .. "): every percent 14 screen px or more (the readability floor)",
					table.concat(small, "; ", 1, math.min(#small, 6)))
				T.check(#fused == 0, "egg chips (" .. m[1] .. "): the chips' wood edge " .. need .. " screen px or more over the Spin plank's (not fused to it)",
					table.concat(fused, "; "))
				-- (P2 icons look fin1, minor: at 844 x 390 the 2 x 2 chips had 0 px of cream between them, their wood edges
				-- fused into one 4 px line, and the name plate's edge touched the grid) cream between neighbouring chips'
				-- wood edges (both UIStrokes counted, screen px): 3 or more on the landscape phone (the phone mock-up has
				-- about 7), and the name plate's edge 3 or more over the grid there; elsewhere never fused (1 or more:
				-- 2 at 1920 and 390, ~1 at 1280, the chips' gap left as it is)
				local apartNeed = m[1] == "Phone" and 3 or 1
				local tight = {}
				local function edgeGap(a, b2)
					local ta, tb = strokeOf(a) * scale, strokeOf(b2) * scale
					local ax0, ay0 = a.AbsolutePosition.X - ta, a.AbsolutePosition.Y - ta
					local ax1, ay1 = a.AbsolutePosition.X + a.AbsoluteSize.X + ta, a.AbsolutePosition.Y + a.AbsoluteSize.Y + ta
					local bx0, by0 = b2.AbsolutePosition.X - tb, b2.AbsolutePosition.Y - tb
					local bx1, by1 = b2.AbsolutePosition.X + b2.AbsoluteSize.X + tb, b2.AbsolutePosition.Y + b2.AbsoluteSize.Y + tb
					return math.max(bx0 - ax1, ax0 - bx1, by0 - ay1, ay0 - by1)
				end
				for _, id in ipairs({ "Cloud", "Storm", "Sky", "Celestial" }) do
					local body = roots[id] and roots[id].Parent
					local odds = body and body:FindFirstChild("Odds")
					local rows = {}
					for _, row in ipairs(odds and odds:GetChildren() or {}) do
						if row:IsA("Frame") and row.Name:match("^Odds_") and row.Visible then
							rows[#rows + 1] = row
						end
					end
					for i = 1, #rows do
						for j = i + 1, #rows do
							local g = edgeGap(rows[i], rows[j])
							if g < apartNeed - 0.01 then
								tight[#tight + 1] = fmt("%s %s|%s %.1f px", id, rows[i].Name:sub(6), rows[j].Name:sub(6), g)
							end
						end
					end
					local plate = body and body:FindFirstChild("NamePlate")
					if m[1] == "Phone" and plate and plate.Visible then
						for _, row in ipairs(rows) do
							local g = edgeGap(plate, row)
							if g < apartNeed - 0.01 then
								tight[#tight + 1] = fmt("%s plate|%s %.1f px", id, row.Name:sub(6), g)
							end
						end
					end
				end
				T.check(#tight == 0, "egg chips (" .. m[1] .. "): " .. apartNeed .. " screen px or more of cream between neighbouring chips' wood edges"
					.. (m[1] == "Phone" and " and under the name plate's" or ""), table.concat(tight, "; ", 1, math.min(#tight, 6)))
			end, m[3], true)
			T.check(ok, "egg chips (" .. m[1] .. "): the page builds and lays out", tostring(err))
		end
		-- a sheet with no egg row: the same egg as the 9 x 9 glyph in Frames, own colours, at the screen's cell
		local eggs = ms.Eggs
		ms.Eggs = nil
		local ok, err = machinesPage("Portrait", { W = 350, H = 552 }, function(roots)
			local wrong, n = {}, 0
			chipsOf(roots, function(id, row, r)
				n = n + 1
				local pix = row:FindFirstChild("PixelEgg")
				local frames = 0
				for _, d in ipairs(pix and pix:GetChildren() or {}) do
					if d:IsA("Frame") then
						frames = frames + 1
					elseif d:IsA("ImageLabel") then
						frames = -1000
					end
				end
				if not (pix and pix.Visible and pix:GetAttribute("PixelIcon") == "egg_" .. r:lower() and pix:GetAttribute("Own") == true and frames > 0 and pix:GetAttribute("CellPx") == 2) then
					wrong[#wrong + 1] = id .. "." .. r
				end
			end)
			T.check(n >= 16 and #wrong == 0, "egg chips (no egg cell): each chip's egg is the 9 x 9 glyph in its own colours, Frames, 2 px cells", table.concat(wrong, ", "))
		end, nil, true)
		T.check(ok, "egg chips (no egg cell): the page builds and lays out", tostring(err))
		ms.Eggs = eggs
		ms.Id = saved
		SEm.MEASURE = savedMeasure
		LKC.flushErrors("machines_egg_chips")
	end)

	return S
end

if (ARGS and ARGS.context or "server") == "server" then
	return serverScenarios()
end
return clientScenarios()
